// ===============================
// ADMIN ROOT PAGE
// Redirects to admin dashboard or login
// =============================

"use client";

import { useEffect, useState } from "react";
import { useRouter } from "next/navigation";
import { authService } from "@/services";

export default function AdminPage() {
  const router = useRouter();
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    const user = authService.getCurrentUser();
    setIsLoading(false);

    if (user?.role === "admin") {
      router.replace("/admin/dashboard");
    } else {
      router.replace("/admin/login");
    }
  }, [router]);

  if (isLoading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-[#F0F5FF]">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary-500"></div>
      </div>
    );
  }

  return null;
}

"use client";

import { useEffect, useState, useCallback } from "react";
import { AdminLayout } from "@/components";
import {
  paymentService,
  Transaction,
  TransactionStats,
  TransactionFilters,
} from "@/services/api/payment.service";

// Status config
const STATUS_CONFIG: Record<
  string,
  { label: string; color: string; bgColor: string }
> = {
  pending: { label: "Pending", color: "#D97706", bgColor: "#FEF3C7" },
  processing: { label: "Processing", color: "#3B82F6", bgColor: "#DBEAFE" },
  completed: { label: "Completed", color: "#059669", bgColor: "#D1FAE5" },
  failed: { label: "Failed", color: "#DC2626", bgColor: "#FEE2E2" },
  refunded: { label: "Refunded", color: "#7C3AED", bgColor: "#EDE9FE" },
  partially_refunded: {
    label: "Partial Refund",
    color: "#8B5CF6",
    bgColor: "#EDE9FE",
  },
  released: { label: "Released", color: "#10B981", bgColor: "#D1FAE5" },
  held: { label: "Held", color: "#F59E0B", bgColor: "#FEF3C7" },
  cancelled: { label: "Cancelled", color: "#6B7280", bgColor: "#F3F4F6" },
};

const TYPE_CONFIG: Record<string, { label: string; icon: string }> = {
  payment: { label: "Payment", icon: "💳" },
  payout: { label: "Payout", icon: "🏦" },
  refund: { label: "Refund", icon: "↩️" },
  platform_fee: { label: "Platform Fee", icon: "📊" },
};

export default function AdminPaymentsPage() {
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [stats, setStats] = useState<TransactionStats | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [successMessage, setSuccessMessage] = useState<string | null>(null);
  const [selectedTransaction, setSelectedTransaction] =
    useState<Transaction | null>(null);
  const [actionLoading, setActionLoading] = useState<string | null>(null);

  // Filters & pagination
  const [filters, setFilters] = useState<TransactionFilters>({
    page: 1,
    limit: 15,
  });
  const [totalPages, setTotalPages] = useState(1);
  const [totalCount, setTotalCount] = useState(0);
  const [searchQuery, setSearchQuery] = useState("");

  // Refund modal
  const [showRefundModal, setShowRefundModal] = useState(false);
  const [refundTarget, setRefundTarget] = useState<Transaction | null>(null);
  const [refundAmount, setRefundAmount] = useState("");
  const [refundReason, setRefundReason] = useState("");

  const fetchData = useCallback(async () => {
    setIsLoading(true);
    setError(null);
    try {
      const [txRes, statsRes] = await Promise.all([
        paymentService.getAllTransactions(filters),
        paymentService.getTransactionStats(),
      ]);

      if (txRes.success && txRes.data) {
        setTransactions(txRes.data.transactions);
        setTotalPages(txRes.data.pagination?.pages || 1);
        setTotalCount(txRes.data.pagination?.total || 0);
      }
      if (statsRes.success && statsRes.data) {
        setStats(statsRes.data.stats);
      }
    } catch {
      setError("Failed to load payment data.");
    } finally {
      setIsLoading(false);
    }
  }, [filters]);

  useEffect(() => {
    fetchData();
  }, [fetchData]);

  useEffect(() => {
    if (!successMessage) return;
    const t = setTimeout(() => setSuccessMessage(null), 4000);
    return () => clearTimeout(t);
  }, [successMessage]);

  const handleRelease = async (bookingId: string) => {
    setActionLoading(bookingId);
    try {
      const res = await paymentService.releasePayment(bookingId);
      if (res.success) {
        setSuccessMessage("Payment released successfully.");
        setSelectedTransaction(null);
        fetchData();
      } else {
        setError(res.message || "Failed to release payment.");
      }
    } catch {
      setError("Failed to release payment.");
    } finally {
      setActionLoading(null);
    }
  };

  const handleRefundSubmit = async () => {
    if (!refundTarget) return;
    const bookingId =
      typeof refundTarget.bookingId === "string"
        ? refundTarget.bookingId
        : (refundTarget.bookingId as { _id: string })?._id;
    if (!bookingId) return;

    const normalizedReason = refundReason.trim();
    if (!normalizedReason) {
      setError("Refund reason is required.");
      return;
    }

    const parsedAmount = refundAmount.trim() ? Number.parseFloat(refundAmount) : undefined;
    if (
      parsedAmount !== undefined &&
      (!Number.isFinite(parsedAmount) || parsedAmount <= 0)
    ) {
      setError("Refund amount must be a valid positive number.");
      return;
    }

    setActionLoading(bookingId);
    try {
      const refundPayload = {
        ...(parsedAmount !== undefined ? { amount: parsedAmount } : {}),
        reason: normalizedReason,
      };
      const res = await paymentService.processRefund(bookingId, refundPayload);
      if (res.success) {
        setSuccessMessage("Refund processed successfully.");
        setShowRefundModal(false);
        setRefundTarget(null);
        setRefundAmount("");
        setRefundReason("");
        setSelectedTransaction(null);
        fetchData();
      } else {
        setError(res.message || "Failed to process refund.");
      }
    } catch (err: unknown) {
      const message =
        err &&
        typeof err === "object" &&
        "message" in err &&
        typeof (err as { message?: unknown }).message === "string"
          ? (err as { message: string }).message
          : "Failed to process refund.";
      setError(message);
    } finally {
      setActionLoading(null);
    }
  };

  const formatCurrency = (amount: number, currency = "NPR") => {
    if (currency === "NPR") {
      return `Rs. ${new Intl.NumberFormat("en-NP", {
        minimumFractionDigits: 2,
        maximumFractionDigits: 2,
      }).format(amount)}`;
    }
    return new Intl.NumberFormat("en-US", { style: "currency", currency }).format(amount);
  };

  const formatDate = (date: string) =>
    new Date(date).toLocaleDateString("en-US", {
      year: "numeric",
      month: "short",
      day: "numeric",
      hour: "2-digit",
      minute: "2-digit",
    });

  const getStatusBadge = (status: string) => {
    const config = STATUS_CONFIG[status] || {
      label: status,
      color: "#6B7280",
      bgColor: "#F3F4F6",
    };
    return (
      <span
        className="px-2.5 py-0.5 rounded-full text-xs font-medium"
        style={{ color: config.color, backgroundColor: config.bgColor }}
      >
        {config.label}
      </span>
    );
  };

  const getUserName = (
    user: string | { _id?: string; fullName?: string; email?: string }
  ) => {
    if (typeof user === "string") return user;
    return user.fullName || user.email || user._id || "Unknown";
  };

  return (
    <AdminLayout>
      <div className="space-y-6">
        {/* Header */}
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-2xl font-bold text-gray-900">
              Payment Management
            </h1>
            <p className="text-sm text-gray-500 mt-1">
              Manage transactions, releases, and refunds
            </p>
          </div>
          <button
            onClick={() => fetchData()}
            disabled={isLoading}
            className="px-4 py-2 text-sm font-medium text-white bg-primary-500 rounded-lg hover:bg-[#2F4BDB] disabled:opacity-50 flex items-center gap-2"
          >
            <svg
              className={`w-4 h-4 ${isLoading ? "animate-spin" : ""}`}
              fill="none"
              stroke="currentColor"
              viewBox="0 0 24 24"
            >
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth={2}
                d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15"
              />
            </svg>
            Refresh
          </button>
        </div>

        {/* Messages */}
        {successMessage && (
          <div className="bg-green-50 border border-green-200 text-green-700 px-4 py-3 rounded-xl text-sm">
            {successMessage}
          </div>
        )}
        {error && (
          <div className="bg-red-50 border border-red-200 text-red-700 px-4 py-3 rounded-xl text-sm flex justify-between items-center">
            {error}
            <button
              onClick={() => setError(null)}
              className="text-red-500 hover:text-red-700"
            >
              ✕
            </button>
          </div>
        )}

        {/* Stats Cards */}
        {stats && (
          <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
            <StatCard
              label="Total Volume"
              value={formatCurrency(stats.totalVolume || 0)}
              icon="💰"
            />
            <StatCard
              label="Total Transactions"
              value={String(stats.totalTransactions || 0)}
              icon="📊"
            />
            <StatCard
              label="Platform Revenue"
              value={formatCurrency(stats.totalPlatformFees || 0)}
              icon="🏢"
              accent
            />
            <StatCard
              label="Pending Payouts"
              value={formatCurrency((stats as unknown as Record<string, number>).pendingPayouts || 0)}
              icon="⏳"
            />
          </div>
        )}

        {/* Filters */}
        <div className="bg-white rounded-xl border border-[#E1E6EF] p-4 flex flex-wrap gap-3 items-center">
          <input
            type="text"
            placeholder="Search transaction #..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            onKeyDown={(e) => {
              if (e.key === "Enter") {
                setFilters((f) => {
                  const { search: _search, ...rest } = f;
                  return searchQuery
                    ? { ...rest, page: 1, search: searchQuery }
                    : { ...rest, page: 1 };
                });
              }
            }}
            className="flex-1 min-w-50 px-3 py-2 border border-gray-300 rounded-lg text-sm focus:ring-2 focus:ring-[#4461F2] focus:border-transparent"
          />
          <select
            value={filters.type || ""}
            onChange={(e) => {
              const value = e.target.value as TransactionFilters["type"] | "";
              setFilters((f) => {
                const { type: _type, ...rest } = f;
                return value ? { ...rest, page: 1, type: value } : { ...rest, page: 1 };
              });
            }}
            className="px-3 py-2 border border-gray-300 rounded-lg text-sm"
          >
            <option value="">All Types</option>
            <option value="payment">Payment</option>
            <option value="payout">Payout</option>
            <option value="refund">Refund</option>
            <option value="platform_fee">Platform Fee</option>
          </select>
          <select
            value={filters.status || ""}
            onChange={(e) => {
              const value = e.target.value as TransactionFilters["status"] | "";
              setFilters((f) => {
                const { status: _status, ...rest } = f;
                return value ? { ...rest, page: 1, status: value } : { ...rest, page: 1 };
              });
            }}
            className="px-3 py-2 border border-gray-300 rounded-lg text-sm"
          >
            <option value="">All Statuses</option>
            <option value="pending">Pending</option>
            <option value="processing">Processing</option>
            <option value="completed">Completed</option>
            <option value="failed">Failed</option>
            <option value="refunded">Refunded</option>
            <option value="released">Released</option>
            <option value="held">Held</option>
          </select>
          <span className="text-xs text-gray-500">{totalCount} results</span>
        </div>

        {/* Transactions Table */}
        <div className="bg-white rounded-xl border border-[#E1E6EF] overflow-hidden">
          {isLoading ? (
            <div className="flex items-center justify-center py-20">
              <div className="w-10 h-10 border-4 border-gray-200 border-t-[#4461F2] rounded-full animate-spin" />
            </div>
          ) : transactions.length === 0 ? (
            <div className="text-center py-20">
              <p className="text-gray-500">No transactions found.</p>
            </div>
          ) : (
            <div className="overflow-x-auto">
              <table className="w-full text-sm">
                <thead className="bg-gray-50 border-b border-[#E1E6EF]">
                  <tr>
                    <th className="text-left px-4 py-3 font-medium text-gray-600">
                      Transaction
                    </th>
                    <th className="text-left px-4 py-3 font-medium text-gray-600">
                      Type
                    </th>
                    <th className="text-left px-4 py-3 font-medium text-gray-600">
                      Payer
                    </th>
                    <th className="text-left px-4 py-3 font-medium text-gray-600">
                      Payee
                    </th>
                    <th className="text-right px-4 py-3 font-medium text-gray-600">
                      Amount
                    </th>
                    <th className="text-right px-4 py-3 font-medium text-gray-600">
                      Fee
                    </th>
                    <th className="text-center px-4 py-3 font-medium text-gray-600">
                      Status
                    </th>
                    <th className="text-left px-4 py-3 font-medium text-gray-600">
                      Date
                    </th>
                    <th className="text-right px-4 py-3 font-medium text-gray-600">
                      Actions
                    </th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-gray-100">
                  {transactions.map((tx) => (
                    <tr
                      key={tx._id}
                      className="hover:bg-gray-50 cursor-pointer"
                      onClick={() => setSelectedTransaction(tx)}
                    >
                      <td className="px-4 py-3 font-mono text-xs text-gray-700">
                        {tx.transactionNumber || tx._id.slice(-8)}
                      </td>
                      <td className="px-4 py-3">
                        <span className="flex items-center gap-1.5">
                          <span>
                            {TYPE_CONFIG[tx.type]?.icon || "📄"}
                          </span>
                          <span className="text-gray-700">
                            {TYPE_CONFIG[tx.type]?.label || tx.type}
                          </span>
                        </span>
                      </td>
                      <td className="px-4 py-3 text-gray-600 truncate max-w-35">
                        {tx.payerId ? getUserName(tx.payerId) : "—"}
                      </td>
                      <td className="px-4 py-3 text-gray-600 truncate max-w-35">
                        {tx.payeeId ? getUserName(tx.payeeId) : "—"}
                      </td>
                      <td className="px-4 py-3 text-right font-semibold text-gray-900">
                        {formatCurrency(tx.amount, tx.currency)}
                      </td>
                      <td className="px-4 py-3 text-right text-gray-500">
                        {tx.platformFee
                          ? formatCurrency(tx.platformFee, tx.currency)
                          : "—"}
                      </td>
                      <td className="px-4 py-3 text-center">
                        {getStatusBadge(tx.status)}
                      </td>
                      <td className="px-4 py-3 text-gray-500 text-xs whitespace-nowrap">
                        {formatDate(tx.createdAt)}
                      </td>
                      <td className="px-4 py-3 text-right">
                        <button
                          onClick={(e) => {
                            e.stopPropagation();
                            setSelectedTransaction(tx);
                          }}
                          className="text-primary-500 hover:underline text-xs font-medium"
                        >
                          View
                        </button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}

          {/* Pagination */}
          {totalPages > 1 && (
            <div className="flex items-center justify-between px-4 py-3 border-t border-[#E1E6EF]">
              <p className="text-xs text-gray-500">
                Page {filters.page} of {totalPages}
              </p>
              <div className="flex gap-2">
                <button
                  onClick={() =>
                    setFilters((f) => ({
                      ...f,
                      page: Math.max(1, (f.page || 1) - 1),
                    }))
                  }
                  disabled={(filters.page || 1) <= 1}
                  className="px-3 py-1.5 text-xs font-medium border border-gray-300 rounded-lg disabled:opacity-40 hover:bg-gray-50"
                >
                  Previous
                </button>
                <button
                  onClick={() =>
                    setFilters((f) => ({
                      ...f,
                      page: Math.min(totalPages, (f.page || 1) + 1),
                    }))
                  }
                  disabled={(filters.page || 1) >= totalPages}
                  className="px-3 py-1.5 text-xs font-medium border border-gray-300 rounded-lg disabled:opacity-40 hover:bg-gray-50"
                >
                  Next
                </button>
              </div>
            </div>
          )}
        </div>

        {/* Transaction Detail Modal */}
        {selectedTransaction && (
          <div
            className="fixed inset-0 z-50 bg-black/50 flex items-center justify-center p-4"
            onClick={() => setSelectedTransaction(null)}
          >
            <div
              className="bg-white rounded-2xl max-w-lg w-full max-h-[80vh] overflow-y-auto p-6"
              onClick={(e) => e.stopPropagation()}
            >
              <div className="flex items-center justify-between mb-4">
                <h2 className="text-lg font-bold text-gray-900">
                  Transaction Details
                </h2>
                <button
                  onClick={() => setSelectedTransaction(null)}
                  className="text-gray-400 hover:text-gray-600"
                >
                  <svg
                    className="w-5 h-5"
                    fill="none"
                    stroke="currentColor"
                    viewBox="0 0 24 24"
                  >
                    <path
                      strokeLinecap="round"
                      strokeLinejoin="round"
                      strokeWidth={2}
                      d="M6 18L18 6M6 6l12 12"
                    />
                  </svg>
                </button>
              </div>

              <div className="space-y-4">
                <DetailRow
                  label="Transaction #"
                  value={
                    selectedTransaction.transactionNumber ||
                    selectedTransaction._id
                  }
                />
                <DetailRow
                  label="Type"
                  value={
                    TYPE_CONFIG[selectedTransaction.type]?.label ||
                    selectedTransaction.type
                  }
                />
                <DetailRow
                  label="Status"
                  value={getStatusBadge(selectedTransaction.status)}
                />
                <DetailRow
                  label="Amount"
                  value={formatCurrency(
                    selectedTransaction.amount,
                    selectedTransaction.currency
                  )}
                />
                {selectedTransaction.platformFee != null && (
                  <DetailRow
                    label="Platform Fee"
                    value={formatCurrency(
                      selectedTransaction.platformFee,
                      selectedTransaction.currency
                    )}
                  />
                )}
                {selectedTransaction.netAmount != null && (
                  <DetailRow
                    label="Net Amount"
                    value={formatCurrency(
                      selectedTransaction.netAmount,
                      selectedTransaction.currency
                    )}
                  />
                )}
                <DetailRow
                  label="Payer"
                  value={
                    selectedTransaction.payerId
                      ? getUserName(selectedTransaction.payerId)
                      : "—"
                  }
                />
                <DetailRow
                  label="Payee"
                  value={
                    selectedTransaction.payeeId
                      ? getUserName(selectedTransaction.payeeId)
                      : "—"
                  }
                />
                <DetailRow
                  label="Date"
                  value={formatDate(selectedTransaction.createdAt)}
                />
                {selectedTransaction.stripePaymentIntentId && (
                  <DetailRow
                    label="Stripe PI"
                    value={
                      <span className="font-mono text-xs">
                        {selectedTransaction.stripePaymentIntentId}
                      </span>
                    }
                  />
                )}
                {selectedTransaction.receiptUrl && (
                  <DetailRow
                    label="Receipt"
                    value={
                      <a
                        href={selectedTransaction.receiptUrl}
                        target="_blank"
                        rel="noopener noreferrer"
                        className="text-primary-500 hover:underline text-sm"
                      >
                        View Receipt ↗
                      </a>
                    }
                  />
                )}
                {selectedTransaction.description && (
                  <DetailRow
                    label="Description"
                    value={selectedTransaction.description}
                  />
                )}
              </div>

              {/* Actions */}
              <div className="mt-6 flex gap-3">
                {(selectedTransaction.status as string) === "held" &&
                  selectedTransaction.type === "payment" && (
                    <button
                      onClick={() => {
                        const bId =
                          typeof selectedTransaction.bookingId === "string"
                            ? selectedTransaction.bookingId
                            : (selectedTransaction.bookingId as { _id: string })?._id;
                        if (bId) handleRelease(bId);
                      }}
                      disabled={!!actionLoading}
                      className="flex-1 px-4 py-2.5 text-sm font-medium text-white bg-green-600 rounded-lg hover:bg-green-700 disabled:opacity-50"
                    >
                      {actionLoading ? "Processing..." : "Release Payment"}
                    </button>
                  )}
                {((selectedTransaction.status as string) === "completed" ||
                  (selectedTransaction.status as string) === "released") &&
                  selectedTransaction.type === "payment" && (
                    <button
                      onClick={() => {
                        setRefundTarget(selectedTransaction);
                        setRefundAmount(
                          String(selectedTransaction.amount)
                        );
                        setShowRefundModal(true);
                      }}
                      className="flex-1 px-4 py-2.5 text-sm font-medium text-white bg-red-600 rounded-lg hover:bg-red-700"
                    >
                      Process Refund
                    </button>
                  )}
                <button
                  onClick={() => setSelectedTransaction(null)}
                  className="px-4 py-2.5 text-sm font-medium text-gray-700 border border-gray-300 rounded-lg hover:bg-gray-50"
                >
                  Close
                </button>
              </div>
            </div>
          </div>
        )}

        {/* Refund Modal */}
        {showRefundModal && refundTarget && (
          <div
            className="fixed inset-0 z-60 bg-black/50 flex items-center justify-center p-4"
            onClick={() => setShowRefundModal(false)}
          >
            <div
              className="bg-white rounded-2xl max-w-md w-full p-6"
              onClick={(e) => e.stopPropagation()}
            >
              <h2 className="text-lg font-bold text-gray-900 mb-4">
                Process Refund
              </h2>
              <p className="text-sm text-gray-600 mb-4">
                Transaction:{" "}
                <span className="font-mono">
                  {refundTarget.transactionNumber}
                </span>
              </p>
              <div className="space-y-4">
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">
                    Refund Amount
                  </label>
                  <input
                    type="number"
                    step="0.01"
                    max={refundTarget.amount}
                    value={refundAmount}
                    onChange={(e) => setRefundAmount(e.target.value)}
                    className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm"
                    placeholder={`Max: ${refundTarget.amount}`}
                  />
                  <p className="text-xs text-gray-500 mt-1">
                    Original amount:{" "}
                    {formatCurrency(refundTarget.amount, refundTarget.currency)}
                    . Leave blank for full refund.
                  </p>
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">
                    Reason <span className="text-red-500">*</span>
                  </label>
                  <textarea
                    value={refundReason}
                    onChange={(e) => setRefundReason(e.target.value)}
                    rows={3}
                    className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm resize-none"
                    placeholder="Reason for refund..."
                    required
                  />
                </div>
              </div>
              <div className="flex gap-3 mt-6">
                <button
                  onClick={() => {
                    setShowRefundModal(false);
                    setRefundTarget(null);
                  }}
                  className="flex-1 px-4 py-2.5 text-sm font-medium text-gray-700 border border-gray-300 rounded-lg hover:bg-gray-50"
                >
                  Cancel
                </button>
                <button
                  onClick={handleRefundSubmit}
                  disabled={!!actionLoading || !refundReason.trim()}
                  className="flex-1 px-4 py-2.5 text-sm font-medium text-white bg-red-600 rounded-lg hover:bg-red-700 disabled:opacity-50"
                >
                  {actionLoading ? "Processing..." : "Confirm Refund"}
                </button>
              </div>
            </div>
          </div>
        )}
      </div>
    </AdminLayout>
  );
}

// Helper components
function StatCard({
  label,
  value,
  icon,
  accent,
}: {
  label: string;
  value: string;
  icon: string;
  accent?: boolean;
}) {
  return (
    <div
      className={`rounded-xl border p-4 ${
        accent
          ? "bg-linear-to-br from-primary-500 to-secondary-500 text-white border-transparent"
          : "bg-white border-[#E1E6EF]"
      }`}
    >
      <div className="flex items-center justify-between mb-2">
        <span
          className={`text-xs font-medium ${
            accent ? "text-white/80" : "text-gray-500"
          }`}
        >
          {label}
        </span>
        <span className="text-lg">{icon}</span>
      </div>
      <p
        className={`text-xl font-bold ${
          accent ? "text-white" : "text-gray-900"
        }`}
      >
        {value}
      </p>
    </div>
  );
}

function DetailRow({
  label,
  value,
}: {
  label: string;
  value: React.ReactNode;
}) {
  return (
    <div className="flex justify-between items-center py-2 border-b border-gray-100">
      <span className="text-sm text-gray-500">{label}</span>
      <span className="text-sm font-medium text-gray-900">{value}</span>
    </div>
  );
}

"use client";

import { useEffect, useState, useCallback } from "react";
import { AdminLayout } from "@/components";
import {
  reviewService,
  Review,
  ReviewStats,
  ReviewFilters,
  ModerationAction,
} from "@/services/api/review.service";

const STATUS_CONFIG: Record<
  string,
  { label: string; color: string; bgColor: string }
> = {
  active: { label: "Active", color: "#059669", bgColor: "#D1FAE5" },
  pending: { label: "Pending", color: "#D97706", bgColor: "#FEF3C7" },
  hidden: { label: "Hidden", color: "#DC2626", bgColor: "#FEE2E2" },
  removed: { label: "Removed", color: "#6B7280", bgColor: "#F3F4F6" },
};

const MODERATION_ACTIONS: { value: ModerationAction; label: string; color: string }[] = [
  { value: "approve", label: "Approve", color: "bg-green-600 hover:bg-green-700" },
  { value: "hide", label: "Hide", color: "bg-amber-600 hover:bg-amber-700" },
  { value: "remove", label: "Remove", color: "bg-red-600 hover:bg-red-700" },
  { value: "dismiss_reports", label: "Dismiss Reports", color: "bg-gray-600 hover:bg-gray-700" },
];

export default function AdminReviewsPage() {
  const [reviews, setReviews] = useState<Review[]>([]);
  const [stats, setStats] = useState<ReviewStats | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [successMessage, setSuccessMessage] = useState<string | null>(null);
  const [selectedReview, setSelectedReview] = useState<Review | null>(null);
  const [actionLoading, setActionLoading] = useState<string | null>(null);

  // Filters & pagination
  const [filters, setFilters] = useState<ReviewFilters>({ page: 1, limit: 15 });
  const [totalPages, setTotalPages] = useState(1);
  const [totalCount, setTotalCount] = useState(0);
  const [activeTab, setActiveTab] = useState<"all" | "reported" | "pending">("all");

  // Moderation modal
  const [showModerateModal, setShowModerateModal] = useState(false);
  const [moderateTarget, setModerateTarget] = useState<Review | null>(null);
  const [moderateAction, setModerateAction] = useState<ModerationAction>("approve");
  const [moderateReason, setModerateReason] = useState("");

  const fetchData = useCallback(async () => {
    setIsLoading(true);
    setError(null);
    try {
      const activeFilters: ReviewFilters = { ...filters };
      if (activeTab === "reported") {
        activeFilters.reported = true;
      } else if (activeTab === "pending") {
        activeFilters.status = "pending_review";
      }

      const [revRes, statsRes] = await Promise.all([
        reviewService.getAllReviews(activeFilters),
        reviewService.getReviewStats(),
      ]);

      if (revRes.success && revRes.data) {
        setReviews(revRes.data.reviews);
        setTotalPages(revRes.data.pagination?.pages || 1);
        setTotalCount(revRes.data.pagination?.total || 0);
      }
      if (statsRes.success && statsRes.data) {
        setStats(statsRes.data);
      }
    } catch {
      setError("Failed to load review data.");
    } finally {
      setIsLoading(false);
    }
  }, [filters, activeTab]);

  useEffect(() => {
    fetchData();
  }, [fetchData]);

  useEffect(() => {
    if (!successMessage) return;
    const t = setTimeout(() => setSuccessMessage(null), 4000);
    return () => clearTimeout(t);
  }, [successMessage]);

  const handleTabChange = (tab: typeof activeTab) => {
    setActiveTab(tab);
    setFilters((f) => ({ ...f, page: 1 }));
  };

  const openModerateModal = (review: Review, action: ModerationAction) => {
    setModerateTarget(review);
    setModerateAction(action);
    setModerateReason("");
    setShowModerateModal(true);
  };

  const handleModerate = async () => {
    if (!moderateTarget) return;
    setActionLoading(moderateTarget._id);
    try {
      const res = await reviewService.moderateReview(moderateTarget._id, {
        action: moderateAction,
        ...(moderateReason ? { reason: moderateReason } : {}),
      });
      if (res.success) {
        setSuccessMessage(`Review ${moderateAction}d successfully.`);
        setShowModerateModal(false);
        setModerateTarget(null);
        setSelectedReview(null);
        fetchData();
      } else {
        setError(res.message || "Moderation failed.");
      }
    } catch {
      setError("Failed to moderate review.");
    } finally {
      setActionLoading(null);
    }
  };

  const getUserName = (user: string | { _id?: string; fullName?: string; email?: string }) => {
    if (typeof user === "string") return user;
    return user.fullName || user.email || user._id || "Unknown";
  };

  const formatDate = (date: string) =>
    new Date(date).toLocaleDateString("en-US", {
      year: "numeric",
      month: "short",
      day: "numeric",
    });

  const getStatusBadge = (status: string) => {
    const config = STATUS_CONFIG[status] || { label: status, color: "#6B7280", bgColor: "#F3F4F6" };
    return (
      <span
        className="px-2.5 py-0.5 rounded-full text-xs font-medium"
        style={{ color: config.color, backgroundColor: config.bgColor }}
      >
        {config.label}
      </span>
    );
  };

  const renderStars = (rating: number) => {
    return (
      <span className="flex items-center gap-0.5">
        {[1, 2, 3, 4, 5].map((i) => (
          <svg
            key={i}
            className={`w-3.5 h-3.5 ${i <= rating ? "text-amber-400" : "text-gray-300"}`}
            fill="currentColor"
            viewBox="0 0 20 20"
          >
            <path d="M9.049 2.927c.3-.921 1.603-.921 1.902 0l1.07 3.292a1 1 0 00.95.69h3.462c.969 0 1.371 1.24.588 1.81l-2.8 2.034a1 1 0 00-.364 1.118l1.07 3.292c.3.921-.755 1.688-1.54 1.118l-2.8-2.034a1 1 0 00-1.175 0l-2.8 2.034c-.784.57-1.838-.197-1.539-1.118l1.07-3.292a1 1 0 00-.364-1.118L2.98 8.72c-.783-.57-.38-1.81.588-1.81h3.461a1 1 0 00.951-.69l1.07-3.292z" />
          </svg>
        ))}
        <span className="text-xs text-gray-500 ml-1">{rating.toFixed(1)}</span>
      </span>
    );
  };

  const tabs = [
    { key: "all" as const, label: "All Reviews" },
    { key: "reported" as const, label: "Reported", badge: stats?.reportedReviews },
    { key: "pending" as const, label: "Pending", badge: stats?.hiddenReviews },
  ];

  return (
    <AdminLayout>
      <div className="space-y-6">
        {/* Header */}
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-2xl font-bold text-gray-900">Review Management</h1>
            <p className="text-sm text-gray-500 mt-1">Moderate reviews and handle reports</p>
          </div>
          <button
            onClick={() => fetchData()}
            disabled={isLoading}
            className="px-4 py-2 text-sm font-medium text-white bg-primary-500 rounded-lg hover:bg-[#2F4BDB] disabled:opacity-50 flex items-center gap-2"
          >
            <svg
              className={`w-4 h-4 ${isLoading ? "animate-spin" : ""}`}
              fill="none"
              stroke="currentColor"
              viewBox="0 0 24 24"
            >
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth={2}
                d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15"
              />
            </svg>
            Refresh
          </button>
        </div>

        {/* Messages */}
        {successMessage && (
          <div className="bg-green-50 border border-green-200 text-green-700 px-4 py-3 rounded-xl text-sm">
            {successMessage}
          </div>
        )}
        {error && (
          <div className="bg-red-50 border border-red-200 text-red-700 px-4 py-3 rounded-xl text-sm flex justify-between items-center">
            {error}
            <button onClick={() => setError(null)} className="text-red-500 hover:text-red-700">✕</button>
          </div>
        )}

        {/* Stats Cards */}
        {stats && (
          <div className="grid grid-cols-2 md:grid-cols-5 gap-4">
            <StatCard label="Total Reviews" value={String(stats.totalReviews || 0)} icon="⭐" />
            <StatCard label="Average Rating" value={String(stats.averageRating?.toFixed(1) || "0")} icon="📊" />
            <StatCard label="Verified" value={String(stats.verifiedReviews || 0)} icon="✅" />
            <StatCard
              label="Reported"
              value={String(stats.reportedReviews || 0)}
              icon="🚩"
              warning={!!stats.reportedReviews}
            />
            <StatCard
              label="Hidden"
              value={String(stats.hiddenReviews || 0)}
              icon="⏳"
              warning={!!stats.hiddenReviews}
            />
          </div>
        )}

        {/* Tabs */}
        <div className="flex gap-1 bg-gray-100 p-1 rounded-lg w-fit">
          {tabs.map(({ key, label, badge }) => (
            <button
              key={key}
              onClick={() => handleTabChange(key)}
              className={`px-4 py-2 text-sm font-medium rounded-md transition-colors flex items-center gap-2 ${
                activeTab === key
                  ? "bg-white text-primary-500 shadow-sm"
                  : "text-gray-600 hover:text-gray-900"
              }`}
            >
              {label}
              {badge != null && badge > 0 && (
                <span className="bg-red-500 text-white text-xs px-1.5 py-0.5 rounded-full">
                  {badge}
                </span>
              )}
            </button>
          ))}
        </div>

        {/* Filters */}
        <div className="bg-white rounded-xl border border-[#E1E6EF] p-4 flex flex-wrap gap-3 items-center">
          <select
            value={filters.reviewType || ""}
            onChange={(e) => {
              const value = e.target.value as "verified" | "public" | "";
              setFilters((f) => {
                const { reviewType: _reviewType, ...rest } = f;
                return value ? { ...rest, page: 1, reviewType: value } : { ...rest, page: 1 };
              });
            }}
            className="px-3 py-2 border border-gray-300 rounded-lg text-sm"
          >
            <option value="">All Types</option>
            <option value="verified">Verified</option>
            <option value="public">Public</option>
          </select>
          <select
            value={filters.minRating || ""}
            onChange={(e) => {
              const value = e.target.value ? parseInt(e.target.value) : null;
              setFilters((f) => {
                const { minRating: _minRating, ...rest } = f;
                return value ? { ...rest, page: 1, minRating: value } : { ...rest, page: 1 };
              });
            }}
            className="px-3 py-2 border border-gray-300 rounded-lg text-sm"
          >
            <option value="">All Ratings</option>
            <option value="5">5 Stars</option>
            <option value="4">4+ Stars</option>
            <option value="3">3+ Stars</option>
            <option value="2">2+ Stars</option>
            <option value="1">1+ Stars</option>
          </select>
          <span className="text-xs text-gray-500">{totalCount} results</span>
        </div>

        {/* Reviews Table */}
        <div className="bg-white rounded-xl border border-[#E1E6EF] overflow-hidden">
          {isLoading ? (
            <div className="flex items-center justify-center py-20">
              <div className="w-10 h-10 border-4 border-gray-200 border-t-[#4461F2] rounded-full animate-spin" />
            </div>
          ) : reviews.length === 0 ? (
            <div className="text-center py-20">
              <p className="text-gray-500">No reviews found.</p>
            </div>
          ) : (
            <div className="overflow-x-auto">
              <table className="w-full text-sm">
                <thead className="bg-gray-50 border-b border-[#E1E6EF]">
                  <tr>
                    <th className="text-left px-4 py-3 font-medium text-gray-600">Reviewer</th>
                    <th className="text-left px-4 py-3 font-medium text-gray-600">Reviewee</th>
                    <th className="text-left px-4 py-3 font-medium text-gray-600">Type</th>
                    <th className="text-center px-4 py-3 font-medium text-gray-600">Rating</th>
                    <th className="text-left px-4 py-3 font-medium text-gray-600">Comment</th>
                    <th className="text-center px-4 py-3 font-medium text-gray-600">Status</th>
                    <th className="text-center px-4 py-3 font-medium text-gray-600">Reports</th>
                    <th className="text-left px-4 py-3 font-medium text-gray-600">Date</th>
                    <th className="text-right px-4 py-3 font-medium text-gray-600">Actions</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-gray-100">
                  {reviews.map((review) => (
                    <tr
                      key={review._id}
                      className="hover:bg-gray-50 cursor-pointer"
                      onClick={() => setSelectedReview(review)}
                    >
                      <td className="px-4 py-3 text-gray-700 truncate max-w-[120px]">
                        {getUserName(review.reviewerId)}
                      </td>
                      <td className="px-4 py-3 text-gray-700 truncate max-w-[120px]">
                        {getUserName(review.revieweeId)}
                      </td>
                      <td className="px-4 py-3">
                        <span
                          className={`px-2 py-0.5 rounded text-xs font-medium ${
                            review.reviewType === "verified"
                              ? "bg-blue-100 text-blue-700"
                              : "bg-gray-100 text-gray-700"
                          }`}
                        >
                          {review.reviewType === "verified" ? "✓ Verified" : "Public"}
                        </span>
                      </td>
                      <td className="px-4 py-3 text-center">{renderStars(review.overallRating)}</td>
                      <td className="px-4 py-3 text-gray-600 truncate max-w-[200px]">
                        {review.title || review.comment?.slice(0, 60) || "—"}
                      </td>
                      <td className="px-4 py-3 text-center">{getStatusBadge(review.status)}</td>
                      <td className="px-4 py-3 text-center">
                        {review.reported?.isReported && review.reported.reports?.length > 0 ? (
                          <span className="px-2 py-0.5 bg-red-100 text-red-700 rounded-full text-xs font-medium">
                            {review.reported.reports.length}
                          </span>
                        ) : (
                          <span className="text-gray-400 text-xs">0</span>
                        )}
                      </td>
                      <td className="px-4 py-3 text-gray-500 text-xs whitespace-nowrap">
                        {formatDate(review.createdAt)}
                      </td>
                      <td className="px-4 py-3 text-right">
                        <button
                          onClick={(e) => {
                            e.stopPropagation();
                            setSelectedReview(review);
                          }}
                          className="text-primary-500 hover:underline text-xs font-medium"
                        >
                          View
                        </button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}

          {/* Pagination */}
          {totalPages > 1 && (
            <div className="flex items-center justify-between px-4 py-3 border-t border-[#E1E6EF]">
              <p className="text-xs text-gray-500">
                Page {filters.page} of {totalPages}
              </p>
              <div className="flex gap-2">
                <button
                  onClick={() =>
                    setFilters((f) => ({ ...f, page: Math.max(1, (f.page || 1) - 1) }))
                  }
                  disabled={(filters.page || 1) <= 1}
                  className="px-3 py-1.5 text-xs font-medium border border-gray-300 rounded-lg disabled:opacity-40 hover:bg-gray-50"
                >
                  Previous
                </button>
                <button
                  onClick={() =>
                    setFilters((f) => ({ ...f, page: Math.min(totalPages, (f.page || 1) + 1) }))
                  }
                  disabled={(filters.page || 1) >= totalPages}
                  className="px-3 py-1.5 text-xs font-medium border border-gray-300 rounded-lg disabled:opacity-40 hover:bg-gray-50"
                >
                  Next
                </button>
              </div>
            </div>
          )}
        </div>

        {/* Review Detail Modal */}
        {selectedReview && (
          <div
            className="fixed inset-0 z-50 bg-black/50 flex items-center justify-center p-4"
            onClick={() => setSelectedReview(null)}
          >
            <div
              className="bg-white rounded-2xl max-w-lg w-full max-h-[85vh] overflow-y-auto p-6"
              onClick={(e) => e.stopPropagation()}
            >
              <div className="flex items-center justify-between mb-4">
                <h2 className="text-lg font-bold text-gray-900">Review Details</h2>
                <button
                  onClick={() => setSelectedReview(null)}
                  className="text-gray-400 hover:text-gray-600"
                >
                  <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                  </svg>
                </button>
              </div>

              <div className="space-y-4">
                {/* Rating & Type */}
                <div className="flex items-center justify-between">
                  {renderStars(selectedReview.overallRating)}
                  <span
                    className={`px-2.5 py-0.5 rounded text-xs font-medium ${
                      selectedReview.reviewType === "verified"
                        ? "bg-blue-100 text-blue-700"
                        : "bg-gray-100 text-gray-700"
                    }`}
                  >
                    {selectedReview.reviewType === "verified" ? "✓ Verified" : "Public"}
                  </span>
                </div>

                {/* Status */}
                <div className="flex justify-between items-center py-2 border-b border-gray-100">
                  <span className="text-sm text-gray-500">Status</span>
                  {getStatusBadge(selectedReview.status)}
                </div>

                {/* Users */}
                <div className="flex justify-between items-center py-2 border-b border-gray-100">
                  <span className="text-sm text-gray-500">Reviewer</span>
                  <span className="text-sm font-medium">{getUserName(selectedReview.reviewerId)}</span>
                </div>
                <div className="flex justify-between items-center py-2 border-b border-gray-100">
                  <span className="text-sm text-gray-500">Reviewee</span>
                  <span className="text-sm font-medium">{getUserName(selectedReview.revieweeId)}</span>
                </div>

                {/* Title & Comment */}
                {selectedReview.title && (
                  <div>
                    <p className="text-sm font-semibold text-gray-900">{selectedReview.title}</p>
                  </div>
                )}
                <div>
                  <p className="text-sm text-gray-700 leading-relaxed">{selectedReview.comment}</p>
                </div>

                {/* Detailed Ratings */}
                {selectedReview.ratings && (
                  <div className="bg-gray-50 rounded-lg p-3">
                    <p className="text-xs font-medium text-gray-500 mb-2">Detailed Ratings</p>
                    <div className="grid grid-cols-2 gap-2 text-xs">
                      {Object.entries(selectedReview.ratings).map(([key, val]) => (
                        <div key={key} className="flex justify-between">
                          <span className="text-gray-600 capitalize">
                            {key.replace(/([A-Z])/g, " $1").trim()}
                          </span>
                          <span className="font-medium">{val}/5</span>
                        </div>
                      ))}
                    </div>
                  </div>
                )}

                {/* Reports */}
                {selectedReview.reported?.isReported && selectedReview.reported.reports?.length > 0 && (
                  <div className="bg-red-50 rounded-lg p-3">
                    <p className="text-xs font-medium text-red-700 mb-2">
                      Reports ({selectedReview.reported.reports.length})
                    </p>
                    <div className="space-y-2">
                      {selectedReview.reported.reports.map((report, i) => (
                        <div key={i} className="text-xs text-red-600">
                          <span className="font-medium capitalize">{report.reason}</span>
                          {report.description && (
                            <span className="text-red-500"> — {report.description}</span>
                          )}
                        </div>
                      ))}
                    </div>
                  </div>
                )}

                {/* Response */}
                {selectedReview.response?.content && (
                  <div className="bg-blue-50 rounded-lg p-3">
                    <p className="text-xs font-medium text-blue-700 mb-1">Owner Response</p>
                    <p className="text-sm text-blue-800">{selectedReview.response.content}</p>
                  </div>
                )}

                {/* Date */}
                <div className="flex justify-between items-center py-2 border-b border-gray-100">
                  <span className="text-sm text-gray-500">Created</span>
                  <span className="text-sm text-gray-600">{formatDate(selectedReview.createdAt)}</span>
                </div>

                {/* Moderation History */}
                {selectedReview.moderation && (
                  <div className="flex justify-between items-center py-2 border-b border-gray-100">
                    <span className="text-sm text-gray-500">Moderation</span>
                    <span className="text-sm text-gray-600 capitalize">
                      {selectedReview.moderation.action}
                      {selectedReview.moderation.reason && ` — ${selectedReview.moderation.reason}`}
                    </span>
                  </div>
                )}
              </div>

              {/* Actions */}
              <div className="mt-6 space-y-3">
                <p className="text-xs font-medium text-gray-500">Moderation Actions</p>
                <div className="flex flex-wrap gap-2">
                  {MODERATION_ACTIONS.map(({ value, label, color }) => (
                    <button
                      key={value}
                      onClick={() => openModerateModal(selectedReview, value)}
                      disabled={!!actionLoading}
                      className={`px-3 py-2 text-xs font-medium text-white rounded-lg disabled:opacity-50 ${color}`}
                    >
                      {label}
                    </button>
                  ))}
                </div>
                <button
                  onClick={() => setSelectedReview(null)}
                  className="w-full px-4 py-2 text-sm font-medium text-gray-700 border border-gray-300 rounded-lg hover:bg-gray-50"
                >
                  Close
                </button>
              </div>
            </div>
          </div>
        )}

        {/* Moderation Modal */}
        {showModerateModal && moderateTarget && (
          <div
            className="fixed inset-0 z-[60] bg-black/50 flex items-center justify-center p-4"
            onClick={() => setShowModerateModal(false)}
          >
            <div
              className="bg-white rounded-2xl max-w-md w-full p-6"
              onClick={(e) => e.stopPropagation()}
            >
              <h2 className="text-lg font-bold text-gray-900 mb-2">
                Confirm: {moderateAction.replace("_", " ").replace(/\b\w/g, (l) => l.toUpperCase())}
              </h2>
              <p className="text-sm text-gray-600 mb-4">
                This action will {moderateAction} the review by{" "}
                <span className="font-medium">{getUserName(moderateTarget.reviewerId)}</span>.
              </p>
              <div className="mb-4">
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  Reason (optional)
                </label>
                <textarea
                  value={moderateReason}
                  onChange={(e) => setModerateReason(e.target.value)}
                  rows={3}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm resize-none"
                  placeholder="Reason for this action..."
                />
              </div>
              <div className="flex gap-3">
                <button
                  onClick={() => {
                    setShowModerateModal(false);
                    setModerateTarget(null);
                  }}
                  className="flex-1 px-4 py-2.5 text-sm font-medium text-gray-700 border border-gray-300 rounded-lg hover:bg-gray-50"
                >
                  Cancel
                </button>
                <button
                  onClick={handleModerate}
                  disabled={!!actionLoading}
                  className="flex-1 px-4 py-2.5 text-sm font-medium text-white bg-primary-500 rounded-lg hover:bg-[#2F4BDB] disabled:opacity-50"
                >
                  {actionLoading ? "Processing..." : "Confirm"}
                </button>
              </div>
            </div>
          </div>
        )}
      </div>
    </AdminLayout>
  );
}

function StatCard({
  label,
  value,
  icon,
  warning,
}: {
  label: string;
  value: string;
  icon: string;
  warning?: boolean;
}) {
  return (
    <div
