                {/* Secure Booking */}
                <div className="flex items-start gap-3 p-3.5 bg-emerald-50 rounded-xl border border-emerald-100">
                  <svg className="w-5 h-5 text-emerald-500 shrink-0 mt-0.5" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M2.166 4.999A11.954 11.954 0 0010 1.944 11.954 11.954 0 0017.834 5c.11.65.166 1.32.166 2.001 0 5.225-3.34 9.67-8 11.317C5.34 16.67 2 12.225 2 7c0-.682.057-1.35.166-2.001zm11.541 3.708a1 1 0 00-1.414-1.414L9 10.586 7.707 9.293a1 1 0 00-1.414 1.414l2 2a1 1 0 001.414 0l4-4z" clipRule="evenodd" /></svg>
                  <div>
                    <p className="text-sm font-semibold text-emerald-800">Secure Booking</p>
                    <p className="text-xs text-emerald-600 mt-0.5 leading-relaxed">You won&apos;t be charged until the caregiver confirms your request.</p>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>
      </main>
    </div>
  );
}

/**
 * Booking Confirmation Page
 * Displays booking confirmation with map location
 */

'use client';

import { useState, useEffect } from 'react';
import { useSearchParams } from 'next/navigation';
import { BookingConfirmationMap } from '@/features/map/components/legacy';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/Card';
import type { BookingLocation } from '@/types/map.types';
import { CheckCircle, Calendar, Clock, Banknote, Loader2, AlertCircle, MapPin } from 'lucide-react';
import { bookingService } from '@/services';

interface BookingDetails {
  id: string;
  date: string;
  time: string;
  duration: string;
  totalCost: number;
  caregiver: {
    name: string;
    specialty: string;
    rating: number;
    reviews: number;
    avatar?: string;
  };
  location?: BookingLocation;
}

export default function BookingConfirmationPage() {
  const searchParams = useSearchParams();
  const bookingId = searchParams.get('bookingId');

  const [booking, setBooking] = useState<BookingDetails | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const fetchBooking = async () => {
      if (!bookingId) {
        setError('No booking ID provided');
        setIsLoading(false);
        return;
      }

      try {
        const response = await bookingService.getBookingById(bookingId);
        if (response.success && response.data?.booking) {
          const b = response.data.booking;
          const bAny = b as unknown as Record<string, unknown>;
          const schedule = bAny.schedule as { startDate?: string; startTime?: string; endTime?: string; totalHours?: number } | undefined;
          const caregiver = bAny.caregiverId as { fullName?: string; rating?: number; reviewCount?: number; avatar?: string } | undefined;
          const location = bAny.location as { coordinates?: { lat?: number; lng?: number }; address?: string; city?: string; postalCode?: string } | undefined;
          setBooking({
            id: b._id,
            date: schedule?.startDate ? new Date(schedule.startDate).toLocaleDateString('en-US', {
              weekday: 'long',
              year: 'numeric',
              month: 'long',
              day: 'numeric',
            }) : '',
            time: schedule?.startTime && schedule?.endTime ? `${schedule.startTime} - ${schedule.endTime}` : '',
            duration: schedule?.totalHours ? `${schedule.totalHours} hours` : '',
            totalCost: (bAny.totalAmount as number) || 0,
            caregiver: {
              name: caregiver?.fullName || 'Caregiver',
              specialty: (bAny.serviceType as string) || 'Care Service',
              rating: caregiver?.rating || 0,
              reviews: caregiver?.reviewCount || 0,
              ...(caregiver?.avatar ? { avatar: caregiver.avatar } : {}),
            },
            ...(location ? {
              location: {
                latitude: location.coordinates?.lat || 0,
                longitude: location.coordinates?.lng || 0,
                address: location.address || '',
                city: location.city || '',
                postalCode: location.postalCode || '',
              }
            } : {}),
          });
        }
      } catch (err) {
        console.error('Failed to fetch booking:', err);
        setError('Unable to load booking details');
      } finally {
        setIsLoading(false);
      }
    };

    fetchBooking();
  }, [bookingId]);

  if (isLoading) {
    return (
      <div className="min-h-screen bg-neutral-50 flex items-center justify-center">
        <div className="text-center">
          <Loader2 className="w-10 h-10 text-primary-500 animate-spin mx-auto mb-4" />
          <p className="text-gray-500">Loading booking details...</p>
        </div>
      </div>
    );
  }

  if (error || !booking) {
    return (
      <div className="min-h-screen bg-neutral-50 flex items-center justify-center">
        <div className="text-center max-w-md mx-auto p-6">
          <AlertCircle className="w-12 h-12 text-red-500 mx-auto mb-4" />
          <h2 className="text-xl font-bold text-gray-900 mb-2">Booking Not Found</h2>
          <p className="text-gray-500 mb-4">{error || 'Unable to load booking details'}</p>
          <a
            href="/dashboard"
            className="inline-flex px-4 py-2 bg-primary-500 text-white rounded-lg hover:bg-primary-600 transition-colors"
          >
            Go to Dashboard
          </a>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-neutral-50">
      <div className="container mx-auto px-4 py-8 max-w-4xl">
        {/* Success Header */}
        <div className="mb-8 text-center">
          <div className="inline-flex items-center justify-center w-16 h-16 bg-green-100 rounded-full mb-4">
            <CheckCircle className="w-10 h-10 text-green-600" />
          </div>
          <h1 className="text-3xl font-bold text-neutral-900 mb-2">
            Booking Confirmed!
          </h1>
          <p className="text-neutral-600">
            Your booking has been successfully confirmed. Details below.
          </p>
        </div>

        <div className="grid gap-6 md:grid-cols-2">
          {/* Booking Details */}
          <Card>
            <CardHeader>
              <CardTitle>Booking Details</CardTitle>
            </CardHeader>
            <CardContent className="space-y-4">
              <div className="flex items-center gap-3">
                <Calendar className="w-5 h-5 text-neutral-600" />
                <div>
                  <p className="text-sm text-neutral-500">Date</p>
                  <p className="font-medium">{booking.date}</p>
                </div>
              </div>
              <div className="flex items-center gap-3">
                <Clock className="w-5 h-5 text-neutral-600" />
                <div>
                  <p className="text-sm text-neutral-500">Time</p>
                  <p className="font-medium">{booking.time}</p>
                </div>
              </div>
              <div className="flex items-center gap-3">
                <Banknote className="w-5 h-5 text-neutral-600" />
                <div>
                  <p className="text-sm text-neutral-500">Total Cost</p>
                  <p className="font-medium">Rs. {booking.totalCost.toLocaleString()}</p>
                </div>
              </div>
            </CardContent>
          </Card>

          {/* Caregiver Info */}
          <Card>
            <CardHeader>
              <CardTitle>Caregiver</CardTitle>
            </CardHeader>
            <CardContent>
              <div className="flex items-center gap-4">
                <div className="w-16 h-16 bg-blue-100 rounded-full flex items-center justify-center overflow-hidden">
                  {booking.caregiver.avatar ? (
                    <img src={booking.caregiver.avatar} alt={booking.caregiver.name} className="w-full h-full object-cover" />
                  ) : (
                    <span className="text-2xl">👩‍⚕️</span>
                  )}
                </div>
                <div>
                  <h3 className="font-semibold text-lg">{booking.caregiver.name}</h3>
                  <p className="text-sm text-neutral-600">{booking.caregiver.specialty}</p>
                  {booking.caregiver.rating > 0 && (
                    <div className="flex items-center gap-1 mt-1">
                      <span className="text-yellow-500">⭐</span>
                      <span className="text-sm font-medium">
                        {booking.caregiver.rating.toFixed(1)} ({booking.caregiver.reviews} reviews)
                      </span>
                    </div>
                  )}
                </div>
              </div>
            </CardContent>
          </Card>
        </div>

        {/* Service Location Map */}
        <div className="mt-6">
          <h2 className="text-xl font-semibold text-neutral-900 mb-4">
            Service Location
          </h2>
          {booking.location ? (
            <BookingConfirmationMap
              location={booking.location}
              showNavigation={true}
            />
          ) : (
            <div className="bg-white rounded-xl border border-gray-200 p-8 text-center">
              <MapPin className="w-12 h-12 text-gray-300 mx-auto mb-3" />
              <p className="text-gray-500">Location details not available</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

﻿"use client";

import { useEffect, useState } from "react";
import Link from "next/link";
import Image from "next/image";
import { useParams, useRouter } from "next/navigation";
import { Logo } from "@/components/ui/Logo";
import { caregiverService, type Caregiver } from "@/services";
import { authService } from "@/features/auth/services";
import type { User } from "@/types";

export default function CaregiverProfilePage() {
  const params = useParams();
  const router = useRouter();
  const [caregiver, setCaregiver] = useState<Caregiver | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState("");
  const [user, setUser] = useState<User | null>(null);

  useEffect(() => {
    // Check if user is logged in
    const storedUser = authService.getCurrentUser();
    setUser(storedUser);
  }, []);

  useEffect(() => {
    if (params.id) {
      fetchCaregiver();
    }
  }, [params.id]);

  const fetchCaregiver = async () => {
    try {
      setIsLoading(true);
      setError("");

      const response = await caregiverService.getCaregiverProfile(params.id as string);

      if (!response.success) {
        throw new Error("Failed to fetch caregiver");
      }

      setCaregiver(response.data?.caregiver || null);
    } catch (err) {
      console.error("Error fetching caregiver:", err);
      setError(err instanceof Error ? err.message : "Failed to load caregiver profile");
    } finally {
      setIsLoading(false);
    }
  };

  const getMemberSince = (dateString?: string) => {
    if (!dateString) return "Unknown";
    const date = new Date(dateString);
    return date.toLocaleDateString("en-US", { month: "long", year: "numeric" });
  };

  const formatNPR = (amount: number): string => `NPR ${amount.toLocaleString()}`;

  const dashboardHref = user?.role === "admin" ? "/admin/dashboard" : "/dashboard";

  const getAvailabilityStatus = (): { available: boolean; label: string; timeLabel: string } => {
    if (!caregiver?.availability?.days?.length) {
      return { available: false, label: "Availability Not Set", timeLabel: "" };
    }
    const now = new Date();
    const dayNames = ["sunday", "monday", "tuesday", "wednesday", "thursday", "friday", "saturday"];
    const today = dayNames[now.getDay()];
    const availDays = (caregiver.availability.days || []).map((d: string) => d.toLowerCase());
    if (!availDays.includes(today)) {
      return { available: false, label: "Not Available Today", timeLabel: "" };
    }
    const start = caregiver.availability.hours?.start;
    const end = caregiver.availability.hours?.end;
    if (!start || !end) {
      return { available: true, label: "Available Today", timeLabel: "" };
    }
    const [sh, sm] = start.split(":").map(Number);
    const [eh, em] = end.split(":").map(Number);
    const startMins = sh * 60 + (sm || 0);
    const endMins = eh * 60 + (em || 0);
    const currentMins = now.getHours() * 60 + now.getMinutes();
    if (currentMins >= startMins && currentMins <= endMins) {
      return { available: true, label: "Available Now", timeLabel: `${start} \u2013 ${end}` };
    }
    if (currentMins < startMins) {
      return { available: false, label: "Not Available Right Now", timeLabel: `Available from ${start} today` };
    }
    return { available: false, label: "Not Available Right Now", timeLabel: `Working hours: ${start}\u2013${end}` };
  };

  const availStatus = getAvailabilityStatus();

  if (isLoading) {
    return (
      <div className="min-h-screen bg-linear-to-br from-[#39B54A]/5 via-white to-[#39B54A]/5 flex items-center justify-center">
        <div className="text-center">
          <div className="w-16 h-16 border-4 border-[#39B54A] border-t-transparent rounded-full animate-spin mx-auto mb-4" />
          <p className="text-gray-400 font-medium">Loading profile&hellip;</p>
        </div>
      </div>
    );
  }

  if (error || !caregiver) {
    return (
      <div className="min-h-screen bg-linear-to-br from-[#39B54A]/5 via-white to-[#39B54A]/5">
        <header className="sticky top-0 z-50 bg-white/95 backdrop-blur-md border-b border-slate-200/60 shadow-sm">
          <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
            <div className="flex justify-between items-center h-16">
              <Link href="/home" className="flex items-center gap-2.5">
                <Logo variant="default" showText asLink={false} />
              </Link>
            </div>
          </div>
        </header>
        <div className="max-w-4xl mx-auto px-4 py-16 text-center">
          <div className="bg-white rounded-2xl p-12 shadow-xl border border-slate-100 max-w-sm mx-auto">
            <div className="text-5xl mb-4">\ud83d\ude14</div>
            <h1 className="text-2xl font-bold text-gray-900 mb-2">Caregiver Not Found</h1>
            <p className="text-gray-400 mb-6 text-sm">{error || "This caregiver doesn't exist or is no longer available."}</p>
            <Link href="/caregivers" className="inline-flex items-center gap-2 px-6 py-3 bg-[#39B54A] text-white rounded-xl hover:bg-[#2d913c] transition-all font-semibold shadow-md shadow-[#39B54A]/30">
              <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 19l-7-7m0 0l7-7m-7 7h18" /></svg>
              Browse Caregivers
            </Link>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-linear-to-br from-[#39B54A]/5 via-white to-[#39B54A]/5">
      {/* Header */}
      <header className="sticky top-0 z-50 bg-white/95 backdrop-blur-md border-b border-slate-200/60 shadow-sm">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between items-center h-16">
            <Logo variant="default" showText href="/home" />
            <nav className="hidden md:flex items-center gap-8">
              <Link href="/home" className="text-sm font-medium text-gray-500 hover:text-primary-500 transition-colors">Home</Link>
              <Link href="/caregivers" className="text-sm font-medium text-gray-500 hover:text-primary-500 transition-colors">Find Caregivers</Link>
            </nav>
            <div className="flex items-center gap-3">
              {user ? (
                <>
                  <Link href={dashboardHref} className="px-4 py-2 text-sm font-medium text-gray-500 hover:text-primary-500 transition-colors">
                    Dashboard
                  </Link>
                  {user.role === "admin" && (
                    <Link href="/admin/dashboard" className="px-5 py-2 bg-[#39B54A] hover:bg-[#2d913c] text-white text-sm font-semibold rounded-xl transition-all shadow-sm hover:shadow-[#39B54A]/30">
                      Admin Panel
                    </Link>
                  )}
                </>
              ) : (
                <>
                  <Link href="/login" className="px-4 py-2 text-sm font-medium text-gray-500 hover:text-primary-500 transition-colors">Login</Link>
                  <Link href="/caregivers" className="px-5 py-2 bg-[#39B54A] hover:bg-[#2d913c] text-white text-sm font-semibold rounded-xl transition-all shadow-sm hover:shadow-[#39B54A]/30">Sign Up</Link>
                </>
              )}
            </div>
          </div>
        </div>
      </header>

      <main className="max-w-5xl mx-auto px-4 py-8">
