"use client";
import React, { useEffect, useState } from "react";
import { motion, AnimatePresence } from "framer-motion";

interface RealTimeIndicatorProps {
  connected: boolean;
  lastEventType?: string;
  compact?: boolean;
}

const EVENT_LABELS: Record<string, string> = {
  "booking:created": "New booking",
  "booking:accepted": "Booking accepted",
  "booking:confirmed": "Booking confirmed",
  "booking:active": "Session started",
  "booking:completed": "Session completed",
  "booking:cancelled": "Booking cancelled",
  "tracking:submitted": "Log submitted",
  "tracking:flagged": "Log flagged",
  "tracking:missed": "Log missed",
  "dispute:created": "Dispute raised",
  "dispute:resolved": "Dispute resolved",
  "notification:created": "New notification",
};

export default function RealTimeIndicator({ connected, lastEventType, compact = false }: RealTimeIndicatorProps) {
  const [flash, setFlash] = useState(false);
  const [displayEvent, setDisplayEvent] = useState<string | null>(null);

  useEffect(() => {
    if (lastEventType) {
      setDisplayEvent(EVENT_LABELS[lastEventType] || "Update received");
      setFlash(true);
      const t1 = setTimeout(() => setFlash(false), 600);
      const t2 = setTimeout(() => setDisplayEvent(null), 3000);
      return () => { clearTimeout(t1); clearTimeout(t2); };
    }
  }, [lastEventType]);

  if (compact) {
    return (
      <div className="relative flex items-center justify-center w-5 h-5">
        <motion.div
          animate={connected ? { scale: [1, 1.4, 1], opacity: [0.6, 0.2, 0.6] } : {}}
          transition={{ duration: 2, repeat: Infinity, ease: "easeInOut" }}
          className={`absolute w-4 h-4 rounded-full ${connected ? "bg-[#39B54A]/20" : "bg-gray-200/0"}`}
        />
        <div className={`w-2 h-2 rounded-full ${connected ? "bg-[#39B54A]" : "bg-gray-400"}`} />
      </div>
    );
  }

  return (
    <div className="flex items-center gap-2">
      <div className="relative flex items-center justify-center w-5 h-5">
        {connected && (
          <motion.div
            animate={{ scale: [1, 1.6, 1], opacity: [0.5, 0, 0.5] }}
            transition={{ duration: 2, repeat: Infinity, ease: "easeInOut" }}
            className="absolute w-4 h-4 rounded-full bg-[#39B54A]/25"
          />
        )}
        <div className={`w-2 h-2 rounded-full ${connected ? "bg-[#39B54A]" : "bg-gray-400"}`} />
      </div>
      <div className="flex flex-col">
        <AnimatePresence mode="wait">
          {flash && displayEvent ? (
            <motion.span
              key="event"
              initial={{ opacity: 0, y: -4 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: 4 }}
              className="text-[10px] font-medium text-[#39B54A]"
            >
              {displayEvent}
            </motion.span>
          ) : (
            <motion.span
              key="status"
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              className={`text-[10px] font-medium ${connected ? "text-[#39B54A]" : "text-gray-400"}`}
            >
              {connected ? "Live" : "Offline"}
            </motion.span>
          )}
        </AnimatePresence>
      </div>
    </div>
  );
}

"use client";

import { useState, useEffect, useCallback, useRef } from "react";
import { useRouter } from "next/navigation";
import { motion, AnimatePresence } from "framer-motion";
import {
  FileText,
  Upload,
  CheckCircle2,
  XCircle,
  Clock,
  AlertTriangle,
  Eye,
  Trash2,
  RefreshCw,
  Info,
  FileBadge,
  FileCheck,
  X,
  Plus,
  ShieldCheck,
} from "lucide-react";
import CaregiverLayout from "../components/CaregiverLayout";
import { authService } from "@/features/auth/services/auth.service";
import { useAuthContext } from "@/context/AuthContext";
import { documentService } from "@/services";
import type {
  Document as CareDocument,
  DocumentType,
} from "@/services/api/document.service";

// ─── Document type definitions ────────────────────────────────────────────────

const DOC_TYPES: {
  value: DocumentType;
  label: string;
  description: string;
  icon: React.ElementType;
}[] = [
  {
    value: "id_proof",
    label: "ID Proof",
    description: "National ID, Passport, or Driver's License",
    icon: FileBadge,
  },
  {
    value: "address_proof",
    label: "Address Proof",
    description: "Utility bill or bank statement (last 3 months)",
    icon: FileText,
  },
  {
    value: "certification",
    label: "Certification",
    description: "Care-related certifications or training records",
    icon: FileCheck,
  },
  {
    value: "background_check",
    label: "Background Check",
    description: "Police clearance or DBS certificate",
    icon: ShieldCheck,
  },
];

const STATUS_CONFIG: Record<
  string,
  { label: string; color: string; bg: string; icon: React.ElementType }
> = {
  pending: {
    label: "Under Review",
    color: "text-amber-600",
    bg: "bg-amber-50 border-amber-200",
    icon: Clock,
  },
  verified: {
    label: "Verified",
    color: "text-green-600",
    bg: "bg-green-50 border-green-200",
    icon: CheckCircle2,
  },
  rejected: {
    label: "Rejected",
    color: "text-red-600",
    bg: "bg-red-50 border-red-200",
    icon: XCircle,
  },
};

// ─── Helpers ──────────────────────────────────────────────────────────────────

function formatFileSize(bytes?: number): string {
  if (!bytes) return "—";
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
  return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
}

function formatDate(dateStr?: string): string {
  if (!dateStr) return "—";
  return new Date(dateStr).toLocaleDateString("en-US", {
    day: "numeric",
    month: "short",
    year: "numeric",
  });
}

// ─── Upload Modal ─────────────────────────────────────────────────────────────

interface UploadModalProps {
  onClose: () => void;
  onSuccess: () => void;
  preSelectedType?: DocumentType | undefined;
}

function UploadModal({
  onClose,
  onSuccess,
  preSelectedType,
}: UploadModalProps) {
  const [selectedType, setSelectedType] = useState<DocumentType | "">(
    preSelectedType ?? "",
  );
  const [selectedFile, setSelectedFile] = useState<File | null>(null);
  const [preview, setPreview] = useState<string | null>(null);
  const [isUploading, setIsUploading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [dragOver, setDragOver] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileSelect = (file: File) => {
    const allowed = [
      "image/jpeg",
      "image/png",
      "image/webp",
      "application/pdf",
    ];
    if (!allowed.includes(file.type)) {
      setError("Only JPEG, PNG, WebP, or PDF files are allowed.");
      return;
    }
    if (file.size > 10 * 1024 * 1024) {
      setError("File size must be under 10 MB.");
      return;
    }
    setError(null);
    setSelectedFile(file);
    if (file.type.startsWith("image/")) {
      setPreview(URL.createObjectURL(file));
    } else {
      setPreview(null);
    }
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) handleFileSelect(file);
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setDragOver(false);
    const file = e.dataTransfer.files?.[0];
    if (file) handleFileSelect(file);
  };

  const handleUpload = async () => {
    if (!selectedType || !selectedFile) {
      setError("Please select a document type and file.");
      return;
    }
    setIsUploading(true);
    setError(null);
    try {
      await documentService.uploadDocument({
        documentType: selectedType,
        file: selectedFile,
      });
      onSuccess();
      onClose();
    } catch (err) {
      setError(
        err instanceof Error ? err.message : "Upload failed. Please try again.",
      );
    } finally {
      setIsUploading(false);
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm">
      <motion.div
        initial={{ opacity: 0, scale: 0.95, y: 12 }}
        animate={{ opacity: 1, scale: 1, y: 0 }}
        exit={{ opacity: 0, scale: 0.95, y: 12 }}
        transition={{ duration: 0.2 }}
        className="bg-white rounded-2xl shadow-2xl w-full max-w-lg max-h-[90vh] overflow-y-auto"
      >
        {/* Header */}
        <div className="flex items-center justify-between p-6 border-b border-gray-100 sticky top-0 bg-white z-10">
          <div>
            <h2 className="text-lg font-bold text-gray-900">Upload Document</h2>
            <p className="text-sm text-gray-500 mt-0.5">
              Select a type and upload your file for admin review
            </p>
          </div>
          <button
            onClick={onClose}
            className="p-2 hover:bg-gray-100 rounded-xl transition text-gray-400 hover:text-gray-600"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        <div className="p-6 space-y-5">
          {/* Document Type Selection */}
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">
              Document Type <span className="text-red-500">*</span>
            </label>
            <div className="grid grid-cols-2 gap-2">
              {DOC_TYPES.map(({ value, label, description, icon: Icon }) => (
                <button
                  key={value}
                  type="button"
                  onClick={() => setSelectedType(value)}
                  className={`p-3 rounded-xl border-2 text-left transition-all ${
                    selectedType === value
                      ? "border-[#39B54A] bg-[#39B54A]/5"
                      : "border-gray-200 hover:border-gray-300 hover:bg-gray-50/60"
                  }`}
                >
                  <Icon
                    className={`w-4 h-4 mb-1.5 ${
                      selectedType === value
                        ? "text-[#39B54A]"
                        : "text-gray-400"
                    }`}
                  />
                  <p
                    className={`text-xs font-semibold leading-tight ${
                      selectedType === value
                        ? "text-[#39B54A]"
                        : "text-gray-700"
                    }`}
                  >
                    {label}
                  </p>
                  <p className="text-[10px] text-gray-400 leading-tight mt-0.5">
                    {description}
                  </p>
                </button>
              ))}
            </div>
          </div>

          {/* File Upload */}
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">
              File <span className="text-red-500">*</span>
            </label>
            <div
              onClick={() => fileInputRef.current?.click()}
              onDragOver={(e) => {
                e.preventDefault();
                setDragOver(true);
              }}
              onDragLeave={() => setDragOver(false)}
              onDrop={handleDrop}
              className={`border-2 border-dashed rounded-xl p-6 text-center cursor-pointer transition-all ${
                dragOver
                  ? "border-[#39B54A] bg-[#39B54A]/5 scale-[1.01]"
                  : selectedFile
                    ? "border-[#39B54A] bg-[#39B54A]/5"
                    : "border-gray-200 hover:border-gray-300 hover:bg-gray-50/60"
              }`}
            >
              <input
                ref={fileInputRef}
                type="file"
                accept="image/jpeg,image/png,image/webp,application/pdf"
                onChange={handleInputChange}
                className="hidden"
              />

              {preview ? (
                <img
                  src={preview}
                  alt="Preview"
                  className="mx-auto max-h-32 object-contain rounded-lg mb-3"
                />
              ) : selectedFile ? (
                <div className="w-14 h-14 bg-[#39B54A]/10 rounded-xl flex items-center justify-center mx-auto mb-3">
                  <FileText className="w-7 h-7 text-[#39B54A]" />
                </div>
              ) : (
                <div className="w-14 h-14 bg-gray-100 rounded-xl flex items-center justify-center mx-auto mb-3">
                  <Upload className="w-7 h-7 text-gray-300" />
                </div>
              )}

              {selectedFile ? (
                <div>
                  <p className="text-sm font-semibold text-gray-800 truncate max-w-xs mx-auto">
                    {selectedFile.name}
                  </p>
                  <p className="text-xs text-gray-400 mt-0.5">
                    {formatFileSize(selectedFile.size)}
                  </p>
                  <p className="text-xs text-[#39B54A] mt-1 font-medium">
                    Click to change file
                  </p>
                </div>
              ) : (
                <div>
                  <p className="text-sm font-medium text-gray-600">
                    Click to select or drag & drop
                  </p>
                  <p className="text-xs text-gray-400 mt-1">
                    JPEG, PNG, WebP, PDF — max 10 MB
                  </p>
                </div>
              )}
            </div>
          </div>

          {/* Error Message */}
          <AnimatePresence>
            {error && (
              <motion.div
                initial={{ opacity: 0, height: 0 }}
                animate={{ opacity: 1, height: "auto" }}
                exit={{ opacity: 0, height: 0 }}
                className="flex items-center gap-2 p-3 bg-red-50 border border-red-200 rounded-xl text-red-600 text-sm overflow-hidden"
              >
                <AlertTriangle className="w-4 h-4 shrink-0" />
                {error}
              </motion.div>
            )}
          </AnimatePresence>
        </div>

        {/* Footer */}
        <div className="flex gap-3 p-6 pt-0">
          <button
            onClick={onClose}
            className="flex-1 py-2.5 border border-gray-200 text-gray-700 rounded-xl font-medium hover:bg-gray-50 transition text-sm"
          >
            Cancel
          </button>
          <button
            onClick={handleUpload}
            disabled={isUploading || !selectedType || !selectedFile}
            className="flex-1 py-2.5 bg-[#39B54A] hover:bg-[#2d913c] disabled:bg-gray-200 disabled:cursor-not-allowed text-white disabled:text-gray-400 rounded-xl font-semibold transition text-sm flex items-center justify-center gap-2"
          >
            {isUploading ? (
              <>
                <RefreshCw className="w-4 h-4 animate-spin" />
                Uploading…
              </>
            ) : (
              <>
                <Upload className="w-4 h-4" />
                Upload Document
              </>
            )}
          </button>
        </div>
      </motion.div>
    </div>
  );
}

// ─── Document Card ────────────────────────────────────────────────────────────

interface DocumentCardProps {
  doc: CareDocument;
  onDelete: (id: string) => Promise<void>;
  onReupload: (type: DocumentType) => void;
  isDeleting: boolean;
}

function DocumentCard({
  doc,
  onDelete,
  onReupload,
  isDeleting,
}: DocumentCardProps) {
  const statusKey = doc.status in STATUS_CONFIG ? doc.status : "pending";
  const status = STATUS_CONFIG[statusKey];
  const StatusIcon = status.icon;
  const effectiveType = (doc.documentType ??
    (doc as unknown as { type?: string }).type) as DocumentType | undefined;
  const docTypeDef = DOC_TYPES.find((t) => t.value === effectiveType);
  const DocIcon = docTypeDef?.icon ?? FileText;
  const fileUrl = doc.fileUrl ?? (doc as unknown as { url?: string }).url;

  return (
    <motion.div
      layout
      initial={{ opacity: 0, y: 12 }}
      animate={{ opacity: 1, y: 0 }}
      exit={{ opacity: 0, scale: 0.95 }}
      className={`bg-white border border-gray-200 rounded-2xl p-5 hover:shadow-md transition-all ${
        isDeleting ? "opacity-50 pointer-events-none" : ""
      }`}
    >
      <div className="flex items-start gap-4">
        {/* Icon */}
        <div className="w-11 h-11 bg-gray-100 rounded-xl flex items-center justify-center shrink-0">
          <DocIcon className="w-5 h-5 text-gray-500" />
        </div>

        {/* Info */}
        <div className="flex-1 min-w-0">
          <div className="flex items-start justify-between gap-2 flex-wrap">
            <div className="min-w-0">
              <p className="text-sm font-semibold text-gray-800">
                {docTypeDef?.label ?? "Document"}
              </p>
              <p className="text-xs text-gray-400 truncate mt-0.5">
                {doc.originalName ?? doc.fileName}
              </p>
            </div>
            {/* Status Badge */}
            <span
              className={`shrink-0 inline-flex items-center gap-1 px-2.5 py-1 rounded-full text-xs font-medium border ${status.bg} ${status.color}`}
            >
              <StatusIcon className="w-3 h-3" />
              {status.label}
            </span>
          </div>

          {/* Meta */}
          <div className="flex flex-wrap items-center gap-x-3 gap-y-1 mt-2 text-xs text-gray-400">
            <span>{formatFileSize(doc.size ?? doc.fileSize)}</span>
            <span>·</span>
            <span>Uploaded {formatDate(doc.createdAt)}</span>
            {doc.verifiedAt && (
              <>
                <span>·</span>
                <span className="text-green-500">
                  Verified {formatDate(doc.verifiedAt)}
                </span>
              </>
            )}
          </div>

          {/* Rejection reason */}
          {doc.status === "rejected" && doc.rejectionReason && (
            <div className="mt-3 p-3 bg-red-50 border border-red-200 rounded-xl">
              <p className="text-xs font-semibold text-red-700 mb-1">
                Rejection reason:
              </p>
              <p className="text-xs text-red-600 leading-relaxed">
                {doc.rejectionReason}
              </p>
            </div>
          )}
        </div>
      </div>

      {/* Actions */}
      <div className="flex gap-2 mt-4 pt-4 border-t border-gray-100">
        {fileUrl ? (
          <a
            href={fileUrl}
            target="_blank"
            rel="noopener noreferrer"
            className="flex-1 py-2 text-xs font-medium text-gray-700 border border-gray-200 rounded-xl flex items-center justify-center gap-1.5 hover:bg-gray-50 transition"
          >
            <Eye className="w-3.5 h-3.5" />
            View File
          </a>
        ) : null}

        {doc.status === "rejected" && effectiveType && (
          <button
            onClick={() => onReupload(effectiveType)}
            className="flex-1 py-2 text-xs font-medium text-[#39B54A] border border-[#39B54A] rounded-xl flex items-center justify-center gap-1.5 hover:bg-[#39B54A]/5 transition"
          >
            <RefreshCw className="w-3.5 h-3.5" />
            Re-upload
          </button>
        )}

        <button
          onClick={() => void onDelete(doc._id)}
          disabled={isDeleting}
          className="p-2 text-gray-400 border border-gray-200 rounded-xl hover:bg-red-50 hover:text-red-500 hover:border-red-200 transition disabled:opacity-50"
          title="Delete document"
        >
          {isDeleting ? (
            <RefreshCw className="w-3.5 h-3.5 animate-spin" />
          ) : (
            <Trash2 className="w-3.5 h-3.5" />
          )}
        </button>
      </div>
    </motion.div>
  );
}

// ─── Stat Card ────────────────────────────────────────────────────────────────

interface StatCardProps {
  label: string;
  value: number;
  color: string;
  bg: string;
  icon: React.ElementType;
  active: boolean;
  onClick: () => void;
}

function StatCard({
  label,
  value,
  color,
  bg,
  icon: Icon,
  active,
  onClick,
}: StatCardProps) {
  return (
    <button
      onClick={onClick}
      className={`${bg} border-2 rounded-2xl p-4 text-center transition-all hover:shadow-md w-full ${
        active ? "border-current shadow-md scale-[1.02]" : "border-gray-200"
      }`}
    >
      <div
        className={`w-9 h-9 rounded-xl flex items-center justify-center mx-auto mb-2 ${bg}`}
      >
        <Icon className={`w-5 h-5 ${color}`} />
      </div>
      <p className={`text-2xl font-bold ${color}`}>{value}</p>
      <p className="text-xs text-gray-500 mt-0.5 font-medium">{label}</p>
    </button>
  );
}

// ─── Main Page ────────────────────────────────────────────────────────────────

export default function CaregiverDocumentsPage() {
  const router = useRouter();
  const { user, isLoading: isAuthLoading } = useAuthContext();
  const [documents, setDocuments] = useState<CareDocument[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [showUpload, setShowUpload] = useState(false);
  const [reuploadType, setReuploadType] = useState<DocumentType | undefined>(
    undefined,
  );
  const [deletingId, setDeletingId] = useState<string | null>(null);
  const [statusFilter, setStatusFilter] = useState<string>("all");
  const loadedForUserRef = useRef<string | null>(null);

  // ── Load Documents ──────────────────────────────────────────────────────────
  const loadDocuments = useCallback(async () => {
    setIsLoading(true);
    setError(null);
    try {
      const res = await documentService.getMyDocuments();
      const docs = res.data?.documents ?? [];
      setDocuments(docs);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to load documents");
    } finally {
      setIsLoading(false);
    }
  }, []);

  useEffect(() => {
    if (isAuthLoading) {
      return;
    }

    if (!user) {
      router.replace("/login?redirect=/dashboard/caregiver/documents");
      return;
    }

    if (user.role !== "caregiver") {
      const fallbackRoute = authService.getDashboardPathForRole(user.role);
      router.replace(fallbackRoute || "/dashboard");
      return;
    }

    const currentUserId = user._id ?? null;
    if (loadedForUserRef.current === currentUserId) {
      return;
    }

    loadedForUserRef.current = currentUserId;
    void loadDocuments();
  }, [isAuthLoading, user, router, loadDocuments]);

  // ── Delete ──────────────────────────────────────────────────────────────────
  const handleDelete = async (documentId: string) => {
    if (
      !window.confirm(
        "Delete this document? This cannot be undone and you may need to re-upload for verification.",
      )
    )
      return;
    setDeletingId(documentId);
    try {
      await documentService.deleteDocument(documentId);
      setDocuments((prev) => prev.filter((d) => d._id !== documentId));
    } catch (err) {
      window.alert(
        err instanceof Error ? err.message : "Delete failed. Please try again.",
      );
    } finally {
      setDeletingId(null);
    }
  };

  const handleReupload = (type: DocumentType) => {
    setReuploadType(type);
    setShowUpload(true);
  };

  const openUpload = () => {
    setReuploadType(undefined);
    setShowUpload(true);
  };

  // ── Stats ───────────────────────────────────────────────────────────────────
  const stats = {
    total: documents.length,
    verified: documents.filter((d) => d.status === "verified").length,
    pending: documents.filter((d) => d.status === "pending").length,
    rejected: documents.filter((d) => d.status === "rejected").length,
  };

  const statCards = [
    {
      label: "Total",
      value: stats.total,
      color: "text-gray-700",
      bg: "bg-white",
      icon: FileText,
      filter: "all",
    },
    {
      label: "Verified",
      value: stats.verified,
      color: "text-green-600",
      bg: "bg-green-50",
      icon: CheckCircle2,
      filter: "verified",
    },
    {
      label: "Under Review",
      value: stats.pending,
      color: "text-amber-600",
      bg: "bg-amber-50",
      icon: Clock,
      filter: "pending",
    },
    {
      label: "Rejected",
      value: stats.rejected,
      color: "text-red-600",
      bg: "bg-red-50",
      icon: XCircle,
      filter: "rejected",
    },
  ];

  // ── Filtered documents ──────────────────────────────────────────────────────
  const filteredDocs =
    statusFilter === "all"
      ? documents
      : documents.filter((d) => d.status === statusFilter);

  // ── Render ──────────────────────────────────────────────────────────────────
  return (
    <CaregiverLayout>
      <div className="max-w-5xl mx-auto px-4 sm:px-6 py-8">
        {/* Header */}
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 mb-8">
          <div>
            <h1 className="text-2xl font-bold text-gray-900">My Documents</h1>
            <p className="text-sm text-gray-500 mt-1">
              Upload and manage your verification documents. Admin reviews each
              submission within 1–3 business days.
            </p>
          </div>
          <button
            onClick={openUpload}
            className="inline-flex items-center gap-2 px-4 py-2.5 bg-[#39B54A] hover:bg-[#2d913c] text-white rounded-xl font-semibold text-sm transition shadow-sm hover:shadow-md shrink-0"
          >
            <Plus className="w-4 h-4" />
            Upload Document
          </button>
        </div>

        {/* Stats */}
        <div className="grid grid-cols-2 sm:grid-cols-4 gap-3 mb-6">
          {statCards.map((s) => (
            <StatCard
              key={s.filter}
              label={s.label}
              value={s.value}
              color={s.color}
              bg={s.bg}
              icon={s.icon}
              active={statusFilter === s.filter}
              onClick={() =>
                setStatusFilter(statusFilter === s.filter ? "all" : s.filter)
              }
            />
          ))}
        </div>

        {/* Info Banner */}
        <div className="flex items-start gap-3 p-4 bg-blue-50 border border-blue-200 rounded-xl mb-6">
          <Info className="w-4 h-4 text-blue-500 mt-0.5 shrink-0" />
          <p className="text-sm text-blue-700 leading-relaxed">
            <span className="font-semibold">Required documents:</span> ID Proof,
            Address Proof, and at least one Certification are required to
            complete your caregiver verification.
          </p>
        </div>

        {/* Active filter indicator */}
        {statusFilter !== "all" && (
          <div className="flex items-center gap-2 mb-4">
            <span className="text-sm text-gray-500">
              Showing{" "}
              <span className="font-medium text-gray-700">
                {filteredDocs.length}
              </span>{" "}
              {statusFilter} document{filteredDocs.length !== 1 ? "s" : ""}
            </span>
            <button
              onClick={() => setStatusFilter("all")}
              className="text-xs text-[#39B54A] hover:underline font-medium"
            >
              Clear filter
            </button>
          </div>
        )}

        {/* Content */}
        {isLoading ? (
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            {[1, 2, 3, 4].map((i) => (
              <div
                key={i}
                className="bg-white border border-gray-200 rounded-2xl p-5 animate-pulse"
              >
                <div className="flex gap-3">
                  <div className="w-11 h-11 bg-gray-100 rounded-xl shrink-0" />
                  <div className="flex-1 space-y-2">
                    <div className="h-4 bg-gray-100 rounded w-2/3" />
                    <div className="h-3 bg-gray-100 rounded w-3/4" />
                    <div className="h-3 bg-gray-100 rounded w-1/2" />
                  </div>
                </div>
                <div className="mt-4 pt-4 border-t border-gray-100 flex gap-2">
                  <div className="flex-1 h-8 bg-gray-100 rounded-xl" />
                  <div className="w-8 h-8 bg-gray-100 rounded-xl" />
                </div>
              </div>
            ))}
          </div>
        ) : error ? (
          <div className="text-center py-16 bg-white border border-gray-200 rounded-2xl">
            <AlertTriangle className="w-12 h-12 text-red-400 mx-auto mb-4" />
            <h3 className="text-lg font-semibold text-gray-800 mb-2">
              Failed to Load Documents
            </h3>
            <p className="text-gray-500 text-sm mb-6">{error}</p>
            <button
              onClick={() => void loadDocuments()}
              className="inline-flex items-center gap-2 px-4 py-2 bg-[#39B54A] text-white rounded-xl text-sm font-medium hover:bg-[#2d913c] transition"
            >
              <RefreshCw className="w-4 h-4" />
              Try Again
            </button>
          </div>
        ) : filteredDocs.length === 0 ? (
          <div className="text-center py-16 bg-white border border-gray-200 rounded-2xl">
            <div className="w-20 h-20 bg-gray-100 rounded-2xl flex items-center justify-center mx-auto mb-5">
              <FileText className="w-10 h-10 text-gray-300" />
            </div>
            <h3 className="text-lg font-semibold text-gray-800 mb-2">
              {statusFilter === "all"
                ? "No documents uploaded yet"
                : `No ${statusFilter} documents`}
            </h3>
            <p className="text-gray-500 text-sm mb-6 max-w-sm mx-auto">
              {statusFilter === "all"
                ? "Upload your ID proof, certifications, and other required documents to complete your verification and start accepting bookings."
                : `You have no documents with "${statusFilter}" status.`}
            </p>
            {statusFilter === "all" ? (
              <button
                onClick={openUpload}
                className="inline-flex items-center gap-2 px-5 py-2.5 bg-[#39B54A] text-white rounded-xl text-sm font-semibold hover:bg-[#2d913c] transition"
              >
                <Upload className="w-4 h-4" />
                Upload First Document
              </button>
            ) : (
              <button
                onClick={() => setStatusFilter("all")}
                className="text-sm text-[#39B54A] hover:underline font-medium"
              >
                View all documents
              </button>
            )}
          </div>
        ) : (
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            <AnimatePresence mode="popLayout">
              {filteredDocs.map((doc) => (
                <DocumentCard
                  key={doc._id}
                  doc={doc}
                  onDelete={handleDelete}
                  onReupload={handleReupload}
                  isDeleting={deletingId === doc._id}
                />
              ))}
            </AnimatePresence>
          </div>
        )}
      </div>

      {/* Upload Modal */}
      <AnimatePresence>
        {showUpload && (
          <UploadModal
            key="upload-modal"
            onClose={() => {
              setShowUpload(false);
              setReuploadType(undefined);
            }}
            onSuccess={() => void loadDocuments()}
            {...(reuploadType !== undefined
              ? { preSelectedType: reuploadType }
              : {})}
          />
        )}
      </AnimatePresence>
    </CaregiverLayout>
  );
}

"use client";

import { useEffect, useMemo, useState, type ChangeEvent } from "react";
import Link from "next/link";
import { useSearchParams } from "next/navigation";
import {
  AlertCircle,
  AlertTriangle,
  CalendarDays,
  Check,
  CheckCircle2,
  ChevronLeft,
  ChevronRight,
  Clock3,
  FileImage,
  Loader2,
  MapPin,
  MessageCircle,
  ShieldCheck,
} from "lucide-react";
import {
  bookingService,
  type Booking,
  type BookingTrackingLog,
} from "@/features/booking/services";
import {
  useCaregiverActionCenter,
  useCaregiverTracking,
} from "@/hooks/useDashboardData";
import { CaregiverLayout } from "../components";

type CalendarMode = "month" | "week";

type TrackingDayStatus = "completed" | "pending" | "issue" | "none";

const toDateOnly = (value: Date | string): Date => {
  const date = new Date(value);
  date.setHours(0, 0, 0, 0);
  return date;
};

const toDateKey = (value: Date | string): string => {
  const date = toDateOnly(value);
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, "0");
  const day = String(date.getDate()).padStart(2, "0");
  return `${year}-${month}-${day}`;
};

const fromDateKey = (dateKey: string): Date => {
  return new Date(`${dateKey}T00:00:00`);
};

const isWithinBookingWindow = (
  date: Date,
  booking: Pick<Booking, "schedule">
): boolean => {
  const check = toDateOnly(date);
  const start = toDateOnly(booking.schedule.startDate);
  const end = toDateOnly(booking.schedule.endDate ?? booking.schedule.startDate);
  return check >= start && check <= end;
};

const buildMonthGrid = (viewDate: Date): Date[] => {
  const year = viewDate.getFullYear();
  const month = viewDate.getMonth();
  const firstDay = new Date(year, month, 1);
  const lastDay = new Date(year, month + 1, 0);

  const cells: Date[] = [];

  const startOffset = firstDay.getDay();
  for (let i = startOffset - 1; i >= 0; i -= 1) {
    cells.push(new Date(year, month, -i));
  }

  for (let day = 1; day <= lastDay.getDate(); day += 1) {
    cells.push(new Date(year, month, day));
  }

  while (cells.length % 7 !== 0) {
    const nextDay = cells.length - (startOffset + lastDay.getDate()) + 1;
    cells.push(new Date(year, month + 1, nextDay));
  }

  return cells;
};

const buildWeek = (anchorDate: Date): Date[] => {
  const start = new Date(anchorDate);
  start.setDate(start.getDate() - start.getDay());
  start.setHours(0, 0, 0, 0);

  return Array.from({ length: 7 }, (_, index) => {
    const day = new Date(start);
    day.setDate(start.getDate() + index);
    return day;
  });
};

const formatDateLabel = (dateKey: string): string => {
  return fromDateKey(dateKey).toLocaleDateString("en-US", {
    weekday: "long",
    month: "long",
    day: "numeric",
    year: "numeric",
  });
};

const readFileAsDataUrl = (file: File): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => {
      if (typeof reader.result === "string") {
        resolve(reader.result);
        return;
      }
      reject(new Error("Unable to read selected image"));
    };
    reader.onerror = () => reject(new Error("Unable to read selected image"));
    reader.readAsDataURL(file);
  });
};

const extractErrorMessage = (error: unknown, fallback: string): string => {
  if (typeof error === "object" && error !== null) {
    const possibleError = error as {
      message?: string;
      errors?: Array<{ message?: string; msg?: string }>;
    };

    return (
      possibleError.errors?.[0]?.msg ||
      possibleError.errors?.[0]?.message ||
      possibleError.message ||
      fallback
    );
  }

  if (error instanceof Error && error.message) {
    return error.message;
  }

  return fallback;
};

const STATUS_STYLE: Record<
  TrackingDayStatus,
  { bg: string; text: string; ring: string; dot: string }
> = {
  completed: {
    bg: "bg-emerald-100",
    text: "text-emerald-700",
    ring: "ring-emerald-300",
    dot: "bg-emerald-500",
  },
  pending: {
    bg: "bg-amber-100",
    text: "text-amber-700",
    ring: "ring-amber-300",
    dot: "bg-amber-500",
  },
  issue: {
    bg: "bg-red-100",
    text: "text-red-700",
    ring: "ring-red-300",
    dot: "bg-red-500",
  },
  none: {
    bg: "bg-gray-50",
    text: "text-gray-500",
    ring: "ring-gray-200",
    dot: "bg-gray-300",
  },
};

const DAY_LABELS = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];

export default function CaregiverMyWorkPage() {
  const searchParams = useSearchParams();
  const {
    data: actionCenterData,
    isLoading: actionLoading,
    refetch: refetchActionCenter,
  } = useCaregiverActionCenter();

  const bookings = actionCenterData?.bookings ?? [];

  const [selectedBookingId, setSelectedBookingId] = useState<string>("");
  const [calendarMode, setCalendarMode] = useState<CalendarMode>("month");
  const [viewDate, setViewDate] = useState<Date>(new Date());

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [selectedDateKey, setSelectedDateKey] = useState<string>(toDateKey(new Date()));

  const [tasksCompleted, setTasksCompleted] = useState("");
  const [notes, setNotes] = useState("");
  const [issueFlag, setIssueFlag] = useState(false);
  const [issues, setIssues] = useState("");
  const [powImages, setPowImages] = useState<string[]>([]);

  const [modalError, setModalError] = useState<string | null>(null);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [actionLoadingType, setActionLoadingType] = useState<"checkin" | "checkout" | null>(null);

  useEffect(() => {
    if (bookings.length === 0) {
      return;
    }

    const bookingFromQuery = searchParams.get("bookingId");
    const matchFromQuery = bookingFromQuery
      ? bookings.find((booking) => booking._id === bookingFromQuery)
      : null;

    if (matchFromQuery) {
      setSelectedBookingId(matchFromQuery._id);
      return;
    }

    if (!selectedBookingId) {
      const preferred =
        bookings.find((booking) => booking.status === "in_progress") ??
        bookings.find((booking) => booking.status === "confirmed") ??
        bookings[0];

      if (preferred) {
        setSelectedBookingId(preferred._id);
      }
    }
  }, [bookings, searchParams, selectedBookingId]);

  const selectedBooking = useMemo(
    () => bookings.find((booking) => booking._id === selectedBookingId) ?? null,
    [bookings, selectedBookingId]
  );

  const {
    data: trackingData,
    isLoading: trackingLoading,
    refetch: refetchTracking,
  } = useCaregiverTracking(selectedBookingId || null, Boolean(selectedBookingId));

  const logsByDate = useMemo(() => {
    const map = new Map<string, BookingTrackingLog>();
    for (const log of trackingData?.trackingLogs ?? []) {
      map.set(log.dateKey, log);
    }
    return map;
  }, [trackingData?.trackingLogs]);

  const selectedLog = logsByDate.get(selectedDateKey);

  useEffect(() => {
    if (!isModalOpen) {
      return;
    }

    const log = logsByDate.get(selectedDateKey);
    setTasksCompleted(log?.tasksCompleted ?? "");
    setNotes(log?.notes ?? "");
    setIssueFlag(Boolean(log?.issueFlag));
    setIssues(log?.issues ?? "");
    setPowImages(log?.images?.map((image) => image.imageUrl) ?? []);
    setModalError(null);
  }, [isModalOpen, selectedDateKey, logsByDate]);

  const monthGrid = useMemo(() => buildMonthGrid(viewDate), [viewDate]);
  const weekGrid = useMemo(() => buildWeek(viewDate), [viewDate]);

  const todayKey = toDateKey(new Date());
  const todayLog = logsByDate.get(todayKey);

  const getDayStatus = (date: Date): TrackingDayStatus => {
    if (!selectedBooking) {
      return "none";
    }

    if (!isWithinBookingWindow(date, selectedBooking)) {
      return "none";
    }

    const key = toDateKey(date);
    const log = logsByDate.get(key);

    if (log) {
      if (log.status === "FLAGGED" || log.issueFlag || log.missed) {
        return "issue";
      }
      if (log.status === "SUBMITTED") {
        return "completed";
      }
      return "pending";
    }

    if (toDateOnly(date) <= toDateOnly(new Date())) {
      return "pending";
    }

    return "none";
  };

  const summaryCards = [
    {
      label: "Submitted",
      value: trackingData?.summary.submitted ?? 0,
      style: "bg-emerald-50 text-emerald-700 border-emerald-100",
    },
    {
      label: "Pending",
      value: trackingData?.summary.pending ?? 0,
      style: "bg-amber-50 text-amber-700 border-amber-100",
    },
    {
      label: "Flagged",
      value: trackingData?.summary.flagged ?? 0,
      style: "bg-red-50 text-red-700 border-red-100",
    },
    {
      label: "Missed",
      value: trackingData?.summary.missed ?? 0,
      style: "bg-rose-50 text-rose-700 border-rose-100",
    },
  ];

  const openDateModal = (date: Date) => {
    if (!selectedBooking || !isWithinBookingWindow(date, selectedBooking)) {
      return;
    }

    setSelectedDateKey(toDateKey(date));
    setIsModalOpen(true);
  };

  const refreshTrackingData = async () => {
    await Promise.all([refetchTracking(), refetchActionCenter()]);
  };

  const runCheckIn = async (dateKey: string) => {
    if (!selectedBooking) return;

    try {
      setActionLoadingType("checkin");
      setModalError(null);
      await bookingService.checkInTracking({
        bookingId: selectedBooking._id,
        date: dateKey,
        notes,
      });
      await refreshTrackingData();
    } catch (error) {
      setModalError(extractErrorMessage(error, "Failed to check in."));
    } finally {
      setActionLoadingType(null);
    }
  };

  const runCheckOut = async (dateKey: string) => {
    if (!selectedBooking) return;

    try {
      setActionLoadingType("checkout");
      setModalError(null);
      await bookingService.checkOutTracking({
        bookingId: selectedBooking._id,
        date: dateKey,
        notes,
      });
      await refreshTrackingData();
    } catch (error) {
      setModalError(extractErrorMessage(error, "Failed to check out."));
    } finally {
      setActionLoadingType(null);
    }
  };

  const submitDailyLog = async () => {
    if (!selectedBooking) {
      return;
    }

    if (!selectedLog?.checkInTime) {
      setModalError("Check-in is required before submitting daily report.");
      return;
    }

    if (!tasksCompleted.trim()) {
      setModalError("Task summary is required.");
      return;
    }

    if (issueFlag && powImages.length === 0) {
      setModalError("At least one proof image is required when issue is flagged.");
      return;
    }

    try {
      setIsSubmitting(true);
      setModalError(null);
      await bookingService.submitTracking({
        bookingId: selectedBooking._id,
        date: selectedDateKey,
        tasksCompleted,
        notes,
        issues,
        issueFlag,
        images: powImages,
      });

      await refreshTrackingData();
      setIsModalOpen(false);
    } catch (error) {
      setModalError(extractErrorMessage(error, "Failed to submit daily report."));
    } finally {
      setIsSubmitting(false);
    }
  };

  const handlePowUpload = async (event: ChangeEvent<HTMLInputElement>) => {
    const files = Array.from(event.target.files ?? []);
    if (files.length === 0) return;

    try {
      const converted = await Promise.all(files.map((file) => readFileAsDataUrl(file)));
      setPowImages((prev) => [...prev, ...converted]);
    } catch (error) {
      setModalError(extractErrorMessage(error, "Unable to process selected image."));
    } finally {
      event.target.value = "";
    }
  };

  const removePowImage = (index: number) => {
    setPowImages((prev) => prev.filter((_, itemIndex) => itemIndex !== index));
  };

  const showTrackingLocked =
    trackingData?.controls.trackingEnabled === false ||
    !trackingData?.agreement.accepted;

  const canEditSelectedLog =
    !selectedLog ||
    (selectedLog.status !== "SUBMITTED" && selectedLog.status !== "FLAGGED");

  if (actionLoading && !actionCenterData) {
    return (
      <CaregiverLayout pageTitle="My Work">
        <div className="h-80 bg-white rounded-2xl border border-gray-100 animate-pulse" />
      </CaregiverLayout>
    );
  }

  return (
    <CaregiverLayout pageTitle="My Work">
      <div className="space-y-6">
        <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-4">
          <div>
            <h1 className="text-2xl font-bold text-gray-900">My Work Tracking</h1>
            <p className="text-sm text-gray-500 mt-1">
              Daily attendance, proof-of-work, and trust logs for each booking.
            </p>
          </div>

          <div className="flex flex-wrap items-center gap-3">
            <select
              value={selectedBookingId}
              onChange={(event) => setSelectedBookingId(event.target.value)}
              className="px-3 py-2 rounded-xl border border-gray-200 text-sm bg-white focus:outline-none focus:ring-2 focus:ring-[#39B54A]/20"
            >
              {bookings.map((booking) => (
                <option key={booking._id} value={booking._id}>
                  {booking.bookingNumber || booking._id} · {booking.status}
                </option>
              ))}
            </select>

            <div className="flex items-center gap-1 bg-gray-100 p-1 rounded-xl">
              <button
                onClick={() => setCalendarMode("month")}
                className={`px-3 py-1.5 text-xs rounded-lg transition-colors ${
                  calendarMode === "month"
                    ? "bg-white text-gray-900 shadow-sm"
                    : "text-gray-500"
                }`}
              >
                Month
              </button>
              <button
                onClick={() => setCalendarMode("week")}
                className={`px-3 py-1.5 text-xs rounded-lg transition-colors ${
                  calendarMode === "week"
                    ? "bg-white text-gray-900 shadow-sm"
                    : "text-gray-500"
                }`}
              >
                Week
              </button>
            </div>
          </div>
        </div>

        <div className="grid grid-cols-2 lg:grid-cols-4 gap-3">
          {summaryCards.map((card) => (
            <div
              key={card.label}
              className={`p-4 rounded-xl border ${card.style}`}
            >
              <p className="text-xs font-semibold uppercase tracking-wide">{card.label}</p>
              <p className="text-2xl font-bold mt-1">{card.value}</p>
            </div>
          ))}
        </div>

        <div className="grid grid-cols-1 xl:grid-cols-12 gap-6">
          <div className="xl:col-span-8 space-y-6">
            <div className="bg-white rounded-2xl border border-gray-100 p-5">
              <div className="flex flex-wrap items-center justify-between gap-3 mb-4">
                <div className="flex items-center gap-2">
                  <button
                    onClick={() => {
                      const nextDate = new Date(viewDate);
                      nextDate.setMonth(
                        viewDate.getMonth() + (calendarMode === "month" ? -1 : 0)
                      );
                      nextDate.setDate(
                        viewDate.getDate() + (calendarMode === "week" ? -7 : 0)
                      );
                      setViewDate(nextDate);
                    }}
                    className="p-2 rounded-lg hover:bg-gray-100"
                  >
                    <ChevronLeft className="w-4 h-4 text-gray-500" />
                  </button>

                  <p className="text-sm font-semibold text-gray-800 min-w-40 text-center">
                    {calendarMode === "month"
                      ? viewDate.toLocaleDateString("en-US", {
                          month: "long",
                          year: "numeric",
                        })
                      : `${weekGrid[0].toLocaleDateString("en-US", {
                          month: "short",
                          day: "numeric",
                        })} - ${weekGrid[6].toLocaleDateString("en-US", {
                          month: "short",
                          day: "numeric",
                        })}`}
                  </p>

                  <button
                    onClick={() => {
                      const nextDate = new Date(viewDate);
                      nextDate.setMonth(
                        viewDate.getMonth() + (calendarMode === "month" ? 1 : 0)
                      );
                      nextDate.setDate(
                        viewDate.getDate() + (calendarMode === "week" ? 7 : 0)
                      );
                      setViewDate(nextDate);
                    }}
                    className="p-2 rounded-lg hover:bg-gray-100"
                  >
                    <ChevronRight className="w-4 h-4 text-gray-500" />
                  </button>
                </div>

                <div className="flex items-center gap-4 text-xs text-gray-600">
                  <span className="inline-flex items-center gap-1.5">
                    <span className="w-2.5 h-2.5 rounded-full bg-emerald-500" /> Completed
                  </span>
                  <span className="inline-flex items-center gap-1.5">
                    <span className="w-2.5 h-2.5 rounded-full bg-amber-500" /> Pending
                  </span>
                  <span className="inline-flex items-center gap-1.5">
                    <span className="w-2.5 h-2.5 rounded-full bg-red-500" /> Issue
                  </span>
                </div>
              </div>

              <div className="grid grid-cols-7 gap-2 mb-2">
                {DAY_LABELS.map((label) => (
                  <p
                    key={label}
                    className="text-[11px] text-center font-semibold text-gray-400 uppercase tracking-wide py-1"
                  >
                    {label}
                  </p>
                ))}
              </div>

              <div className="grid grid-cols-7 gap-2">
                {(calendarMode === "month" ? monthGrid : weekGrid).map((date) => {
                  const isOutsideMonth =
                    calendarMode === "month" && date.getMonth() !== viewDate.getMonth();
                  const dateKey = toDateKey(date);
                  const status = getDayStatus(date);
                  const statusStyle = STATUS_STYLE[status];
                  const isSelected = dateKey === selectedDateKey;
                  const inWindow = selectedBooking
                    ? isWithinBookingWindow(date, selectedBooking)
                    : false;

                  return (
                    <button
                      key={`${calendarMode}-${dateKey}`}
                      disabled={!inWindow}
                      onClick={() => openDateModal(date)}
                      className={`relative rounded-xl border p-2 text-left min-h-16 transition-all ${
                        inWindow ? "hover:shadow-sm" : "opacity-55 cursor-not-allowed"
                      } ${statusStyle.bg} ${statusStyle.text} ${
                        isSelected ? `ring-2 ${statusStyle.ring}` : ""
                      }`}
                    >
                      <p
                        className={`text-xs font-semibold ${
                          isOutsideMonth ? "opacity-55" : ""
                        }`}
                      >
                        {date.getDate()}
                      </p>
                      <span
                        className={`absolute right-2 bottom-2 w-2 h-2 rounded-full ${statusStyle.dot}`}
                      />
                    </button>
                  );
                })}
              </div>

              {trackingLoading && (
                <div className="mt-4 flex items-center gap-2 text-sm text-gray-500">
                  <Loader2 className="w-4 h-4 animate-spin" />
                  Refreshing tracking logs...
                </div>
              )}
            </div>

            <div className="bg-white rounded-2xl border border-gray-100 p-5">
              <h3 className="text-sm font-semibold text-gray-900 mb-3">Pending Actions</h3>
              {actionCenterData?.pendingActions?.length ? (
                <div className="space-y-2">
                  {actionCenterData.pendingActions.slice(0, 5).map((item) => (
                    <Link
                      key={item.id}
                      href={`/dashboard/caregiver/my-work?bookingId=${item.bookingId}`}
                      className="block rounded-xl border border-gray-100 p-3 hover:border-gray-200 hover:bg-gray-50 transition-colors"
                    >
                      <p className="text-xs font-semibold text-gray-800">{item.title}</p>
                      <p className="text-[11px] text-gray-500 mt-0.5">{item.subtitle}</p>
                    </Link>
                  ))}
                </div>
              ) : (
                <p className="text-xs text-gray-400">No pending actions right now.</p>
              )}
            </div>
          </div>

          <div className="xl:col-span-4">
            <div className="sticky top-24 space-y-4">
              <div className="bg-white rounded-2xl border border-gray-100 p-5">
                <h3 className="text-sm font-semibold text-gray-900 mb-3">Sticky Action Panel</h3>

                <div className="space-y-2">
                  <button
                    onClick={() => runCheckIn(todayKey)}
                    disabled={!selectedBooking || !trackingData?.controls.trackingEnabled || actionLoadingType === "checkin"}
                    className="w-full px-4 py-2.5 rounded-xl bg-[#39B54A] text-white text-sm font-medium hover:bg-primary-600 disabled:opacity-50 disabled:cursor-not-allowed"
                  >
                    {actionLoadingType === "checkin" ? "Checking in..." : "Check-in now"}
                  </button>

                  <button
                    onClick={() => {
                      setSelectedDateKey(todayKey);
                      setIsModalOpen(true);
                    }}
                    disabled={!selectedBooking || !trackingData?.controls.trackingEnabled}
                    className="w-full px-4 py-2.5 rounded-xl border border-gray-200 text-sm font-medium text-gray-700 hover:bg-gray-50 disabled:opacity-50 disabled:cursor-not-allowed"
                  >
                    Submit report
                  </button>
                </div>

                {showTrackingLocked && (
                  <div className="mt-3 p-3 rounded-xl bg-amber-50 border border-amber-100">
                    <p className="text-xs font-semibold text-amber-700">Tracking Locked</p>
                    <p className="text-[11px] text-amber-600 mt-1">
                      Booking must be active and agreement accepted before tracking.
                    </p>
                  </div>
                )}

                <div className="mt-4 pt-4 border-t border-gray-100 space-y-2">
                  <div className="flex items-center justify-between text-xs">
                    <span className="text-gray-500">Agreement</span>
                    <span
                      className={`font-semibold ${
                        trackingData?.agreement.accepted
                          ? "text-emerald-600"
                          : "text-amber-600"
                      }`}
                    >
                      {trackingData?.agreement.accepted ? "Accepted" : "Pending"}
                    </span>
                  </div>

                  <div className="flex items-center justify-between text-xs">
                    <span className="text-gray-500">Chat & Call</span>
                    <span
                      className={`font-semibold ${
                        trackingData?.controls.chatEnabled
                          ? "text-emerald-600"
                          : "text-gray-500"
                      }`}
                    >
                      {trackingData?.controls.chatEnabled ? "Enabled" : "Locked"}
                    </span>
                  </div>

                  <div className="flex items-center justify-between text-xs">
                    <span className="text-gray-500">Map Visibility</span>
                    <span
                      className={`font-semibold ${
                        trackingData?.controls.mapVisible
                          ? "text-emerald-600"
                          : "text-gray-500"
                      }`}
                    >
                      {trackingData?.controls.mapVisible ? "Visible" : "Hidden"}
                    </span>
                  </div>
                </div>

                <div className="mt-4 grid grid-cols-2 gap-2">
                  <Link
                    href="/messages"
                    className="inline-flex items-center justify-center gap-1.5 px-3 py-2 text-xs rounded-xl border border-gray-200 text-gray-700 hover:bg-gray-50"
                  >
                    <MessageCircle className="w-3.5 h-3.5" /> Chat
                  </Link>
                  <Link
                    href={`/dashboard/bookings/${selectedBookingId}`}
                    className="inline-flex items-center justify-center gap-1.5 px-3 py-2 text-xs rounded-xl border border-gray-200 text-gray-700 hover:bg-gray-50"
                  >
                    <MapPin className="w-3.5 h-3.5" /> Map
                  </Link>
                </div>

                <Link
                  href={`/dashboard/bookings/${selectedBookingId}?action=dispute`}
                  className="mt-3 inline-flex w-full items-center justify-center gap-1.5 px-3 py-2 text-xs rounded-xl bg-red-50 text-red-700 border border-red-100 hover:bg-red-100"
                >
                  <AlertTriangle className="w-3.5 h-3.5" /> Raise Issue
                </Link>

                {trackingData?.agreement.pdfUrl && (
                  <div className="mt-3 pt-3 border-t border-gray-100 flex gap-2">
                    <a
                      href={trackingData.agreement.pdfUrl}
                      target="_blank"
                      rel="noreferrer"
                      className="flex-1 inline-flex items-center justify-center gap-1.5 px-3 py-2 text-xs rounded-xl border border-gray-200 text-gray-700 hover:bg-gray-50"
                    >
                      <ShieldCheck className="w-3.5 h-3.5" /> View Agreement
                    </a>
                    <a
                      href={trackingData.agreement.pdfUrl}
                      download
                      className="flex-1 inline-flex items-center justify-center gap-1.5 px-3 py-2 text-xs rounded-xl border border-gray-200 text-gray-700 hover:bg-gray-50"
                    >
                      <CalendarDays className="w-3.5 h-3.5" /> Download PDF
                    </a>
                  </div>
                )}
              </div>
            </div>
          </div>
        </div>
      </div>

      {isModalOpen && selectedBooking && (
        <div
          className="fixed inset-0 z-50 bg-black/45 backdrop-blur-[1px] flex items-center justify-center p-4"
          onClick={() => setIsModalOpen(false)}
        >
          <div
            className="w-full max-w-2xl max-h-[90vh] overflow-auto bg-white rounded-2xl border border-gray-100 p-6"
            onClick={(event) => event.stopPropagation()}
          >
            <div className="flex items-start justify-between gap-3 mb-4">
              <div>
                <h2 className="text-lg font-bold text-gray-900">Daily Tracking Sheet</h2>
                <p className="text-sm text-gray-500">{formatDateLabel(selectedDateKey)}</p>
              </div>
              <button
                onClick={() => setIsModalOpen(false)}
                className="px-3 py-1.5 rounded-lg border border-gray-200 text-xs text-gray-600 hover:bg-gray-50"
              >
                Close
              </button>
            </div>

            <div className="grid sm:grid-cols-2 gap-3 mb-4">
              <button
                onClick={() => runCheckIn(selectedDateKey)}
                disabled={Boolean(selectedLog?.checkInTime) || actionLoadingType === "checkin" || !canEditSelectedLog}
                className="inline-flex items-center justify-center gap-2 px-4 py-2.5 rounded-xl bg-emerald-50 text-emerald-700 border border-emerald-100 hover:bg-emerald-100 disabled:opacity-50"
              >
                {actionLoadingType === "checkin" ? (
                  <Loader2 className="w-4 h-4 animate-spin" />
                ) : (
                  <CheckCircle2 className="w-4 h-4" />
                )}
                {selectedLog?.checkInTime ? "Checked In" : "Check In"}
              </button>

              <button
                onClick={() => runCheckOut(selectedDateKey)}
                disabled={!selectedLog?.checkInTime || Boolean(selectedLog?.checkOutTime) || actionLoadingType === "checkout" || !canEditSelectedLog}
                className="inline-flex items-center justify-center gap-2 px-4 py-2.5 rounded-xl bg-blue-50 text-blue-700 border border-blue-100 hover:bg-blue-100 disabled:opacity-50"
              >
                {actionLoadingType === "checkout" ? (
                  <Loader2 className="w-4 h-4 animate-spin" />
                ) : (
                  <Clock3 className="w-4 h-4" />
                )}
                {selectedLog?.checkOutTime ? "Checked Out" : "Check Out"}
              </button>
            </div>

            {!canEditSelectedLog && (
              <div className="mb-4 p-3 rounded-xl bg-gray-50 border border-gray-100">
                <p className="text-xs font-medium text-gray-600">
                  This log is locked after submission and can only be updated by admin.
                </p>
              </div>
            )}

            <div className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  Task Summary
                </label>
                <textarea
                  value={tasksCompleted}
                  onChange={(event) => setTasksCompleted(event.target.value)}
                  disabled={!canEditSelectedLog}
                  rows={3}
                  placeholder="What was completed today?"
                  className="w-full px-3 py-2.5 rounded-xl border border-gray-200 text-sm focus:outline-none focus:ring-2 focus:ring-[#39B54A]/20 disabled:bg-gray-50"
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  Notes (Optional)
                </label>
                <textarea
                  value={notes}
                  onChange={(event) => setNotes(event.target.value)}
                  disabled={!canEditSelectedLog}
                  rows={2}
                  placeholder="Extra observations"
                  className="w-full px-3 py-2.5 rounded-xl border border-gray-200 text-sm focus:outline-none focus:ring-2 focus:ring-[#39B54A]/20 disabled:bg-gray-50"
                />
              </div>

              <div className="rounded-xl border border-gray-100 p-3">
                <label className="inline-flex items-center gap-2 text-sm font-medium text-gray-700">
                  <input
                    type="checkbox"
                    checked={issueFlag}
                    disabled={!canEditSelectedLog}
                    onChange={(event) => setIssueFlag(event.target.checked)}
                    className="rounded border-gray-300"
                  />
                  Flag issue for this day
                </label>

                {issueFlag && (
                  <textarea
                    value={issues}
                    onChange={(event) => setIssues(event.target.value)}
                    disabled={!canEditSelectedLog}
                    rows={2}
                    placeholder="Describe the issue"
                    className="mt-2 w-full px-3 py-2.5 rounded-xl border border-gray-200 text-sm focus:outline-none focus:ring-2 focus:ring-red-200 disabled:bg-gray-50"
                  />
                )}
              </div>

              <div>
                <p className="text-sm font-medium text-gray-700 mb-1">
                  Proof of Work (POW)
                </p>
                <label className="inline-flex items-center gap-2 px-3 py-2 rounded-xl border border-gray-200 text-xs text-gray-700 hover:bg-gray-50 cursor-pointer">
                  <FileImage className="w-4 h-4" />
                  Upload image
                  <input
                    type="file"
                    accept="image/*"
                    multiple
                    disabled={!canEditSelectedLog}
                    onChange={handlePowUpload}
                    className="hidden"
                  />
                </label>

                {powImages.length > 0 && (
                  <div className="mt-3 grid grid-cols-3 gap-2">
                    {powImages.map((imageUrl, index) => (
                      <div key={`${imageUrl.slice(0, 20)}-${index}`} className="relative">
                        <img
                          src={imageUrl}
                          alt={`Proof ${index + 1}`}
                          className="w-full h-20 rounded-lg object-cover border border-gray-200"
                        />
                        {canEditSelectedLog && (
                          <button
                            onClick={() => removePowImage(index)}
                            className="absolute -top-1 -right-1 w-5 h-5 rounded-full bg-red-500 text-white text-[10px]"
                          >
                            <Check className="w-3 h-3 mx-auto rotate-45" />
                          </button>
                        )}
                      </div>
                    ))}
                  </div>
                )}
              </div>
            </div>

            {modalError && (
              <div className="mt-4 p-3 rounded-xl bg-red-50 border border-red-100 text-red-700 text-sm inline-flex items-start gap-2">
                <AlertCircle className="w-4 h-4 mt-0.5" />
                <span>{modalError}</span>
              </div>
            )}

            <div className="mt-5 flex items-center justify-between gap-3">
              <div className="text-xs text-gray-500">
                {selectedLog?.checkInTime ? (
                  <span>Checked in at {new Date(selectedLog.checkInTime).toLocaleTimeString()}</span>
                ) : (
                  <span>Check-in required before submission</span>
                )}
              </div>

              <button
                onClick={submitDailyLog}
                disabled={
                  isSubmitting ||
                  !canEditSelectedLog ||
                  !selectedLog?.checkInTime ||
                  !tasksCompleted.trim() ||
                  (issueFlag && powImages.length === 0)
                }
                className="px-5 py-2.5 rounded-xl bg-gray-900 text-white text-sm font-medium hover:bg-gray-800 disabled:opacity-50 disabled:cursor-not-allowed"
              >
                {isSubmitting ? "Submitting..." : "Submit Daily Report"}
              </button>
            </div>
          </div>
        </div>
      )}
    </CaregiverLayout>
  );
}

"use client";

import { useEffect, useState } from "react";
import { useRouter } from "next/navigation";
import dynamic from "next/dynamic";
import { useQueryClient } from "@tanstack/react-query";
import { authService } from "@/features/auth/services";
import { useAuthContext } from "@/context/AuthContext";
import {
  useCaregiverProfile,
  useCaregiverDashboardStats,
  useCaregiverActionCenter,
} from "@/hooks/useDashboardData";
import { useRealtimeDashboard } from "@/hooks/useRealtimeBooking";
import {
  CaregiverSidebar,
  CaregiverTopBar,
  StatsCards,
  WelcomeBanner,
  ProfileCard,
  VerificationWidget,
  TodayTasksWidget,
  PendingActionsWidget,
  RatingBreakdown,
  QuickActions,
  NoticesWidget,
  NotesWidget,
  BookingStatusWidget,
  RealTimeIndicator,
} from "./components";

// Dynamic imports for heavy components — loaded after initial paint
const DashboardCharts = dynamic(() => import("./components/DashboardCharts"), {
  loading: () => <div className="h-80 bg-white rounded-2xl animate-pulse" />,
});
const JobListings = dynamic(() => import("./components/JobListings"), {
  loading: () => <div className="h-60 bg-white rounded-2xl animate-pulse" />,
});
const MessagingPanel = dynamic(() => import("./components/MessagingPanel"), {
  loading: () => <div className="h-60 bg-white rounded-2xl animate-pulse" />,
});
const RecentActivity = dynamic(() => import("./components/RecentActivity"), {
  loading: () => <div className="h-60 bg-white rounded-2xl animate-pulse" />,
});

interface DashboardStats {
  profileViews: number;
  rating: number;
  totalReviews: number;
  completionPercentage: number;
  earnings: {
    total: number;
    pending: number;
    withdrawn: number;
  };
  ratingBreakdown: {
    punctuality: number;
    professionalism: number;
    communication: number;
    qualityOfCare: number;
    valueForMoney: number;
  };
  featured: boolean;
  backgroundCheck: {
    status: string;
  };
}

interface UserProfile {
  _id: string;
  fullName: string;
  email: string;
  avatar?: string;
  role: string;
  hourlyRate?: number;
  dailyRate?: number;
  experience?: number;
  serviceTypes?: string[];
  completionPercentage?: number;
  isEmailVerified?: boolean;
}

export default function CaregiverDashboardPage() {
  const router = useRouter();
  const queryClient = useQueryClient();
  const { user: authUser, isLoading: isAuthLoading } = useAuthContext();
  const [sidebarCollapsed, setSidebarCollapsed] = useState(false);
  const [lastEventType, setLastEventType] = useState<string | undefined>(
    undefined,
  );

  // DashboardRouteGuard validates role/status/verification before rendering this page.
  const cachedUser = authService.getCurrentUser();

  // React Query: fetch profile & stats in background (cached, deduped)
  const { data: profileData, error: profileError } = useCaregiverProfile();

  const { data: statsData } = useCaregiverDashboardStats();
  const { data: actionCenterData } = useCaregiverActionCenter();

  // ── Real-time dashboard sync ──────────────────────────────────────────────
  const { connected: realtimeConnected } = useRealtimeDashboard({
    onBookingCreated: (payload) => {
      setLastEventType("booking:created");
      void queryClient.invalidateQueries({ queryKey: ["caregiver"] });
      console.info("[RT] BOOKING_CREATED", payload);
    },
    onBookingAccepted: (payload) => {
      setLastEventType("booking:accepted");
      void queryClient.invalidateQueries({ queryKey: ["caregiver"] });
      console.info("[RT] BOOKING_ACCEPTED", payload);
    },
    onTrackingFlagged: (payload) => {
      setLastEventType("tracking:flagged");
      void queryClient.invalidateQueries({ queryKey: ["caregiver"] });
      console.info("[RT] TRACKING_FLAGGED", payload);
    },
    onDisputeCreated: (payload) => {
      setLastEventType("dispute:created");
      void queryClient.invalidateQueries({ queryKey: ["caregiver"] });
      console.info("[RT] DISPUTE_CREATED", payload);
    },
    onStatsUpdated: () => {
      setLastEventType("system:stats_updated");
      void queryClient.invalidateQueries({
        queryKey: ["caregiver", "dashboardStats"],
      });
    },
    onNotification: () => {
      setLastEventType("notification:created");
      void queryClient.invalidateQueries({ queryKey: ["caregiver"] });
    },
  });

  // Use fetched data if available, otherwise use cached user for instant render
  const user = profileData
    ? (profileData as unknown as UserProfile)
    : authUser
      ? (authUser as unknown as UserProfile)
      : cachedUser
        ? (cachedUser as unknown as UserProfile)
        : null;
  const stats = statsData ? (statsData as unknown as DashboardStats) : null;

  const handleLogout = async () => {
    await authService.logout();
    router.push("/home");
  };

  useEffect(() => {
    if (isAuthLoading) {
      return;
    }

    if (!authUser) {
      router.replace("/login?redirect=/dashboard/caregiver");
      return;
    }

    if (authUser.role && authUser.role !== "caregiver") {
      const fallbackRoute = authService.getDashboardPathForRole(authUser.role);
      router.replace(fallbackRoute || "/dashboard");
    }
  }, [isAuthLoading, authUser?._id, authUser?.role, router]);

  if (isAuthLoading || !user) {
    return null;
  }

  if (profileError) {
    const err = profileError as { statusCode?: number; message?: string };
    if (err.statusCode === 401) {
      void authService.logout();
      authService.clearAuthData();
      router.replace("/login?redirect=/dashboard/caregiver");
      return null;
    }

    if (err.statusCode === 403) {
      router.replace("/dashboard/pending");
      return null;
    }
    return (
      <div className="min-h-screen bg-[#FAFBFC] flex items-center justify-center">
        <div className="text-center">
          <p className="text-red-500 mb-4">
            {err.message || "Failed to load dashboard"}
          </p>
          <button
            onClick={() => window.location.reload()}
            className="px-5 py-2.5 bg-[#39B54A] text-white rounded-xl text-sm font-medium hover:bg-primary-600 transition-colors"
          >
            Retry
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#FAFBFC]">
      {/* Sidebar */}
      <CaregiverSidebar
        collapsed={sidebarCollapsed}
        onToggle={() => setSidebarCollapsed(!sidebarCollapsed)}
        user={user}
        onLogout={handleLogout}
      />

      {/* Main wrapper with left margin for sidebar */}
      <div
        className={`transition-all duration-300 ${
          sidebarCollapsed ? "ml-18" : "ml-65"
        }`}
      >
        {/* Top Bar */}
        <CaregiverTopBar user={user} />

        {/* Main Content */}
        <main>
          <div className="max-w-350 mx-auto px-6 py-6 space-y-6">
            {/* Welcome Banner */}
            <div className="flex items-start justify-between gap-4">
              <div className="flex-1">
                <WelcomeBanner
                  userName={user?.fullName ?? ""}
                  completionPercentage={stats?.completionPercentage || 0}
                />
              </div>
              {/* Real-time connection indicator */}
              <div className="mt-1 shrink-0">
                <RealTimeIndicator
                  connected={realtimeConnected}
                  {...(lastEventType ? { lastEventType } : {})}
                />
              </div>
            </div>

            {/* Stats Cards */}
            <StatsCards actionMetrics={actionCenterData?.metrics ?? null} />

            {/* Main Grid: Content + Sidebar Widgets */}
            <div className="grid grid-cols-1 xl:grid-cols-12 gap-6">
              {/* Left Content - 8 cols */}
              <div className="xl:col-span-8 space-y-6">
                {/* Charts */}
                <DashboardCharts />

                {/* Job Listings */}
                <JobListings />

                {/* Messaging Panel */}
                <MessagingPanel />

                {/* Recent Activity */}
                <RecentActivity />
              </div>

              {/* Right Sidebar Widgets - 4 cols */}
              <div className="xl:col-span-4 space-y-5">
                {/* Profile Card */}
                <ProfileCard user={user} stats={stats} />

                {/* Verification Status */}
                <VerificationWidget stats={stats} />

                {/* Booking Status — real-time aware */}
                <BookingStatusWidget
                  bookings={actionCenterData?.bookings ?? []}
                  isLoading={!actionCenterData}
                />

                {/* Action Center Widgets */}
                <TodayTasksWidget items={actionCenterData?.todayTasks ?? []} />
                <PendingActionsWidget
                  items={actionCenterData?.pendingActions ?? []}
                />

                {/* Quick Actions */}
                <QuickActions />

                {/* Notice Board */}
                <NoticesWidget />

                {/* My Notes */}
                <NotesWidget />

                {/* Performance Ratings */}
                <RatingBreakdown stats={stats} />
              </div>
            </div>
          </div>
        </main>
      </div>
    </div>
  );
}

"use client";

