        <div className="w-8 h-8 border-3 border-[#4461F2] border-t-transparent rounded-full animate-spin" />
      </div>
    );
  }

  return (
    <DashboardLayout user={user}>
      <NotesPage userRole="careseeker" />
    </DashboardLayout>
  );
}

