  welcome: "Welcome",
  account_activated: "Account Activated",
  account_suspended: "Account Suspended",
};

const getNotificationIcon = (type: NotificationType): React.ElementType => {
  if (type.startsWith("booking_") || type === "check_in" || type === "check_out")
    return CalendarDays;
  if (type.startsWith("check_")) return Clock;
  if (type.startsWith("care_report") || type === "incident_reported") return FileText;
  if (type.startsWith("payment_") || type.startsWith("dispute_")) return CreditCard;
  if (type.startsWith("document_")) return FileText;
  if (type.startsWith("profile_")) return UserCheck;
  if (type.startsWith("review_")) return Star;
  if (type.startsWith("message") || type === "new_message") return MessageSquare;
  if (type.startsWith("system_")) return Megaphone;
  if (type === "welcome" || type === "account_activated") return CheckCircle2;
  if (type === "account_suspended") return Shield;
  return Bell;
};

const getNotificationIconColor = (type: NotificationType): { bg: string; text: string } => {
  if (type.includes("confirmed") || type.includes("approved") || type.includes("completed") || type.includes("activated") || type === "welcome")
    return { bg: "bg-[#39B54A]/10", text: "text-[#39B54A]" };
  if (type.includes("rejected") || type.includes("cancelled") || type.includes("failed") || type.includes("suspended"))
    return { bg: "bg-red-50", text: "text-red-500" };
  if (type.includes("pending") || type.includes("reminder") || type.includes("due"))
    return { bg: "bg-amber-50", text: "text-amber-500" };
  if (type.includes("payment") || type.includes("dispute"))
    return { bg: "bg-blue-50", text: "text-blue-500" };
  if (type.includes("message"))
    return { bg: "bg-violet-50", text: "text-violet-500" };
  return { bg: "bg-gray-50", text: "text-gray-500" };
};

export default function NotificationsPage() {
  const router = useRouter();
  const { user, isLoading: isAuthLoading } = useAuthContext();
  const { socket } = useSocket();
  const [notifications, setNotifications] = useState<Notification[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [pagination, setPagination] = useState({
    total: 0,
    page: 1,
    limit: 20,
    pages: 0,
  });
  const [unreadCount, setUnreadCount] = useState(0);
  const [filters, setFilters] = useState<NotificationFilters>({
    page: 1,
    limit: 20,
  });
  const [filterTab, setFilterTab] = useState<"all" | "unread">("all");

  const fetchNotifications = useCallback(async () => {
    setIsLoading(true);
    setError(null);
    try {
      const response = await notificationService.getNotifications({
        ...filters,
        ...(filterTab === "unread" ? { read: false } : {}),
      });
      if (response.success && response.data) {
        setNotifications(response.data.notifications);
        setPagination(response.data.pagination);
        setUnreadCount(response.data.unreadCount);
      }
    } catch (err) {
      console.error("Failed to fetch notifications:", err);
      setError("Failed to load notifications");
    } finally {
      setIsLoading(false);
    }
  }, [filters, filterTab]);

  useEffect(() => {
    if (isAuthLoading) {
      return;
    }

    if (!user) {
      router.push("/login?redirect=/dashboard/notifications");
      return;
    }

    fetchNotifications();
  }, [isAuthLoading, user?._id, router, fetchNotifications]);

  // Real-time: prepend new notification when it arrives
  useEffect(() => {
    if (!socket) return;
    const handleNew = (notification: Notification) => {
      setNotifications(prev => [notification, ...prev]);
      setUnreadCount(prev => prev + 1);
    };
    socket.on("notification:new", handleNew);
    return () => { socket.off("notification:new", handleNew); };
  }, [socket]);

  const handleMarkAsRead = async (notificationId: string) => {
    try {
      await notificationService.markAsRead(notificationId);
      setNotifications((prev) =>
        prev.map((n) => (n._id === notificationId ? { ...n, read: true } : n))
      );
      setUnreadCount((prev) => Math.max(0, prev - 1));
    } catch (err) {
      console.error("Failed to mark as read:", err);
    }
  };

  const handleMarkAllAsRead = async () => {
    try {
      await notificationService.markAllAsRead();
      setNotifications((prev) => prev.map((n) => ({ ...n, read: true })));
      setUnreadCount(0);
    } catch (err) {
      console.error("Failed to mark all as read:", err);
    }
  };

  const handleDelete = async (notificationId: string) => {
    try {
      await notificationService.deleteNotification(notificationId);
      setNotifications((prev) => prev.filter((n) => n._id !== notificationId));
    } catch (err) {
      console.error("Failed to delete notification:", err);
    }
  };

  const handlePageChange = (page: number) => {
    setFilters((prev) => ({ ...prev, page }));
  };

  const formatDate = (dateString: string) => {
    const date = new Date(dateString);
    const now = new Date();
    const diffMs = now.getTime() - date.getTime();
    const diffDays = Math.floor(diffMs / 86400000);

    if (diffDays === 0) {
      return date.toLocaleTimeString("en-US", {
        hour: "numeric",
        minute: "2-digit",
      });
    } else if (diffDays === 1) {
      return "Yesterday";
    } else if (diffDays < 7) {
      return date.toLocaleDateString("en-US", { weekday: "long" });
    } else {
      return date.toLocaleDateString("en-US", {
        month: "short",
        day: "numeric",
        year: diffDays > 365 ? "numeric" : undefined,
      });
    }
  };

  const normalizeNotificationActionUrl = (raw: string): string => {
    const trimmed = raw.trim();

    if (trimmed === "/bookings") {
      return "/dashboard/bookings";
    }

    const reviewMatch = trimmed.match(/^\/bookings\/([^/?#]+)\/review$/);
    if (reviewMatch) {
      return `/dashboard/reviews/write?bookingId=${reviewMatch[1]}`;
    }

    const bookingMatch = trimmed.match(/^\/bookings\/([^/?#]+)$/);
    if (bookingMatch) {
      return `/dashboard/bookings/${bookingMatch[1]}`;
    }

    const legacyBookingPaymentMatch = trimmed.match(/^\/dashboard\/bookings\/([^/?#]+)\/payment$/);
    if (legacyBookingPaymentMatch) {
      return `/booking/${legacyBookingPaymentMatch[1]}/payment`;
    }

    return trimmed;
  };

  const getActionUrl = (notification: Notification): string | null => {
    const data = (notification.data || {}) as Record<string, unknown>;

    if (typeof data.actionUrl === "string" && data.actionUrl.trim().length > 0) {
      return normalizeNotificationActionUrl(data.actionUrl);
    }

    const bookingRef = data.bookingId ?? data.referenceId;
    if (typeof bookingRef === "string" && bookingRef.trim().length > 0) {
      return `/dashboard/bookings/${bookingRef}`;
    }

    if (data.documentId) {
      return "/dashboard?tab=documents";
    }

    if (typeof data.referenceType === "string" && data.referenceType === "payment") {
      return "/dashboard/payments";
    }

    return null;
  };

  const handleNotificationClick = async (notification: Notification) => {
    if (!notification.read) {
      await handleMarkAsRead(notification._id);
    }
    const actionUrl = getActionUrl(notification);
    if (actionUrl) {
      router.push(actionUrl);
    }
  };

  const pageContent = (
    <div className="space-y-6 max-w-4xl">
        {/* Page Header */}
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-2xl font-bold text-gray-900 tracking-tight">Notifications</h1>
            <p className="text-sm text-gray-500 mt-1">
              {unreadCount > 0
                ? `${unreadCount} unread notification${unreadCount !== 1 ? "s" : ""}`
                : "All caught up!"}
            </p>
          </div>
          {unreadCount > 0 && (
            <button
              onClick={handleMarkAllAsRead}
              className="inline-flex items-center gap-2 px-4 py-2.5 bg-[#39B54A]/10 text-[#39B54A] rounded-xl text-sm font-medium hover:bg-[#39B54A]/20 transition-colors"
            >
              <CheckCheck size={16} />
              Mark All as Read
            </button>
          )}
        </div>

        {/* Tabs */}
        <div className="bg-white rounded-xl p-1 inline-flex border border-gray-100/80">
          <button
            onClick={() => {
              setFilterTab("all");
              setFilters((prev) => ({ ...prev, page: 1 }));
            }}
            className={`px-4 py-2 text-sm font-medium rounded-lg transition-colors ${
              filterTab === "all"
                ? "bg-[#39B54A] text-white shadow-sm"
                : "text-gray-600 hover:text-gray-900 hover:bg-gray-50"
            }`}
          >
            All
          </button>
          <button
            onClick={() => {
              setFilterTab("unread");
              setFilters((prev) => ({ ...prev, page: 1 }));
            }}
            className={`px-4 py-2 text-sm font-medium rounded-lg transition-colors ${
              filterTab === "unread"
                ? "bg-[#39B54A] text-white shadow-sm"
                : "text-gray-600 hover:text-gray-900 hover:bg-gray-50"
            }`}
          >
            Unread ({unreadCount})
          </button>
        </div>

        {/* Error */}
        {error && (
          <motion.div
            initial={{ opacity: 0, y: -8 }}
            animate={{ opacity: 1, y: 0 }}
            className="flex items-center gap-3 p-4 bg-red-50 border border-red-200 rounded-xl text-red-600"
          >
            <AlertTriangle size={18} />
            <span className="text-sm font-medium">{error}</span>
          </motion.div>
        )}

        {/* Notifications List */}
        {isLoading ? (
          <div className="bg-white rounded-xl border border-gray-100/80 p-16">
            <div className="flex flex-col items-center justify-center">
              <div className="relative w-12 h-12 mb-4">
                <div className="absolute inset-0 rounded-full border-[3px] border-gray-200" />
                <div className="absolute inset-0 rounded-full border-[3px] border-[#39B54A] border-t-transparent animate-spin" />
              </div>
              <p className="text-sm text-gray-500">Loading notifications...</p>
            </div>
          </div>
        ) : notifications.length === 0 ? (
          <div className="bg-white rounded-xl border border-gray-100/80 p-16">
            <div className="flex flex-col items-center justify-center text-center">
              <div className="w-16 h-16 bg-gray-50 rounded-2xl flex items-center justify-center mb-4 ring-1 ring-gray-100">
                <BellOff size={28} className="text-gray-400" />
              </div>
              <h3 className="text-base font-semibold text-gray-900 mb-1">
                {filterTab === "unread" ? "No unread notifications" : "No notifications yet"}
              </h3>
              <p className="text-sm text-gray-500 max-w-sm">
                {filterTab === "unread"
                  ? "You've read all your notifications!"
                  : "We'll notify you when something important happens."}
              </p>
            </div>
          </div>
        ) : (
          <div className="bg-white rounded-xl border border-gray-100/80 divide-y divide-gray-50 overflow-hidden">
            <AnimatePresence>
              {notifications.map((notification, i) => {
                const actionUrl = getActionUrl(notification);
                const Icon = getNotificationIcon(notification.type);
                const iconColor = getNotificationIconColor(notification.type);

                return (
                  <motion.div
                    key={notification._id}
                    initial={{ opacity: 0 }}
                    animate={{ opacity: 1 }}
                    transition={{ delay: i * 0.02 }}
                    className={`p-4 hover:bg-gray-50/50 cursor-pointer transition-colors group ${
                      !notification.read ? "bg-[#39B54A]/2" : ""
                    }`}
                    onClick={() => handleNotificationClick(notification)}
                  >
                    <div className="flex gap-4">
                      <div
                        className={`w-10 h-10 ${iconColor.bg} rounded-xl flex items-center justify-center shrink-0 ring-1 ring-black/5`}
                      >
                        <Icon size={18} className={iconColor.text} />
                      </div>
                      <div className="flex-1 min-w-0">
                        <div className="flex items-start justify-between gap-4">
                          <div className="flex-1">
                            <p
                              className={`text-sm leading-snug ${
                                !notification.read
                                  ? "font-semibold text-gray-900"
                                  : "font-medium text-gray-700"
                              }`}
                            >
                              {notification.title}
                            </p>
                            <p className="text-sm text-gray-500 mt-0.5 line-clamp-2">
                              {notification.message}
                            </p>
                            <div className="flex items-center gap-3 mt-2">
                              <span className="text-[11px] text-gray-400">
                                {formatDate(notification.createdAt)}
                              </span>
                              <span className="text-[11px] px-2 py-0.5 bg-gray-50 text-gray-500 rounded-md ring-1 ring-gray-100">
                                {NOTIFICATION_TYPE_LABELS[notification.type] || notification.type}
                              </span>
                            </div>
                          </div>
                          <div className="flex items-center gap-1.5 shrink-0">
                            {!notification.read && (
                              <span className="w-2 h-2 bg-[#39B54A] rounded-full ring-2 ring-[#39B54A]/20" />
                            )}
                            <button
                              onClick={(e) => {
                                e.stopPropagation();
                                handleDelete(notification._id);
                              }}
                              className="p-1.5 text-gray-300 hover:text-red-500 rounded-lg hover:bg-red-50 transition-colors opacity-0 group-hover:opacity-100"
                              title="Delete notification"
                            >
                              <Trash2 size={14} />
                            </button>
                          </div>
                        </div>
                        {actionUrl && (
                          <Link
                            href={actionUrl}
                            onClick={(e) => e.stopPropagation()}
                            className="inline-flex items-center gap-1 mt-2.5 text-xs text-[#39B54A] hover:text-primary-600 font-medium"
                          >
                            View Details
                            <ExternalLink size={11} />
                          </Link>
                        )}
                      </div>
                    </div>
                  </motion.div>
                );
              })}
            </AnimatePresence>
          </div>
        )}

        {/* Pagination */}
        {pagination.pages > 1 && (
          <div className="flex items-center justify-center gap-3 mt-6">
            <button
              onClick={() => handlePageChange(pagination.page - 1)}
              disabled={pagination.page <= 1}
              className="inline-flex items-center gap-1 px-3 py-1.5 text-sm rounded-lg border border-gray-200 text-gray-600 disabled:opacity-40 hover:bg-gray-50 transition-colors"
            >
              <ChevronLeft size={14} />
              Previous
            </button>
            <span className="text-sm text-gray-500">
              Page {pagination.page} of {pagination.pages}
            </span>
            <button
              onClick={() => handlePageChange(pagination.page + 1)}
              disabled={pagination.page >= pagination.pages}
              className="inline-flex items-center gap-1 px-3 py-1.5 text-sm rounded-lg border border-gray-200 text-gray-600 disabled:opacity-40 hover:bg-gray-50 transition-colors"
            >
              Next
              <ChevronRight size={14} />
            </button>
          </div>
        )}
    </div>
  );

  if (isAuthLoading || !user) {
    return (
      <div className="min-h-screen bg-[#FAFBFC] flex items-center justify-center">
        <div className="text-center">
          <div className="relative w-14 h-14 mx-auto mb-4">
            <div className="absolute inset-0 rounded-full border-[3px] border-gray-200" />
            <div className="absolute inset-0 rounded-full border-[3px] border-[#39B54A] border-t-transparent animate-spin" />
          </div>
          <p className="text-sm text-gray-500 font-medium">Loading...</p>
        </div>
      </div>
    );
  }

  if (user.role === "caregiver") {
    return <CaregiverLayout pageTitle="Notifications">{pageContent}</CaregiverLayout>;
  }

  return <DashboardLayout user={user}>{pageContent}</DashboardLayout>;
}

"use client";

import { useEffect, useState } from "react";
import Link from "next/link";
import { useRouter } from "next/navigation";
import { AlertTriangle, CheckCircle2, Clock, Loader2, UploadCloud } from "lucide-react";
import { authService } from "@/features/auth/services/auth.service";
import { getPostAuthRoute } from "@/lib/auth-routing";
import type { User } from "@/types";

export default function PendingDashboardPage() {
  const router = useRouter();
  const [user, setUser] = useState<User | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [isRefreshing, setIsRefreshing] = useState(false);

  const refreshState = async (silent = false) => {
    if (!silent) setIsRefreshing(true);

    try {
      const response = await authService.getMe();
      const fetchedUser = response.data?.user;

      if (!fetchedUser) {
        router.replace("/login?reason=session_required");
        return;
      }

      authService.updateStoredUser(fetchedUser);
      const target = getPostAuthRoute(fetchedUser);
      if (target !== "/dashboard/pending") {
        router.replace(target);
        return;
      }

      setUser(fetchedUser);
    } catch {
      router.replace("/login?reason=session_required");
    } finally {
      setIsLoading(false);
      if (!silent) setIsRefreshing(false);
    }
  };

  useEffect(() => {
    void refreshState(true);
  }, []);

  if (isLoading || !user) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-[#F5F7FA]">
        <div className="text-center">
          <Loader2 className="w-8 h-8 animate-spin text-[#39B54A] mx-auto mb-3" />
          <p className="text-sm text-gray-600">Loading account state...</p>
        </div>
      </div>
    );
  }

  const isRejected = user.verificationStatus === "REJECTED" || user.status === "rejected";
  const isUnderReview = user.verificationStatus === "UNDER_REVIEW" || user.status === "pending_approval";

  return (
    <div className="min-h-screen bg-[#F5F7FA] p-4 sm:p-8">
      <div className="max-w-3xl mx-auto bg-white rounded-2xl shadow-sm border border-gray-200 overflow-hidden">
        <div className="px-6 py-5 bg-linear-to-r from-[#39B54A] to-primary-600 text-white">
          <h1 className="text-xl font-bold">Account Verification</h1>
          <p className="text-sm text-white/85 mt-1">
            You are signed in. Platform features unlock after trust verification.
          </p>
        </div>

        <div className="p-6 space-y-5">
          {!user.onboardingCompleted ? (
            <div className="rounded-xl border border-blue-200 bg-blue-50 p-4 flex items-start gap-3">
              <Clock className="w-5 h-5 text-blue-600 mt-0.5" />
              <div>
                <p className="font-semibold text-blue-900">Onboarding incomplete</p>
                <p className="text-sm text-blue-800 mt-1">
                  Complete role, profile, and required document steps to enter review.
                </p>
              </div>
            </div>
          ) : null}

          {isUnderReview ? (
            <div className="rounded-xl border border-amber-200 bg-amber-50 p-4 flex items-start gap-3">
              <Clock className="w-5 h-5 text-amber-600 mt-0.5" />
              <div>
                <p className="font-semibold text-amber-900">Under review</p>
                <p className="text-sm text-amber-800 mt-1">
                  Your submitted documents are being reviewed by an administrator.
                </p>
              </div>
            </div>
          ) : null}

          {isRejected ? (
            <div className="rounded-xl border border-red-200 bg-red-50 p-4 flex items-start gap-3">
              <AlertTriangle className="w-5 h-5 text-red-600 mt-0.5" />
              <div>
                <p className="font-semibold text-red-900">Verification rejected</p>
                <p className="text-sm text-red-800 mt-1">
                  {user.rejectionReason || "Please correct your documents and submit again."}
                </p>
              </div>
            </div>
          ) : null}

          {!isRejected && !isUnderReview && user.onboardingCompleted ? (
            <div className="rounded-xl border border-gray-200 bg-gray-50 p-4 flex items-start gap-3">
              <CheckCircle2 className="w-5 h-5 text-gray-600 mt-0.5" />
              <div>
                <p className="font-semibold text-gray-900">Pending verification state</p>
                <p className="text-sm text-gray-700 mt-1">
                  We are waiting for the next moderation action on your account.
                </p>
              </div>
            </div>
          ) : null}

          <div className="grid sm:grid-cols-2 gap-3">
            {!user.onboardingCompleted ? (
              <Link
                href="/onboarding"
                className="inline-flex items-center justify-center gap-2 rounded-xl bg-[#39B54A] hover:bg-primary-600 text-white font-semibold py-3 px-4 transition"
              >
                <UploadCloud className="w-4 h-4" />
                Complete onboarding
              </Link>
            ) : null}

            {isRejected ? (
              <Link
                href="/onboarding?step=documents"
                className="inline-flex items-center justify-center gap-2 rounded-xl bg-[#39B54A] hover:bg-primary-600 text-white font-semibold py-3 px-4 transition"
              >
                <UploadCloud className="w-4 h-4" />
                Re-upload documents
              </Link>
            ) : null}

            <button
              type="button"
              onClick={() => {
                void refreshState();
              }}
              className="rounded-xl border border-gray-300 text-gray-800 font-semibold py-3 px-4 hover:bg-gray-50 transition"
            >
              {isRefreshing ? "Checking..." : "Check status"}
            </button>

            <button
              type="button"
              onClick={() => {
                void authService.logout().finally(() => router.replace("/login"));
              }}
              className="rounded-xl border border-gray-300 text-gray-700 font-semibold py-3 px-4 hover:bg-gray-50 transition"
            >
              Sign out
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

