                  {job.schedule.shiftDetails && (
                    <div className="flex items-start gap-3">
                      <svg className="w-5 h-5 text-gray-400 mt-0.5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2" />
                      </svg>
                      <span className="text-gray-600">{job.schedule.shiftDetails}</span>
                    </div>
                  )}
                </div>
              </div>
            )}
          </div>

          {/* Sidebar */}
          <div className="space-y-6">
            {/* Application Deadline */}
            {job.applicationDeadline && (
              <div className="bg-orange-50 rounded-2xl border border-orange-200 p-6">
                <div className="flex items-center gap-3 mb-2">
                  <svg className="w-6 h-6 text-orange-500" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" />
                  </svg>
                  <h3 className="font-semibold text-orange-800">Application Deadline</h3>
                </div>
                <p className="text-orange-700 text-lg font-medium">{formatDate(job.applicationDeadline)}</p>
              </div>
            )}

            {/* Job Details Card */}
            <div className="bg-white rounded-2xl border border-gray-200 p-6">
              <h3 className="font-semibold text-gray-900 mb-4">Job Details</h3>
              <div className="space-y-4">
                <div className="flex items-center justify-between">
                  <span className="text-gray-500">Category</span>
                  <span className="text-gray-900 font-medium capitalize">{job.category?.replace(/_/g, " ")}</span>
                </div>
                <div className="flex items-center justify-between">
                  <span className="text-gray-500">Location</span>
                  <span className="text-gray-900 font-medium">
                    {job.location?.isRemote ? "Remote" : `${job.location?.city}, ${job.location?.state}`}
                  </span>
                </div>
                <div className="flex items-center justify-between">
                  <span className="text-gray-500">Employment</span>
                  <span className="text-gray-900 font-medium capitalize">{job.employmentType?.replace(/_/g, " ")}</span>
                </div>
                <div className="flex items-center justify-between">
                  <span className="text-gray-500">Posted</span>
                  <span className="text-gray-900 font-medium">{formatDate(job.createdAt)}</span>
                </div>
                {job.salary?.negotiable && (
                  <div className="flex items-center justify-between">
                    <span className="text-gray-500">Salary</span>
                    <span className="text-[#39B54A] font-medium">Negotiable</span>
                  </div>
                )}
              </div>
            </div>

            {/* Apply CTA */}
            <div className="bg-linear-to-br from-[#39B54A] to-[#2d913c] rounded-2xl p-6 text-white">
              <h3 className="font-semibold text-xl mb-2">Interested in this job?</h3>
              <p className="text-green-100 mb-4">Submit your application and stand out to the employer.</p>
              <button
                onClick={() => setShowApplyModal(true)}
                disabled={applied}
                className={`w-full py-3 rounded-xl font-semibold transition-colors ${
                  applied
                    ? "bg-white/20 text-white/80 cursor-default"
                    : "bg-white text-[#39B54A] hover:bg-green-50"
                }`}
              >
                {applied ? "Already Applied" : "Apply Now"}
              </button>
            </div>

            {/* Tags */}
            {job.tags && job.tags.length > 0 && (
              <div className="bg-white rounded-2xl border border-gray-200 p-6">
                <h3 className="font-semibold text-gray-900 mb-4">Tags</h3>
                <div className="flex flex-wrap gap-2">
                  {job.tags.map((tag: string, index: number) => (
                    <span
                      key={index}
                      className="px-3 py-1 bg-gray-100 text-gray-600 rounded-full text-sm"
                    >
                      #{tag}
                    </span>
                  ))}
                </div>
              </div>
            )}
          </div>
        </div>

        {/* Similar Jobs */}
        {similarJobs.length > 0 && (
          <div className="mt-12">
            <h2 className="text-2xl font-bold text-gray-900 mb-6">Similar Jobs</h2>
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
              {similarJobs.map((similarJob) => (
                <motion.div
                  key={similarJob._id}
                  whileHover={{ y: -4 }}
                  className="bg-white rounded-2xl border border-gray-200 p-6 cursor-pointer hover:shadow-lg transition-shadow"
                  onClick={() => router.push(`/jobs/${similarJob._id}`)}
                >
                  <h3 className="font-semibold text-gray-900 mb-2 line-clamp-2">{similarJob.title}</h3>
                  <p className="text-sm text-gray-500 mb-3">
                    {similarJob.location?.city}, {similarJob.location?.state}
                  </p>
                  <p className="text-[#39B54A] font-semibold">
                    {formatCurrency(similarJob.salary?.min || 0)}
                  </p>
                </motion.div>
              ))}
            </div>
          </div>
        )}
      </div>

      {/* Apply Modal */}
      <AnimatePresence>
        {showApplyModal && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4"
            onClick={() => setShowApplyModal(false)}
          >
            <motion.div
              initial={{ scale: 0.95, opacity: 0 }}
              animate={{ scale: 1, opacity: 1 }}
              exit={{ scale: 0.95, opacity: 0 }}
              onClick={(e) => e.stopPropagation()}
              className="bg-white rounded-2xl p-6 max-w-lg w-full max-h-[90vh] overflow-y-auto"
            >
              <h2 className="text-2xl font-bold text-gray-900 mb-2">Apply for this Job</h2>
              <p className="text-gray-500 mb-6">{job.title}</p>

              <div className="space-y-4">
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    Cover Letter *
                  </label>
                  <textarea
                    value={coverLetter}
                    onChange={(e) => setCoverLetter(e.target.value)}
                    placeholder="Tell the employer why you're a great fit for this position..."
                    rows={6}
                    className="w-full px-4 py-3 border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-[#39B54A] focus:border-transparent resize-none"
                    required
                  />
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    Expected Salary (₦)
                  </label>
                  <input
                    type="number"
                    value={expectedSalary}
                    onChange={(e) => setExpectedSalary(e.target.value)}
                    placeholder="Enter your expected salary"
                    className="w-full px-4 py-3 border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-[#39B54A] focus:border-transparent"
                  />
                </div>

                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    Availability
                  </label>
                  <input
                    type="text"
                    value={availability}
                    onChange={(e) => setAvailability(e.target.value)}
                    placeholder="e.g., Available immediately, 2 weeks notice"
                    className="w-full px-4 py-3 border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-[#39B54A] focus:border-transparent"
                  />
                </div>
              </div>

              <div className="flex gap-3 mt-6">
                <button
                  onClick={() => setShowApplyModal(false)}
                  className="flex-1 px-4 py-3 text-gray-600 hover:text-gray-900 border border-gray-200 rounded-xl"
                >
                  Cancel
                </button>
                <button
                  onClick={handleApply}
                  disabled={applying || !coverLetter.trim()}
                  className="flex-1 px-4 py-3 bg-[#39B54A] text-white rounded-xl hover:bg-[#2d913c] transition-colors disabled:opacity-50 flex items-center justify-center gap-2"
                >
                  {applying ? (
                    <>
                      <div className="w-5 h-5 border-2 border-white border-t-transparent rounded-full animate-spin"></div>
                      Applying...
                    </>
                  ) : (
                    "Submit Application"
                  )}
                </button>
              </div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

"use client";

// ============================================
// useMessagesPage — Custom hook
// Encapsulates ALL state, effects, and callbacks
// for the Messages page.  The component tree is
// purely presentational and just consumes what
// this hook returns.
// ============================================

import React, { useState, useEffect, useCallback, useRef } from "react";
import { useSearchParams, useRouter } from "next/navigation";
import { format, isToday, isYesterday } from "date-fns";
import { useAuthContext } from "@/context/AuthContext";
import { useSocket } from "@/context/SocketContext";
import {
  chatService,
  type Conversation,
  type Message,
  type ChatAccessStatus,
  type OptimisticMessage,
} from "@/features/chat/services";
import { videoService } from "@/services/api/video.service";

// ── Module-level constants (exported so components can import
//    directly without going through the hook return value) ──
export const CHAT_LABELS = [
  {
    value: "all",
    label: "All",
    color: "gray",
    bgColor: "bg-gray-100",
    textColor: "text-gray-700",
  },
  {
    value: "inquiry",
    label: "Inquiry",
    color: "blue",
    bgColor: "bg-blue-100",
    textColor: "text-blue-700",
  },
  {
    value: "booked",
    label: "Booked",
    color: "green",
    bgColor: "bg-green-100",
    textColor: "text-green-700",
  },
  {
    value: "active",
    label: "Active",
    color: "green",
    bgColor: "bg-[#39B54A]/10",
    textColor: "text-[#2d913c]",
  },
  {
    value: "completed",
    label: "Completed",
    color: "gray",
    bgColor: "bg-gray-100",
    textColor: "text-gray-700",
  },
] as const;

export const QUICK_REACTIONS = ["👍", "❤️", "😊", "👏", "🙏", "🎉"] as const;

export const CANNED_RESPONSES = [
  "Thank you for your inquiry! I'd be happy to help.",
  "I'm available during the times you mentioned.",
  "Could you please provide more details about your needs?",
  "I have experience with similar care requirements.",
  "Let me know if you have any questions!",
  "Looking forward to working with you.",
] as const;

// ── Hook ──────────────────────────────────────────────────────
export function useMessagesPage() {
  const router = useRouter();
  const searchParams = useSearchParams();
  const conversationIdParam = searchParams.get("conversation");

  const { user, isAuthenticated, isLoading: authLoading } = useAuthContext();
  const {
    socket,
    joinConversation,
    leaveConversation,
    sendMessage: socketSendMessage,
    startTyping,
    stopTyping,
    onlineUsers,
    typingUsers,
    onNewMessage,
    onMessagesRead,
    onMessageFailed,
    onChatStatusChange,
  } = useSocket();

  // ── Core chat state ─────────────────────────────────────────
  const [conversations, setConversations] = useState<Conversation[]>([]);
  const [selectedConversation, setSelectedConversation] =
    useState<Conversation | null>(null);
  const [messages, setMessages] = useState<Message[]>([]);
  const [newMessage, setNewMessage] = useState("");
  const [isLoadingConversations, setIsLoadingConversations] = useState(true);
  const [isLoadingMessages, setIsLoadingMessages] = useState(false);
  const [isSending, setIsSending] = useState(false);
  const [searchQuery, setSearchQuery] = useState("");
  const [showMobileChat, setShowMobileChat] = useState(false);
  const [showDropdown, setShowDropdown] = useState(false);

  // ── Feature states ─────────────────────────────────────────
  const [messageSearchQuery, setMessageSearchQuery] = useState("");
  const [labelFilter, setLabelFilter] = useState<string>("all");
  const [showCannedResponses, setShowCannedResponses] = useState(false);
  const [showReactionPicker, setShowReactionPicker] = useState<string | null>(
    null
  );
  const [uploadingImage, setUploadingImage] = useState(false);
  const [pinnedMessages, setPinnedMessages] = useState<Message[]>([]);
  const [showPinnedMessages, setShowPinnedMessages] = useState(false);
  const [showReportModal, setShowReportModal] = useState<string | null>(null);
  const [reportReason, setReportReason] = useState("");

  // ── Video / export states ──────────────────────────────────
  const [showVideoModal, setShowVideoModal] = useState(false);
  const [activeCallId, setActiveCallId] = useState<string | null>(null);
  const [callType, setCallType] = useState<"audio" | "video">("video");
  const [showExportModal, setShowExportModal] = useState(false);
  const [exportFormat, setExportFormat] = useState<"txt" | "json">("txt");
  const [isExporting, setIsExporting] = useState(false);

  // ── Chat access control ────────────────────────────────────
  const [chatAccessStatus, setChatAccessStatus] =
    useState<ChatAccessStatus | null>(null);
  const [isLoadingAccess, setIsLoadingAccess] = useState(false);
  const [optimisticMessages, setOptimisticMessages] = useState<
    OptimisticMessage[]
  >([]);

  // ── Message search state ───────────────────────────────────
  const [searchedMessages, setSearchedMessages] = useState<Message[] | null>(
    null
  );

  // ── Refs ───────────────────────────────────────────────────
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLTextAreaElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // ── Utility helpers ────────────────────────────────────────
  const formatMessageTime = useCallback((date: string): string => {
    const d = new Date(date);
    if (isToday(d)) return format(d, "h:mm a");
    if (isYesterday(d)) return `Yesterday ${format(d, "h:mm a")}`;
    return format(d, "MMM d, h:mm a");
  }, []);

  const formatConversationTime = useCallback((date: string): string => {
    const d = new Date(date);
    if (isToday(d)) return format(d, "h:mm a");
    if (isYesterday(d)) return "Yesterday";
    return format(d, "MMM d");
  }, []);

  const scrollToBottom = useCallback(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  }, []);

  const getOtherParticipant = useCallback(
    (conversation: Conversation) => {
      if (!user) return null;
      return (
        conversation.participants?.find((p) => p._id !== user._id) ?? null
      );
    },
    [user]
  );

  // ── API loaders ────────────────────────────────────────────
  const loadConversations = useCallback(async () => {
    try {
      setIsLoadingConversations(true);
      const response = await chatService.getConversations();
      if (response.success && response.data) {
        setConversations(response.data.conversations || []);
      }
    } catch (error) {
      const msg =
        error && typeof error === "object" && "message" in error
          ? (error as { message: string }).message
          : String(error);
      console.error("Failed to load conversations:", msg);
    } finally {
      setIsLoadingConversations(false);
    }
  }, []);

  const loadMessages = useCallback(async (conversationId: string) => {
    try {
      setIsLoadingMessages(true);
      const response = await chatService.getMessages(conversationId, {
        page: 1,
        limit: 50,
      });
      if (response.success && response.data) {
        setMessages(response.data.messages?.reverse() || []);
      }
    } catch (error) {
      console.error("Failed to load messages:", error);
    } finally {
      setIsLoadingMessages(false);
    }
  }, []);

  const loadChatAccessStatus = useCallback(async (conversationId: string) => {
    try {
      setIsLoadingAccess(true);
