  const handleImageUpload = useCallback(
    async (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (!file || !selectedConversation) return;

      const allowedTypes = [
        "image/jpeg",
        "image/png",
        "image/gif",
        "image/webp",
      ];
      if (!allowedTypes.includes(file.type)) {
        alert("Please upload a valid image file (JPEG, PNG, GIF, WebP)");
        return;
      }

      if (file.size > 5 * 1024 * 1024) {
        alert("Image size should be less than 5MB");
        return;
      }

      setUploadingImage(true);
      try {
        const uploadResult = await chatService.uploadAttachment(file);

        if (uploadResult?.data?.url || uploadResult?.url) {
          const fileUrl = uploadResult?.data?.url || uploadResult?.url;
          const tempId = `temp_${Date.now()}_${Math.random()
            .toString(36)
            .slice(2, 11)}`;
          const attachment: {
            type: "image";
            url: string;
            name: string;
            size: number;
            mimeType: string;
          } = {
            type: "image",
            url: String(fileUrl),
            name: file.name,
            size: file.size,
            mimeType: file.type,
          };

          const optimisticImage: OptimisticMessage = {
            _id: tempId,
            tempId,
            conversationId: selectedConversation._id,
            senderId: {
              _id: user?._id || "",
              fullName: user?.fullName || "You",
              ...(user?.avatar ? { avatar: user.avatar } : {}),
            },
            content: file.name,
            messageType: "image",
            attachments: [attachment],
            status: "sending",
            createdAt: new Date().toISOString(),
            updatedAt: new Date().toISOString(),
          };

          setOptimisticMessages((prev) => [...prev, optimisticImage]);
          scrollToBottom();
          socketSendMessage(
            selectedConversation._id,
            file.name,
            "image",
            [attachment],
            tempId
          );
        }
      } catch (error) {
        console.error("Failed to upload image:", error);
        alert("Failed to upload image. Please try again.");
      } finally {
        setUploadingImage(false);
        if (fileInputRef.current) {
          fileInputRef.current.value = "";
        }
      }
    },
    [selectedConversation, user, socketSendMessage, scrollToBottom]
  );

  const handleInsertCannedResponse = useCallback((text: string) => {
    setNewMessage((prev) => (prev ? `${prev}\n${text}` : text));
