        }
      } catch (error: unknown) {
        console.error("Failed to start call:", error);
        const msg =
          error instanceof Error
            ? error.message
            : (error as { message?: string } | null)?.message;
        alert(
          msg ||
            `Failed to start ${type} call. Video calling may not be configured.`
        );
      }
    },
    [selectedConversation, chatAccessStatus]
  );

  const handleEndCall = useCallback(() => {
    setShowVideoModal(false);
    setActiveCallId(null);
  }, []);

  // ── Socket effects ─────────────────────────────────────────
  useEffect(() => {
    if (!socket) return;

    const markTempMessageFailed = (tempId?: string) => {
      if (!tempId) return;
      setOptimisticMessages((prev) =>
        prev.map((m) =>
          m.tempId === tempId ? { ...m, status: "failed" as const } : m
        )
      );
    };

    const upsertServerMessage = (
      serverMessage: Message,
      tempId?: string
    ) => {
      if (tempId) {
        setOptimisticMessages((prev) =>
          prev.filter((m) => m.tempId !== tempId)
        );
      }
      setMessages((prev) => {
        if (prev.some((m) => m._id === serverMessage._id)) return prev;
        return [...prev, serverMessage];
      });
      scrollToBottom();
    };

    const handleNewMessage = (payload: unknown) => {
      const typedPayload = payload as
        | Message
        | { message: Message; tempId?: string };
      const message =
        (typedPayload as { message?: Message }).message ||
        (typedPayload as Message);
      const tempId = (typedPayload as { tempId?: string }).tempId;

      if (
        selectedConversation &&
        message.conversationId === selectedConversation._id
      ) {
        upsertServerMessage(message, tempId);
      }

      setConversations((prev) =>
        prev
          .map((c) => {
            if (c._id === message.conversationId) {
              const isOwnMessage = message.senderId?._id === user?._id;
              return {
                ...c,
                lastMessage: {
                  content: message.content,
                  senderId: message.senderId._id,
                  messageType: message.messageType,
                  createdAt: message.createdAt,
                },
                unreadCount:
                  selectedConversation?._id !== message.conversationId &&
                  !isOwnMessage
                    ? {
                        ...c.unreadCount,
                        [user?._id || ""]:
                          (c.unreadCount?.[user?._id || ""] || 0) + 1,
                      }
                    : c.unreadCount,
                updatedAt: message.createdAt,
              };
            }
            return c;
          })
          .sort(
            (a, b) =>
              new Date(b.updatedAt).getTime() -
              new Date(a.updatedAt).getTime()
          )
      );
    };

    const handleMessagesRead = (payload: unknown) => {
      const data = payload as {
        conversationId: string;
        userId: string;
        readAt?: string;
      };
      if (
        !selectedConversation ||
        data.conversationId !== selectedConversation._id
      )
        return;

      setMessages((prev) =>
        prev.map((msg) => {
          const isOwnOutgoing = msg.senderId?._id === user?._id;
          if (!isOwnOutgoing || msg.messageType === "system") return msg;
          return {
            ...msg,
            status: "read",
            readAt: data.readAt || new Date().toISOString(),
          };
        })
      );
    };

    const handleMessageDelivered = (payload: unknown) => {
      const data = payload as { conversationId: string; userId: string };
      if (
        !selectedConversation ||
        data.conversationId !== selectedConversation._id
      )
        return;

      setMessages((prev) =>
        prev.map((msg) => {
          const isOwnOutgoing = msg.senderId?._id === user?._id;
          if (!isOwnOutgoing || msg.messageType === "system") return msg;
          if (msg.status === "read") return msg;
          return {
            ...msg,
            status: "delivered",
            deliveredAt: new Date().toISOString(),
          };
        })
      );
    };

    const handleMessageFailedSocket = (payload: unknown) => {
      const data = payload as { tempId?: string };
      markTempMessageFailed(data.tempId);
    };

    const handleChatStatusChangeSocket = (payload: unknown) => {
      const data = payload as { conversationId: string };
      if (
        selectedConversation &&
        data.conversationId === selectedConversation._id
      ) {
        loadChatAccessStatus(selectedConversation._id);
      }
      loadConversations();
    };

    const handleReactionUpdate = (data: {
      messageId: string;
      reactions: Message["reactions"];
    }) => {
      setMessages((prev) =>
        prev.map((msg) => {
          if (msg._id !== data.messageId) return msg;
          if (data.reactions) return { ...msg, reactions: data.reactions };
          const { reactions, ...rest } = msg;
          return rest;
        })
      );
    };

    const handlePinUpdate = (data: {
      messageId: string;
      pinned: Message["pinned"];
    }) => {
      setMessages((prev) =>
        prev.map((msg) => {
          if (msg._id !== data.messageId) return msg;
          if (data.pinned) return { ...msg, pinned: data.pinned };
          const { pinned, ...rest } = msg;
          return rest;
        })
      );
    };

    const offNewMessage = onNewMessage(handleNewMessage);
    const offMessagesRead = onMessagesRead(handleMessagesRead);
    const offMessageFailed = onMessageFailed(handleMessageFailedSocket);
    const offChatStatusChange = onChatStatusChange(
      handleChatStatusChangeSocket
    );

    socket.on("message_delivered", handleMessageDelivered);
    socket.on("reaction_updated", handleReactionUpdate);
    socket.on("message_pinned", handlePinUpdate);

    return () => {
      offNewMessage();
      offMessagesRead();
      offMessageFailed();
      offChatStatusChange();
      socket.off("message_delivered", handleMessageDelivered);
      socket.off("reaction_updated", handleReactionUpdate);
      socket.off("message_pinned", handlePinUpdate);
    };
  }, [
    socket,
    selectedConversation,
    user?._id,
    scrollToBottom,
    loadChatAccessStatus,
    loadConversations,
    onNewMessage,
    onMessagesRead,
    onMessageFailed,
    onChatStatusChange,
  ]);

  // Load conversations on mount / after auth resolves
  useEffect(() => {
    if (isAuthenticated && !authLoading) {
      loadConversations();
    }
  }, [isAuthenticated, authLoading, loadConversations]);

  // Auto-select conversation from URL param
  useEffect(() => {
    if (
      !conversationIdParam ||
      selectedConversation ||
      isLoadingConversations
    )
      return;

    const selectConversationFromParam = async () => {
      const existing = conversations.find(
        (c) => c._id === conversationIdParam
      );
      if (existing) {
        handleSelectConversation(existing);
        return;
      }

      if (conversations.length > 0) {
        try {
          const response = await chatService.getConversationById(
            conversationIdParam
          );
          if (response.success && response.data?.conversation) {
            const newConv = response.data.conversation;
            setConversations((prev) => {
              const exists = prev.some((c) => c._id === newConv._id);
              if (exists) return prev;
              return [newConv, ...prev];
            });
            handleSelectConversation(newConv);
          }
        } catch (error) {
          console.error("Failed to fetch conversation:", error);
        }
      }
    };

    selectConversationFromParam();
  }, [
    conversationIdParam,
    conversations,
    selectedConversation,
    isLoadingConversations,
    handleSelectConversation,
  ]);

  // Scroll to bottom whenever messages update
  useEffect(() => {
    scrollToBottom();
  }, [messages, scrollToBottom]);

  // Debounced message search via backend
  useEffect(() => {
    if (!messageSearchQuery.trim() || !selectedConversation) {
      setSearchedMessages(null);
      return;
    }
    const timer = setTimeout(async () => {
      try {
        const response = await chatService.searchMessages(
          selectedConversation._id,
          messageSearchQuery.trim()
        );
        if (response.success) {
          setSearchedMessages(response.data?.messages || []);
        }
      } catch {
        setSearchedMessages(null);
      }
    }, 300);
    return () => clearTimeout(timer);
  }, [messageSearchQuery, selectedConversation]);

  // ── Derived values ─────────────────────────────────────────
  const filteredConversations = conversations.filter((conv) => {
    if (searchQuery) {
      const other = getOtherParticipant(conv);
      if (
        !other?.fullName
          ?.toLowerCase()
          .includes(searchQuery.toLowerCase())
      )
        return false;
    }
    if (labelFilter !== "all") {
      if ((conv as Conversation & { label?: string }).label !== labelFilter)
        return false;
    }
    return true;
  });

  const baseMessages =
    searchedMessages !== null ? searchedMessages : messages;
  const filteredMessages = [
    ...baseMessages,
    ...optimisticMessages,
  ] as (Message | OptimisticMessage)[];

  const typingInConversation = selectedConversation
    ? (typingUsers?.filter(
        (t) =>
          t.conversationId === selectedConversation._id &&
          t.userId !== user?._id
      ) ?? [])
    : [];

  const otherParticipant = selectedConversation
    ? getOtherParticipant(selectedConversation)
    : null;

  const isOtherOnline = otherParticipant
    ? (onlineUsers?.has(otherParticipant._id) ?? false)
    : false;

  // ── Return everything the UI needs ────────────────────────
  return {
    // ── Auth (kept here so MessagesPageClient can use for guards) ──
    user,
    isAuthenticated,
    authLoading,

    // ── State values ──────────────────────────────────────────
    conversations,
    selectedConversation,
    messages,
    newMessage,
    isLoadingConversations,
    isLoadingMessages,
    isSending,
    searchQuery,
    showMobileChat,
    showDropdown,
    messageSearchQuery,
    labelFilter,
    showCannedResponses,
    showReactionPicker,
    uploadingImage,
    pinnedMessages,
    showPinnedMessages,
    showReportModal,
    reportReason,
    showVideoModal,
    activeCallId,
    callType,
    showExportModal,
    exportFormat,
    isExporting,
    chatAccessStatus,
    isLoadingAccess,
    optimisticMessages,

    // ── Setters exposed for UI-only changes ───────────────────
    setSearchQuery,
    setLabelFilter,
    setShowDropdown,
    setMessageSearchQuery,
    setShowCannedResponses,
    setShowReactionPicker,
    setShowPinnedMessages,
    setShowReportModal,
    setReportReason,
    setShowExportModal,
    setExportFormat,

    // ── Refs ──────────────────────────────────────────────────
    messagesEndRef,
    inputRef,
    fileInputRef,

    // ── Constants ─────────────────────────────────────────────
    CHAT_LABELS,
    QUICK_REACTIONS,
    CANNED_RESPONSES,

    // ── Handlers ─────────────────────────────────────────────
    handleSelectConversation,
    handleSendMessage,
    handleRetryMessage,
    handleRemoveFailedMessage,
    handlePayNow,
    handleContactSupport,
    handleViewBooking,
    handleKeyPress,
    handleBackToList,
    handleMessageChange,
    handleImageUpload,
    handleInsertCannedResponse,
    handleAddReaction,
    handleRemoveReaction,
    handleTogglePinMessage,
    handleBlockUser,
    handleUnblockUser,
    handleToggleMute,
    handleArchiveConversation,
    handleUnarchiveConversation,
    handleReportMessage,
    handleExportChat,
    executeExport,
    handleStartCall,
    handleEndCall,

    // ── Derived values ────────────────────────────────────────
    filteredConversations,
    filteredMessages,
    typingInConversation,
    otherParticipant,
    isOtherOnline,

    // ── Socket state (needed in sub-components) ───────────────
    onlineUsers,
    getOtherParticipant,

    // ── Utilities ─────────────────────────────────────────────
    formatMessageTime,
    formatConversationTime,
  } as const;
}

"use client";

import { useEffect, useState, useCallback } from "react";
import Link from "next/link";
import { useRouter } from "next/navigation";
import { motion } from "framer-motion";
import {
  User,
  Briefcase,
  CalendarDays,
  ClipboardList,
  AlertTriangle,
  ChevronDown,
  CheckCircle2,
  AlertCircle,
  X,
  Shield,
  Banknote,
  Eye,
} from "lucide-react";
import { userService } from "@/features/user/services";
import { authService } from "@/features/auth/services";
import { CaregiverLayout } from "@/app/dashboard/caregiver/components";
import AvatarUpload from "@/components/ui/AvatarUpload";
import {
  SKILL_OPTIONS,
  SERVICE_TYPE_OPTIONS,
  LANGUAGE_OPTIONS,
  WORK_PREFERENCES,
} from "@/lib/constants";
import { useAuthContext } from "@/context/AuthContext";
import { extractStatusCode } from "@/types/errors.types";

const WORK_PREFERENCE_OPTIONS = Object.entries(WORK_PREFERENCES).map(
  ([, value]) => ({ value, label: value.replace(/_/g, ' ').replace(/\b\w/g, l => l.toUpperCase()) })
);

interface Certification {
  name: string;
  issuer: string;
  issueDate: string;
  expiryDate?: string;
  verified: boolean;
}

interface EmergencyContact {
  name: string;
  relationship: string;
  phone: string;
  email?: string;
}

interface PreviousEmployer {
  name: string;
  duration: string;
  duties: string;
  reference?: string;
  contactPhone?: string;
}

interface UserProfile {
  _id: string;
  fullName: string;
  email: string;
  phone?: string;
  age?: number;
  gender?: string;
  avatar?: string;
  role: string;
  status: string;
  location?: {
    city?: string;
    state?: string;
    country?: string;
    address?: string;
    postalCode?: string;
  };
  bio?: string;
  experience?: number;
  hourlyRate?: number;
  dailyRate?: number;
  weeklyRate?: number;
  monthlyRate?: number;
  skills?: string[];
  certifications?: Certification[];
  serviceTypes?: string[];
  workPreferences?: string[];
  serviceRadius?: number;
  previousEmployers?: PreviousEmployer[];
  emergencyContact?: EmergencyContact;
  availability?: {
    days?: string[];
    hours?: { start?: string; end?: string };
  };
  languages?: string[];
  rating?: number;
  totalReviews?: number;
  completionPercentage?: number;
  backgroundCheck?: {
    status: string;
  };
  createdAt?: string;
  isEmailVerified?: boolean;
  isProfileComplete?: boolean;
}

// SERVICE_TYPES, SKILL_OPTIONS, LANGUAGE_OPTIONS, WORK_PREFERENCES
// imported from @/lib/constants (single source of truth)
const SERVICE_TYPES = SERVICE_TYPE_OPTIONS;

// Days of the week
const DAYS_OF_WEEK = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"];

function toDisplayDayLabel(day: string): string {
  const normalized = day.trim().toLowerCase();
  return normalized.charAt(0).toUpperCase() + normalized.slice(1);
}

function toApiDayValue(day: string): string {
  return day.trim().toLowerCase();
}

type ActiveSection = "personal" | "professional" | "pricing" | "availability" | "experience" | "emergency" | null;

export default function CaregiverProfilePage() {
  const router = useRouter();
  const { user: authUser, isLoading: isAuthLoading } = useAuthContext();
  const [profile, setProfile] = useState<UserProfile | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [activeSection, setActiveSection] = useState<ActiveSection>(null);
  const [isSaving, setIsSaving] = useState(false);
  const [error, setError] = useState("");
  const [successMessage, setSuccessMessage] = useState("");

  // Form state
  const [formData, setFormData] = useState({
    // Personal
    fullName: "",
    phone: "",
    age: "",
    gender: "",
    bio: "",
    city: "",
    state: "",
    country: "",
    address: "",
    postalCode: "",
    languages: [] as string[],
    // Professional
    experience: "",
    hourlyRate: "",
    dailyRate: "",
    weeklyRate: "",
    monthlyRate: "",
    skills: [] as string[],
    serviceTypes: [] as string[],
    workPreferences: [] as string[],
    serviceRadius: 25,
    certifications: [] as Certification[],
    // Availability
    availableDays: [] as string[],
    availableHoursStart: "",
    availableHoursEnd: "",
    // Experience
    previousEmployers: [] as PreviousEmployer[],
    // Emergency
    emergencyContact: {
      name: "",
      relationship: "",
      phone: "",
      email: "",
    },
  });

  // New certification form
  const [newCertification, setNewCertification] = useState<Certification>({
    name: "",
    issuer: "",
    issueDate: "",
    expiryDate: "",
    verified: false,
  });

  // New employer form
  const [newEmployer, setNewEmployer] = useState<PreviousEmployer>({
    name: "",
    duration: "",
    duties: "",
    reference: "",
    contactPhone: "",
  });

  const fetchProfile = useCallback(async () => {
    try {
      setIsLoading(true);

      const response = await userService.getProfile();

      if (!response.success || !response.data) {
        throw new Error("Failed to fetch profile");
      }

      const user = response.data.user;

      // Check if user is a caregiver
      if (user.role !== "caregiver") {
        router.push(`/profile/${user.role}`);
        return;
      }

      setProfile(user as unknown as UserProfile);
      initializeFormData(user as unknown as UserProfile);
    } catch (err) {
      console.error("Error fetching profile:", err);
      const statusCode = extractStatusCode(err);
      if (statusCode === 401) {
        router.replace("/login?redirect=/profile/caregiver");
        return;
      }

      if (statusCode === 403) {
        if (authUser?.role === "caregiver") {
          router.replace("/dashboard/pending");
          return;
        }

        setError("You do not have permission to access this profile.");
        return;
      }

      setError("Failed to load profile. Please refresh and try again.");
    } finally {
      setIsLoading(false);
    }
  }, [router, authUser?.role]);

  useEffect(() => {
    if (isAuthLoading) {
      return;
    }

    if (!authUser) {
      router.replace("/login?redirect=/profile/caregiver");
      return;
    }

    if (authUser.role && authUser.role !== "caregiver") {
      router.replace(`/profile/${authUser.role}`);
      return;
    }

    void fetchProfile();
  }, [isAuthLoading, authUser?._id, authUser?.role, router, fetchProfile]);

  const initializeFormData = (user: UserProfile) => {
    setFormData({
      fullName: user.fullName || "",
      phone: user.phone || "",
      age: user.age?.toString() || "",
      gender: user.gender || "",
      bio: user.bio || "",
      city: user.location?.city || "",
      state: user.location?.state || "",
      country: user.location?.country || "",
      address: user.location?.address || "",
      postalCode: user.location?.postalCode || "",
      languages: user.languages || [],
      experience: user.experience?.toString() || "",
      hourlyRate: user.hourlyRate?.toString() || "",
      dailyRate: user.dailyRate?.toString() || "",
      weeklyRate: user.weeklyRate?.toString() || "",
      monthlyRate: user.monthlyRate?.toString() || "",
      skills: user.skills || [],
      serviceTypes: user.serviceTypes || [],
      workPreferences: user.workPreferences || [],
      serviceRadius: user.serviceRadius || 25,
      certifications: user.certifications || [],
      availableDays: (user.availability?.days || []).map(toDisplayDayLabel),
      availableHoursStart: user.availability?.hours?.start || "",
      availableHoursEnd: user.availability?.hours?.end || "",
      previousEmployers: user.previousEmployers || [],
      emergencyContact: {
        name: user.emergencyContact?.name || "",
        relationship: user.emergencyContact?.relationship || "",
        phone: user.emergencyContact?.phone || "",
        email: user.emergencyContact?.email || "",
      },
    });
  };

  const handleSave = async () => {
    try {
      setIsSaving(true);
      setError("");

      const updateData: Record<string, unknown> = {
        fullName: formData.fullName || undefined,
        phone: formData.phone || undefined,
        age: formData.age ? parseInt(formData.age) : undefined,
        gender: formData.gender || undefined,
        bio: formData.bio || undefined,
        languages: formData.languages,
        experience: formData.experience ? parseInt(formData.experience) : undefined,
        hourlyRate: formData.hourlyRate ? parseFloat(formData.hourlyRate) : undefined,
        dailyRate: formData.dailyRate ? parseFloat(formData.dailyRate) : undefined,
        weeklyRate: formData.weeklyRate ? parseFloat(formData.weeklyRate) : undefined,
        monthlyRate: formData.monthlyRate ? parseFloat(formData.monthlyRate) : undefined,
        skills: formData.skills,
        serviceTypes: formData.serviceTypes,
        workPreferences: formData.workPreferences,
        serviceRadius: formData.serviceRadius,
        certifications: formData.certifications,
        previousEmployers: formData.previousEmployers,
        location: {
          city: formData.city || undefined,
          state: formData.state || undefined,
          country: formData.country || undefined,
          address: formData.address || undefined,
          zipCode: formData.postalCode || undefined,
          postalCode: formData.postalCode || undefined,
        },
        availability: {
          days: formData.availableDays.map(toApiDayValue),
          hours: {
            start: formData.availableHoursStart || undefined,
            end: formData.availableHoursEnd || undefined,
          },
        },
        emergencyContact: (
          formData.emergencyContact.name ||
          formData.emergencyContact.phone
        ) ? formData.emergencyContact : undefined,
      };

      // Remove keys with undefined values to keep the payload clean
      Object.keys(updateData).forEach((key) => {
        if (updateData[key] === undefined) delete updateData[key];
      });

      const response = await userService.updateProfile(updateData as Parameters<typeof userService.updateProfile>[0]);

      if (!response.success || !response.data) {
        throw new Error("Failed to update profile");
      }

      setProfile(response.data.user as unknown as UserProfile);
      initializeFormData(response.data.user as unknown as UserProfile);
      setActiveSection(null);
      setSuccessMessage("Profile updated successfully!");
      setTimeout(() => setSuccessMessage(""), 3000);
    } catch (err: unknown) {
      // Handle different error types properly
      let msg = "Failed to update profile";

      if (err instanceof Error) {
        console.error("Error updating profile:", err.message);
        msg = err.message || msg;
      } else if (typeof err === 'object' && err !== null) {
        const apiError = err as { 
          message?: string; 
          statusCode?: number;
          errors?: { msg?: string; message?: string }[];
          response?: { data?: { message?: string; errors?: { msg: string }[] } };
        };
        console.error("Error updating profile:", JSON.stringify(apiError, null, 2));
        msg =
          apiError?.errors?.[0]?.msg ||
          apiError?.errors?.[0]?.message ||
          apiError?.message ||
          apiError?.response?.data?.errors?.[0]?.msg ||
          apiError?.response?.data?.message ||
          msg;
      } else {
        console.error("Error updating profile:", err);
      }

      setError(msg);
    } finally {
      setIsSaving(false);
    }
  };

  const toggleArrayItem = (array: string[], item: string, setter: (val: string[]) => void) => {
    if (array.includes(item)) {
      setter(array.filter((i) => i !== item));
    } else {
      setter([...array, item]);
    }
  };

  const addCertification = () => {
    if (newCertification.name && newCertification.issuer) {
      setFormData((prev) => ({
        ...prev,
        certifications: [...prev.certifications, newCertification],
      }));
      setNewCertification({ name: "", issuer: "", issueDate: "", expiryDate: "", verified: false });
    }
  };

  const removeCertification = (index: number) => {
    setFormData((prev) => ({
      ...prev,
      certifications: prev.certifications.filter((_, i) => i !== index),
    }));
  };

  const addEmployer = () => {
    if (newEmployer.name && newEmployer.duration) {
      setFormData((prev) => ({
        ...prev,
        previousEmployers: [...prev.previousEmployers, newEmployer],
      }));
      setNewEmployer({ name: "", duration: "", duties: "", reference: "", contactPhone: "" });
    }
  };

  const removeEmployer = (index: number) => {
    setFormData((prev) => ({
      ...prev,
      previousEmployers: prev.previousEmployers.filter((_, i) => i !== index),
    }));
  };

  if (isLoading) {
    return (
      <CaregiverLayout pageTitle="Profile">
        <div className="flex items-center justify-center py-24">
          <div className="text-center">
            <div className="relative w-14 h-14 mx-auto mb-4">
              <div className="absolute inset-0 rounded-full border-[3px] border-gray-200" />
              <div className="absolute inset-0 rounded-full border-[3px] border-[#39B54A] border-t-transparent animate-spin" />
            </div>
            <p className="text-sm text-gray-500 font-medium">Loading profile...</p>
          </div>
        </div>
      </CaregiverLayout>
    );
  }

  return (
    <CaregiverLayout pageTitle="Profile">
      <div className="space-y-6 max-w-5xl">
        {/* Success/Error Messages */}
        {successMessage && (
          <motion.div
            initial={{ opacity: 0, y: -8 }}
            animate={{ opacity: 1, y: 0 }}
            className="flex items-center gap-3 p-4 bg-[#39B54A]/10 border border-[#39B54A]/20 rounded-xl text-[#39B54A]"
          >
            <CheckCircle2 size={18} />
            <span className="text-sm font-medium">{successMessage}</span>
          </motion.div>
        )}
        {error && (
          <motion.div
            initial={{ opacity: 0, y: -8 }}
            animate={{ opacity: 1, y: 0 }}
            className="flex items-center gap-3 p-4 bg-red-50 border border-red-200 rounded-xl text-red-600"
          >
            <AlertCircle size={18} />
            <span className="text-sm font-medium">{error}</span>
          </motion.div>
        )}

        {/* Profile Header Card */}
        <div className="bg-white rounded-xl border border-gray-100/80 overflow-hidden">
          {/* Cover Image */}
          <div className="h-32 bg-linear-to-r from-[#39B54A] to-[#81BC89]"></div>

          <div className="px-6 pb-6">
            {/* Avatar and Actions */}
            <div className="flex flex-col lg:flex-row lg:items-start lg:justify-between -mt-12 mb-4 gap-4">
              {/* Left: Avatar + Name */}
              <div className="flex flex-col sm:flex-row items-center sm:items-start gap-4">
                {/* Avatar Upload Section */}
                <div className="flex-shrink-0">
                  <AvatarUpload
                    {...(profile?.avatar !== undefined ? { avatar: profile.avatar } : {})}
                    {...(profile?.fullName !== undefined ? { fullName: profile.fullName } : {})}
                    accentColor="#39B54A"
                    size={100}
                    onAvatarChange={(newUrl) => {
                      setProfile((prev) => prev ? { ...prev, avatar: newUrl } : prev);
                      const stored = authService.getCurrentUser();
                      if (stored) {
                        authService.updateStoredUser({ ...stored, avatar: newUrl });
                        window.dispatchEvent(new Event("userUpdated"));
                      }
                    }}
                  />
                </div>
                {/* Name & Role */}
                <div className="text-center sm:text-left pt-2 sm:pt-16">
                  <div className="flex items-center justify-center sm:justify-start gap-2">
                    <h1 className="text-2xl font-bold text-gray-900">{profile?.fullName}</h1>
                    {profile?.isEmailVerified && (
                      <Shield size={18} className="text-[#39B54A]" />
                    )}
                  </div>
                  <p className="text-gray-500">Caregiver</p>
                </div>
              </div>
              {/* Right: Action Buttons */}
              <div className="flex justify-center sm:justify-start lg:justify-end gap-2 pt-0 lg:pt-16">
                <Link
                  href="/dashboard/caregiver"
                  className="px-4 py-2.5 border border-gray-300 text-gray-700 font-medium rounded-xl hover:bg-[#39B54A]/5 transition-colors"
                >
                  Dashboard
                </Link>
                <Link
                  href={`/caregiver/${profile?._id}`}
                  className="px-4 py-2.5 bg-white hover:bg-[#39B54A] text-[#39B54A] hover:text-white font-medium rounded-xl border border-[#39B54A]/40 hover:border-[#39B54A] transition-all shadow-sm"
                >
                  View Public Profile
                </Link>
              </div>
            </div>

            {/* Profile Completion */}
            <div className="bg-[#39B54A]/5 rounded-xl p-4 mt-4">
              <div className="flex items-center justify-between mb-2">
                <span className="text-sm font-medium text-gray-700">Profile Completion</span>
                <span className="text-sm font-bold text-[#39B54A]">{profile?.completionPercentage || 0}%</span>
              </div>
              <div className="w-full h-2 bg-[#39B54A]/5 rounded-full overflow-hidden">
                <div
                  className="h-full bg-[#39B54A] rounded-full transition-all duration-500"
                  style={{ width: `${profile?.completionPercentage || 0}%` }}
                ></div>
              </div>
            </div>

            {/* Quick Stats */}
            <div className="grid grid-cols-2 sm:grid-cols-4 gap-4 mt-6">
              <div className="text-center p-4 bg-[#39B54A]/5 rounded-xl">
                <p className="text-2xl font-bold text-[#39B54A]">Rs. {(profile?.hourlyRate || 0).toLocaleString("en-NP")}</p>
                <p className="text-sm text-gray-500">Per Hour</p>
              </div>
              <div className="text-center p-4 bg-[#39B54A]/5 rounded-xl">
                <p className="text-2xl font-bold text-[#39B54A]">{profile?.experience || 0}</p>
                <p className="text-sm text-gray-500">Years Exp.</p>
              </div>
              <div className="text-center p-4 bg-[#39B54A]/5 rounded-xl">
                <p className="text-2xl font-bold text-[#39B54A]">{profile?.rating?.toFixed(1) || "N/A"}</p>
                <p className="text-sm text-gray-500">Rating</p>
              </div>
              <div className="text-center p-4 bg-[#39B54A]/5 rounded-xl">
                <p className="text-2xl font-bold text-[#39B54A]">{profile?.totalReviews || 0}</p>
                <p className="text-sm text-gray-500">Reviews</p>
              </div>
            </div>
          </div>
        </div>

        {/* Profile Sections */}
