                              ? "bg-[#39B54A] text-white"
                              : "bg-gray-100 text-gray-600 hover:bg-gray-100"
                          }`}
                        >
                          {day}
                        </button>
                      ))}
                    </div>
                  </div>

                  <div className="grid md:grid-cols-2 gap-4">
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">Start Time</label>
                      <input
                        type="time"
                        value={formData.availableHoursStart}
                        onChange={(e) => setFormData({ ...formData, availableHoursStart: e.target.value })}
                        className="w-full px-4 py-2.5 border border-gray-200 rounded-xl focus:ring-2 focus:ring-[#39B54A]/20 focus:border-[#39B54A] outline-none"
                      />
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">End Time</label>
                      <input
                        type="time"
                        value={formData.availableHoursEnd}
                        onChange={(e) => setFormData({ ...formData, availableHoursEnd: e.target.value })}
                        className="w-full px-4 py-2.5 border border-gray-200 rounded-xl focus:ring-2 focus:ring-[#39B54A]/20 focus:border-[#39B54A] outline-none"
                      />
                    </div>
                  </div>

                  <div className="p-4 bg-[#39B54A]/5 rounded-xl border border-[#39B54A]/10">
                    <p className="text-sm text-gray-700 flex items-center gap-2">
                      <CalendarDays size={14} className="text-[#39B54A]" />
                      For advanced calendar management, visit your{" "}
                      <Link href="/dashboard/caregiver/availability" className="underline font-medium text-[#39B54A]">
                        Availability Dashboard
                      </Link>
                    </p>
                  </div>
                </div>

                <div className="mt-6 flex justify-end gap-3">
                  <button
                    onClick={() => { setActiveSection(null); initializeFormData(profile!); }}
                    className="px-4 py-2 border border-gray-300 text-gray-700 rounded-xl hover:bg-[#39B54A]/5"
                  >
                    Cancel
                  </button>
                  <button
                    onClick={handleSave}
                    disabled={isSaving}
                    className="px-6 py-2 bg-[#39B54A] text-white rounded-xl hover:bg-[#2d913c] disabled:opacity-50"
                  >
                    {isSaving ? "Saving..." : "Save Changes"}
                  </button>
                </div>
              </div>
            )}
          </div>

          {/* Work Experience Section */}
          <div className="bg-white rounded-xl border border-gray-100/80 overflow-hidden">
            <button
              onClick={() => setActiveSection(activeSection === "experience" ? null : "experience")}
              className="w-full flex items-center justify-between p-6 hover:bg-[#39B54A]/5 transition-colors"
            >
              <div className="flex items-center gap-3">
                <div className="w-10 h-10 bg-amber-50 rounded-xl flex items-center justify-center ring-1 ring-amber-100">
                  <ClipboardList size={18} className="text-amber-600" />
                </div>
                <div className="text-left">
                  <h2 className="text-base font-semibold text-gray-900">Work Experience</h2>
                  <p className="text-sm text-gray-500">Previous employers and references</p>
                </div>
              </div>
              <ChevronDown size={18} className={`text-gray-400 transition-transform ${activeSection === "experience" ? "rotate-180" : ""}`} />
            </button>

            {activeSection === "experience" && (
              <div className="px-6 pb-6 border-t border-gray-100 pt-6">
                {formData.previousEmployers.length > 0 && (
                  <div className="space-y-3 mb-6">
                    {formData.previousEmployers.map((emp, idx) => (
                      <div key={idx} className="p-4 bg-[#39B54A]/5 rounded-xl">
                        <div className="flex items-start justify-between">
                          <div>
                            <p className="font-medium text-gray-900">{emp.name}</p>
                            <p className="text-sm text-gray-500">{emp.duration}</p>
                            <p className="text-sm text-gray-600 mt-1">{emp.duties}</p>
                          </div>
                          <button
                            onClick={() => removeEmployer(idx)}
                            className="p-1 text-red-400 hover:text-red-600 hover:bg-red-50 rounded-lg transition-colors"
                          >
                            <X size={16} />
                          </button>
                        </div>
                      </div>
                    ))}
                  </div>
                )}

                <div className="space-y-3 p-4 border-2 border-dashed border-gray-200 rounded-xl">
                  <h4 className="font-medium text-gray-700">Add Previous Employer</h4>
                  <div className="grid md:grid-cols-2 gap-3">
                    <input
                      type="text"
                      placeholder="Employer Name"
                      value={newEmployer.name}
                      onChange={(e) => setNewEmployer({ ...newEmployer, name: e.target.value })}
                      className="px-4 py-2.5 border border-gray-200 rounded-xl focus:ring-2 focus:ring-[#39B54A]/20 focus:border-[#39B54A] outline-none"
                    />
                    <input
                      type="text"
                      placeholder="Duration (e.g., Jan 2020 - Dec 2022)"
                      value={newEmployer.duration}
                      onChange={(e) => setNewEmployer({ ...newEmployer, duration: e.target.value })}
                      className="px-4 py-2.5 border border-gray-200 rounded-xl focus:ring-2 focus:ring-[#39B54A]/20 focus:border-[#39B54A] outline-none"
                    />
                  </div>
                  <textarea
                    placeholder="Duties and responsibilities"
                    value={newEmployer.duties}
                    onChange={(e) => setNewEmployer({ ...newEmployer, duties: e.target.value })}
                    rows={2}
                    className="w-full px-4 py-2.5 border border-gray-200 rounded-xl focus:ring-2 focus:ring-[#39B54A]/20 focus:border-[#39B54A] outline-none resize-none"
                  />
                  <div className="grid md:grid-cols-2 gap-3">
                    <input
                      type="text"
                      placeholder="Reference Name (Optional)"
                      value={newEmployer.reference}
                      onChange={(e) => setNewEmployer({ ...newEmployer, reference: e.target.value })}
                      className="px-4 py-2.5 border border-gray-200 rounded-xl focus:ring-2 focus:ring-[#39B54A]/20 focus:border-[#39B54A] outline-none"
                    />
                    <input
                      type="tel"
                      placeholder="Reference Phone (Optional)"
                      value={newEmployer.contactPhone}
                      onChange={(e) => setNewEmployer({ ...newEmployer, contactPhone: e.target.value })}
                      className="px-4 py-2.5 border border-gray-200 rounded-xl focus:ring-2 focus:ring-[#39B54A]/20 focus:border-[#39B54A] outline-none"
                    />
                  </div>
                  <button
                    onClick={addEmployer}
                    className="w-full py-2.5 bg-gray-100 text-gray-700 rounded-xl hover:bg-gray-200 font-medium"
                  >
                    + Add Employer
                  </button>
                </div>

                <div className="mt-6 flex justify-end gap-3">
                  <button
                    onClick={() => { setActiveSection(null); initializeFormData(profile!); }}
                    className="px-4 py-2 border border-gray-300 text-gray-700 rounded-xl hover:bg-[#39B54A]/5"
                  >
                    Cancel
                  </button>
                  <button
                    onClick={handleSave}
                    disabled={isSaving}
                    className="px-6 py-2 bg-[#39B54A] text-white rounded-xl hover:bg-[#2d913c] disabled:opacity-50"
                  >
                    {isSaving ? "Saving..." : "Save Changes"}
                  </button>
                </div>
              </div>
            )}
          </div>

          {/* Emergency Contact Section */}
          <div className="bg-white rounded-xl border border-gray-100/80 overflow-hidden">
            <button
              onClick={() => setActiveSection(activeSection === "emergency" ? null : "emergency")}
              className="w-full flex items-center justify-between p-6 hover:bg-[#39B54A]/5 transition-colors"
            >
              <div className="flex items-center gap-3">
                <div className="w-10 h-10 bg-red-50 rounded-xl flex items-center justify-center ring-1 ring-red-100">
                  <AlertTriangle size={18} className="text-red-500" />
                </div>
                <div className="text-left">
                  <h2 className="text-base font-semibold text-gray-900">Emergency Contact</h2>
                  <p className="text-sm text-gray-500">Contact in case of emergency</p>
                </div>
              </div>
              <ChevronDown size={18} className={`text-gray-400 transition-transform ${activeSection === "emergency" ? "rotate-180" : ""}`} />
            </button>

            {activeSection === "emergency" && (
              <div className="px-6 pb-6 border-t border-gray-100 pt-6">
                <div className="grid md:grid-cols-2 gap-4">
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">Contact Name</label>
                    <input
                      type="text"
                      value={formData.emergencyContact.name}
                      onChange={(e) => setFormData({
                        ...formData,
                        emergencyContact: { ...formData.emergencyContact, name: e.target.value }
                      })}
                      className="w-full px-4 py-2.5 border border-gray-200 rounded-xl focus:ring-2 focus:ring-[#39B54A]/20 focus:border-[#39B54A] outline-none"
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">Relationship</label>
                    <input
                      type="text"
                      value={formData.emergencyContact.relationship}
                      onChange={(e) => setFormData({
                        ...formData,
                        emergencyContact: { ...formData.emergencyContact, relationship: e.target.value }
                      })}
                      placeholder="e.g., Spouse, Parent, Sibling"
                      className="w-full px-4 py-2.5 border border-gray-200 rounded-xl focus:ring-2 focus:ring-[#39B54A]/20 focus:border-[#39B54A] outline-none"
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">Phone Number</label>
                    <input
                      type="tel"
                      value={formData.emergencyContact.phone}
                      onChange={(e) => setFormData({
                        ...formData,
                        emergencyContact: { ...formData.emergencyContact, phone: e.target.value }
                      })}
                      className="w-full px-4 py-2.5 border border-gray-200 rounded-xl focus:ring-2 focus:ring-[#39B54A]/20 focus:border-[#39B54A] outline-none"
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">Email (Optional)</label>
                    <input
                      type="email"
                      value={formData.emergencyContact.email}
                      onChange={(e) => setFormData({
                        ...formData,
                        emergencyContact: { ...formData.emergencyContact, email: e.target.value }
                      })}
                      className="w-full px-4 py-2.5 border border-gray-200 rounded-xl focus:ring-2 focus:ring-[#39B54A]/20 focus:border-[#39B54A] outline-none"
                    />
                  </div>
                </div>

                <div className="mt-6 flex justify-end gap-3">
                  <button
                    onClick={() => { setActiveSection(null); initializeFormData(profile!); }}
                    className="px-4 py-2 border border-gray-300 text-gray-700 rounded-xl hover:bg-[#39B54A]/5"
                  >
                    Cancel
                  </button>
                  <button
                    onClick={handleSave}
                    disabled={isSaving}
                    className="px-6 py-2 bg-[#39B54A] text-white rounded-xl hover:bg-[#2d913c] disabled:opacity-50"
                  >
                    {isSaving ? "Saving..." : "Save Changes"}
                  </button>
                </div>
              </div>
            )}
          </div>
        </div>
      </div>
    </CaregiverLayout>
  );
}

"use client";

import { useEffect, useState } from "react";
import Link from "next/link";
import { useRouter } from "next/navigation";
import { Logo } from "@/components/ui/Logo";
import { userService } from "@/features/user/services";
import { authService } from "@/features/auth/services";
import type { ProfileUpdateData } from "@/features/user/types";
import { CARE_NEED_OPTIONS as CARE_NEED_OPTION_LIST } from "@/lib/constants";
import AvatarUpload from "@/components/ui/AvatarUpload";

interface UserProfile {
  _id: string;
  fullName: string;
  email: string;
  phone?: string;
  age?: number;
  gender?: string;
  avatar?: string;
  role: string;
  status: string;
  location?: {
    city?: string;
    state?: string;
    country?: string;
    address?: string;
    postalCode?: string;
  };
  bio?: string;
  careNeeds?: string[];
  preferredSchedule?: {
    days?: string[];
    hours?: { start?: string; end?: string };
  };
  budget?: {
    min?: number;
    max?: number;
    type?: string;
  };
  familyMembers?: {
    name?: string;
    age?: number;
    relationship?: string;
    specialNeeds?: string;
  }[];
  createdAt?: string;
  isEmailVerified?: boolean;
  isProfileComplete?: boolean;
}

// Care need options — from shared constants
const CARE_NEED_OPTIONS = CARE_NEED_OPTION_LIST.map((opt) => opt.label);

// Days of the week
const DAYS_OF_WEEK = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"];

export default function CareseekerProfilePage() {
  const router = useRouter();
  const [profile, setProfile] = useState<UserProfile | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [isEditing, setIsEditing] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [error, setError] = useState("");
  const [successMessage, setSuccessMessage] = useState("");

  // Form state
  const [formData, setFormData] = useState({
    fullName: "",
    phone: "",
    age: "",
    gender: "",
    bio: "",
    careNeeds: [] as string[],
    city: "",
    state: "",
    country: "",
    address: "",
    postalCode: "",
    preferredDays: [] as string[],
    preferredHoursStart: "",
    preferredHoursEnd: "",
    budgetMin: "",
    budgetMax: "",
    budgetType: "hourly",
  });

  // Family members state
  const [familyMembers, setFamilyMembers] = useState<{
    name: string;
    age: string;
    relationship: string;
    specialNeeds: string;
  }[]>([]);

  useEffect(() => {
    fetchProfile();
  }, []);

  const fetchProfile = async () => {
    try {
      setIsLoading(true);
      const token = localStorage.getItem("careconnect_token");
      if (!token) {
        router.push("/login");
        return;
      }

      const response = await userService.getProfile();

      if (!response.success || !response.data) {
        throw new Error("Failed to fetch profile");
      }

      const user = response.data.user;

      // Check if user is a careseeker
      if (user.role !== "careseeker") {
        router.push(`/profile/${user.role}`);
        return;
      }

      setProfile(user as unknown as UserProfile);

      // Initialize form with profile data
      setFormData({
        fullName: user.fullName || "",
        phone: user.phone || "",
        age: user.age?.toString() || "",
        gender: user.gender || "",
        bio: user.bio || "",
        careNeeds: user.careNeeds || [],
        city: user.location?.city || "",
        state: user.location?.state || "",
        country: user.location?.country || "",
        address: user.location?.address || "",
        postalCode: user.location?.postalCode || "",
        preferredDays: user.preferredSchedule?.days || [],
        preferredHoursStart: user.preferredSchedule?.hours?.start || "",
        preferredHoursEnd: user.preferredSchedule?.hours?.end || "",
        budgetMin: user.budget?.min?.toString() || "",
        budgetMax: user.budget?.max?.toString() || "",
        budgetType: user.budget?.type || "hourly",
      });

      // Initialize family members
      setFamilyMembers(
        user.familyMembers?.map((m: { name?: string; age?: number; relationship?: string; specialNeeds?: string }) => ({
          name: m.name || "",
          age: m.age?.toString() || "",
          relationship: m.relationship || "",
          specialNeeds: m.specialNeeds || "",
        })) || []
      );
    } catch (err) {
      console.error("Error fetching profile:", err);
      setError("Failed to load profile");
    } finally {
      setIsLoading(false);
    }
  };

  const handleSave = async () => {
    try {
      setIsSaving(true);
      setError("");

      const parsedAge = formData.age ? parseInt(formData.age, 10) : undefined;
      const parsedGender = formData.gender
        ? (formData.gender as "male" | "female" | "other")
        : undefined;
      const parsedBudgetMin = formData.budgetMin ? parseFloat(formData.budgetMin) : undefined;
      const parsedBudgetMax = formData.budgetMax ? parseFloat(formData.budgetMax) : undefined;

      const updateData = {
        fullName: formData.fullName,
        phone: formData.phone,
        ...(parsedAge !== undefined && { age: parsedAge }),
        ...(parsedGender !== undefined && { gender: parsedGender }),
        bio: formData.bio,
        careNeeds: formData.careNeeds,
        location: {
          city: formData.city,
          state: formData.state,
          country: formData.country,
          address: formData.address,
          postalCode: formData.postalCode,
        },
        preferredSchedule: {
          days: formData.preferredDays,
          hours: {
            start: formData.preferredHoursStart,
            end: formData.preferredHoursEnd,
          },
        },
        budget: {
          ...(parsedBudgetMin !== undefined && { min: parsedBudgetMin }),
          ...(parsedBudgetMax !== undefined && { max: parsedBudgetMax }),
          type: formData.budgetType as "hourly" | "daily" | "weekly" | "monthly",
        },
        familyMembers: familyMembers
          .filter((m) => m.name)
          .map((m) => ({
            name: m.name,
            ...(m.age ? { age: parseInt(m.age, 10) } : {}),
            relationship: m.relationship,
            specialNeeds: m.specialNeeds,
          })),
      } satisfies ProfileUpdateData;

      const response = await userService.updateProfile(updateData);

      if (!response.success || !response.data) {
        throw new Error("Failed to update profile");
      }

      setProfile(response.data.user as unknown as UserProfile);
      setIsEditing(false);
      setSuccessMessage("Profile updated successfully!");
      setTimeout(() => setSuccessMessage(""), 3000);
    } catch (err) {
      console.error("Error updating profile:", err);
      setError("Failed to update profile");
    } finally {
      setIsSaving(false);
    }
  };

  const toggleCareNeed = (need: string) => {
    setFormData((prev) => ({
      ...prev,
      careNeeds: prev.careNeeds.includes(need)
        ? prev.careNeeds.filter((n) => n !== need)
        : [...prev.careNeeds, need],
    }));
  };

  const toggleDay = (day: string) => {
    setFormData((prev) => ({
      ...prev,
      preferredDays: prev.preferredDays.includes(day)
        ? prev.preferredDays.filter((d) => d !== day)
        : [...prev.preferredDays, day],
    }));
  };

  const addFamilyMember = () => {
    setFamilyMembers((prev) => [
      ...prev,
      { name: "", age: "", relationship: "", specialNeeds: "" },
    ]);
  };

  const removeFamilyMember = (index: number) => {
    setFamilyMembers((prev) => prev.filter((_, i) => i !== index));
  };

  const updateFamilyMember = (index: number, field: string, value: string) => {
    setFamilyMembers((prev) =>
      prev.map((member, i) =>
        i === index ? { ...member, [field]: value } : member
      )
    );
  };

  const handleLogout = async () => {
    await authService.logout();
    router.push("/home");
  };

  if (isLoading) {
    return (
      <div className="min-h-screen bg-[#F0F5FF] flex items-center justify-center">
        <div className="w-12 h-12 border-4 border-primary-500 border-t-transparent rounded-full animate-spin"></div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#F0F5FF]">
      {/* Header */}
      <header className="sticky top-0 z-50 bg-white border-b border-[#E1E6EF] shadow-sm">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between items-center h-16">
            <Logo variant="default" showText href="/home" />

            <nav className="flex items-center gap-6">
              <Link href="/home" className="text-sm font-medium text-gray-600 hover:text-primary-500">Home</Link>
              <Link href="/dashboard" className="text-sm font-medium text-gray-600 hover:text-primary-500">Dashboard</Link>
              <Link href="/caregivers" className="text-sm font-medium text-gray-600 hover:text-primary-500">Find Caregivers</Link>
              <button
                onClick={handleLogout}
                className="text-sm font-medium text-gray-600 hover:text-gray-800"
              >
                Logout
              </button>
            </nav>
          </div>
        </div>
      </header>

      {/* Main Content */}
      <main className="max-w-4xl mx-auto px-4 py-8">
        {/* Success/Error Messages */}
        {successMessage && (
          <div className="mb-6 p-4 bg-green-50 border border-green-200 rounded-xl text-green-700 text-sm">
            {successMessage}
          </div>
        )}
        {error && (
          <div className="mb-6 p-4 bg-red-50 border border-red-200 rounded-xl text-red-700 text-sm">
            {error}
          </div>
        )}

        {/* Profile Header Card */}
        <div className="bg-white rounded-2xl shadow-lg overflow-hidden mb-6">
          {/* Cover Image */}
          <div className="h-32 bg-linear-to-r from-primary-500 to-secondary-500"></div>

          <div className="px-6 pb-6">
            {/* Avatar and Actions */}
            <div className="flex flex-col lg:flex-row lg:items-start lg:justify-between -mt-12 mb-4 gap-4">
              {/* Left: Avatar + Name */}
              <div className="flex flex-col sm:flex-row items-center sm:items-start gap-4">
                {/* Avatar Upload Section */}
                <div className="shrink-0">
                  <AvatarUpload
                    {...(profile?.avatar !== undefined && { avatar: profile.avatar })}
                    {...(profile?.fullName !== undefined && { fullName: profile.fullName })}
                    accentColor="#3A5BDB"
                    size={100}
                    onAvatarChange={(newUrl) => {
                      setProfile((prev) => prev ? { ...prev, avatar: newUrl } : prev);
                      const stored = authService.getCurrentUser();
                      if (stored) {
                        authService.updateStoredUser({ ...stored, avatar: newUrl });
                        window.dispatchEvent(new Event("userUpdated"));
                      }
                    }}
                  />
                </div>
                {/* Name & Role */}
                <div className="text-center sm:text-left pt-2 sm:pt-16">
                  <div className="flex items-center justify-center sm:justify-start gap-2">
                    <h1 className="text-2xl font-bold text-gray-900">{profile?.fullName}</h1>
                    {profile?.isEmailVerified && (
                      <svg className="w-5 h-5 text-blue-500" fill="currentColor" viewBox="0 0 20 20">
                        <path fillRule="evenodd" d="M6.267 3.455a3.066 3.066 0 001.745-.723 3.066 3.066 0 013.976 0 3.066 3.066 0 001.745.723 3.066 3.066 0 012.812 2.812c.051.643.304 1.254.723 1.745a3.066 3.066 0 010 3.976 3.066 3.066 0 00-.723 1.745 3.066 3.066 0 01-2.812 2.812 3.066 3.066 0 00-1.745.723 3.066 3.066 0 01-3.976 0 3.066 3.066 0 00-1.745-.723 3.066 3.066 0 01-2.812-2.812 3.066 3.066 0 00-.723-1.745 3.066 3.066 0 010-3.976 3.066 3.066 0 00.723-1.745 3.066 3.066 0 012.812-2.812zm7.44 5.252a1 1 0 00-1.414-1.414L9 10.586 7.707 9.293a1 1 0 00-1.414 1.414l2 2a1 1 0 001.414 0l4-4z" clipRule="evenodd" />
                      </svg>
                    )}
                  </div>
                  <p className="text-gray-500">Care Seeker</p>
                </div>
              </div>
              {/* Right: Action Buttons */}
              <div className="flex justify-center sm:justify-start lg:justify-end pt-0 lg:pt-16">
                {!isEditing ? (
                  <button
                    onClick={() => setIsEditing(true)}
                    className="px-6 py-2.5 bg-primary-500 hover:bg-[#2F4BDB] text-white font-medium rounded-xl transition-colors"
                  >
                    Edit Profile
                  </button>
                ) : (
                  <div className="flex gap-2">
                    <button
                      onClick={() => setIsEditing(false)}
                      className="px-4 py-2.5 border border-gray-300 text-gray-700 font-medium rounded-xl hover:bg-[#F0F5FF] transition-colors"
                    >
                      Cancel
                    </button>
                    <button
                      onClick={handleSave}
                      disabled={isSaving}
                      className="px-6 py-2.5 bg-primary-500 hover:bg-[#2F4BDB] text-white font-medium rounded-xl transition-colors disabled:opacity-50"
                    >
                      {isSaving ? "Saving..." : "Save Changes"}
