// ============================================
// ERROR BOUNDARY - Production Error Handling
// ============================================

'use client';

import React, { Component, ReactNode } from 'react';
import { AlertTriangle, RefreshCw, Home } from 'lucide-react';

interface Props {
  children: ReactNode;
  fallback?: ReactNode;
  onError?: (error: Error, errorInfo: React.ErrorInfo) => void;
}

interface State {
  hasError: boolean;
  error: Error | null;
  errorInfo: React.ErrorInfo | null;
}

export class ErrorBoundary extends Component<Props, State> {
  constructor(props: Props) {
    super(props);
    this.state = {
      hasError: false,
      error: null,
      errorInfo: null,
    };
  }

  static getDerivedStateFromError(error: Error): Partial<State> {
    return {
      hasError: true,
      error,
    };
  }

  componentDidCatch(error: Error, errorInfo: React.ErrorInfo) {
    // Log error to console in development
    if (process.env.NODE_ENV === 'development') {
      console.error('ErrorBoundary caught an error:', error, errorInfo);
    }

    // Call custom error handler if provided
    this.props.onError?.(error, errorInfo);

    // In production, you'd send this to an error reporting service
    // Example: Sentry.captureException(error, { contexts: { react: errorInfo } });

    this.setState({
      errorInfo,
    });
  }

  handleReset = () => {
    this.setState({
      hasError: false,
      error: null,
      errorInfo: null,
    });
  };

  handleReload = () => {
    window.location.reload();
  };

  handleGoHome = () => {
    window.location.href = '/';
  };

  render() {
    if (this.state.hasError) {
      // Use custom fallback if provided
      if (this.props.fallback) {
        return this.props.fallback;
      }

      // Default error UI
      return (
        <div className="min-h-screen flex items-center justify-center bg-gray-50 px-4">
          <div className="max-w-md w-full bg-white rounded-2xl shadow-xl p-8 text-center">
            <div className="mb-6">
              <div className="inline-flex items-center justify-center w-16 h-16 rounded-full bg-red-100 mb-4">
                <AlertTriangle className="w-8 h-8 text-red-600" />
              </div>
              <h1 className="text-2xl font-bold text-gray-900 mb-2">
                Oops! Something went wrong
              </h1>
              <p className="text-gray-600">
                We're sorry for the inconvenience. The application encountered an unexpected error.
              </p>
            </div>

            {process.env.NODE_ENV === 'development' && this.state.error && (
              <div className="mb-6 p-4 bg-red-50 rounded-lg text-left">
                <p className="text-xs font-mono text-red-800 break-words">
                  {this.state.error.toString()}
                </p>
                {this.state.errorInfo && (
                  <details className="mt-2">
                    <summary className="text-xs text-red-700 cursor-pointer">
                      Stack trace
                    </summary>
                    <pre className="text-xs text-red-600 mt-2 overflow-auto max-h-40">
                      {this.state.errorInfo.componentStack}
                    </pre>
                  </details>
                )}
              </div>
            )}

            <div className="flex flex-col sm:flex-row gap-3">
              <button
                onClick={this.handleReset}
                className="flex-1 flex items-center justify-center gap-2 px-4 py-3 bg-[#39B54A] text-white rounded-lg hover:bg-[#2d8f3a] transition-colors font-medium"
              >
                <RefreshCw className="w-4 h-4" />
                Try Again
              </button>
              <button
                onClick={this.handleGoHome}
                className="flex-1 flex items-center justify-center gap-2 px-4 py-3 bg-gray-100 text-gray-700 rounded-lg hover:bg-gray-200 transition-colors font-medium"
              >
                <Home className="w-4 h-4" />
                Go Home
              </button>
            </div>

            <button
              onClick={this.handleReload}
              className="mt-3 w-full text-sm text-gray-500 hover:text-gray-700 transition-colors"
            >
              Or reload the page
            </button>
          </div>
        </div>
      );
    }

    return this.props.children;
  }
}

export default ErrorBoundary;

"use client";

import * as React from "react";
import { motion, AnimatePresence } from "framer-motion";
import AdminLayout from "@/components/layout/AdminLayout";
import { adminService, authService, type AdminUser } from "@/services";
import UserTable from "./UserTable";
import UserProfileDrawer from "./UserProfileDrawer";
import type { UserTableFilters } from "./FiltersBar";

type Pagination = { page: number; limit: number; total: number; pages: number };

type AuditLogEntry = {
  id: string;
  timestamp: string;
  adminName: string;
  action: "approve" | "activate" | "suspend" | "delete" | "role_change";
  targetUserId: string;
  targetUserName: string;
  notes?: string;
};

function uid(prefix: string) {
  return `${prefix}_${Math.random().toString(16).slice(2)}_${Date.now()}`;
}

function formatTS(ts: string) {
  const d = new Date(ts);
  if (Number.isNaN(d.getTime())) return "—";
  return d.toLocaleString(undefined, { month: "short", day: "2-digit", year: "numeric", hour: "2-digit", minute: "2-digit" });
}

function adminDisplayName() {
  try {
    const u = authService.getCurrentUser();
    return u?.fullName ?? u?.email ?? "Admin";
  } catch {
    return "Admin";
  }
}

export default function AdminUsersPremium() {
  const [users, setUsers] = React.useState<AdminUser[]>([]);
  const [pagination, setPagination] = React.useState<Pagination>({ page: 1, limit: 20, total: 0, pages: 0 });
  const [loading, setLoading] = React.useState(true);

  const [selectedUser, setSelectedUser] = React.useState<AdminUser | null>(null);
  const [drawerOpen, setDrawerOpen] = React.useState(false);
  const [actionLoadingUserId, setActionLoadingUserId] = React.useState<string | null>(null);
  const [roleChanging, setRoleChanging] = React.useState(false);
  const [refreshToken, setRefreshToken] = React.useState(0);

  const [toast, setToast] = React.useState<{ type: "success" | "error"; message: string } | null>(null);
  const toastTimer = React.useRef<number | null>(null);

  const [auditLogs, setAuditLogs] = React.useState<AuditLogEntry[]>([]);
  const [auditAction, setAuditAction] = React.useState<"all" | AuditLogEntry["action"]>("all");
  const [auditView, setAuditView] = React.useState<"timeline" | "table">("timeline");

  const adminName = React.useMemo(() => adminDisplayName(), []);

  const showToast = React.useCallback((type: "success" | "error", message: string) => {
    setToast({ type, message });
    if (toastTimer.current) window.clearTimeout(toastTimer.current);
    toastTimer.current = window.setTimeout(() => setToast(null), 3500);
  }, []);

  const logAdminAction = React.useCallback((entry: { action: AuditLogEntry["action"]; targetUserId: string; targetUserName: string }) => {
    setAuditLogs((prev) => [
      {
        id: uid("audit"),
        timestamp: new Date().toISOString(),
        adminName,
        action: entry.action,
        targetUserId: entry.targetUserId,
        targetUserName: entry.targetUserName,
      },
      ...prev,
    ]);
  }, [adminName]);

  const fetchUsers = React.useCallback(
    async ({ page, filters }: { page: number; filters: UserTableFilters }) => {
      setLoading(true);
      try {
        const now = Date.now();
        const toIso = new Date(now).toISOString();

        const rangeMs =
          filters.dateRange === "7d"
            ? 7 * 24 * 60 * 60 * 1000
            : filters.dateRange === "30d"
            ? 30 * 24 * 60 * 60 * 1000
            : filters.dateRange === "90d"
            ? 90 * 24 * 60 * 60 * 1000
            : null;

        const fromIso = rangeMs ? new Date(now - rangeMs).toISOString() : undefined;

        const role =
          filters.activityType === "caregiver" ? "caregiver" : filters.activityType === "careseeker" ? "careseeker" : undefined;

        const data = await adminService.getUsers({
          page,
          limit: pagination.limit,
          role,
          status: filters.status === "all" ? undefined : filters.status,
          search: filters.search || undefined,
          sortBy: "lastLogin",
          sortOrder: "desc",
          // backend supports lastLogin filtering
          lastActiveFrom: fromIso,
          lastActiveTo: fromIso ? toIso : undefined,
        } as any);

        setUsers(data.users);
        setPagination(data.pagination as Pagination);
      } catch (e: any) {
        const msg = typeof e?.message === "string" ? e.message : "Failed to load users";
        showToast("error", msg);
      } finally {
        setLoading(false);
      }
    },
    [pagination.limit, showToast]
  );

  const approveUserApi = React.useCallback(
    async (id: string) => {
      setActionLoadingUserId(id);
      try {
        await adminService.approveUser(id);
        showToast("success", "User approved");
      } finally {
        setActionLoadingUserId(null);
        setRefreshToken((t) => t + 1);
      }
    },
    [showToast]
  );

  const activateUserApi = React.useCallback(
    async (id: string) => {
      setActionLoadingUserId(id);
      try {
        await adminService.updateUserStatus(id, "active");
        showToast("success", "User activated");
      } finally {
        setActionLoadingUserId(null);
        setRefreshToken((t) => t + 1);
      }
    },
    [showToast]
  );

  const suspendUserApi = React.useCallback(
    async (id: string) => {
      setActionLoadingUserId(id);
      try {
        await adminService.suspendUser(id, "Suspended by admin");
        showToast("success", "User suspended");
      } finally {
        setActionLoadingUserId(null);
        setRefreshToken((t) => t + 1);
      }
    },
    [showToast]
  );

  const deleteUserApi = React.useCallback(
    async (id: string) => {
      setActionLoadingUserId(id);
      try {
        await adminService.deleteUser(id);
        showToast("success", "User deleted");
      } finally {
        setActionLoadingUserId(null);
        setRefreshToken((t) => t + 1);
      }
    },
    [showToast]
  );

  const roleChangeApi = React.useCallback(
    async (id: string, nextRole: string) => {
      setRoleChanging(true);
      setActionLoadingUserId(id);
      try {
        await adminService.updateUserRole(id, nextRole);
        showToast("success", "Role updated");
      } finally {
        setRoleChanging(false);
        setActionLoadingUserId(null);
        setRefreshToken((t) => t + 1);
      }
    },
    [showToast]
  );

  const approveFromTable = React.useCallback(
    async (id: string) => {
      logAdminAction({
        action: "approve",
        targetUserId: id,
        targetUserName: users.find((u) => u._id === id)?.fullName ?? "User",
      });
      await approveUserApi(id);
    },
    [approveUserApi, logAdminAction, users]
  );

  const activateFromTable = React.useCallback(
    async (id: string) => {
      logAdminAction({
        action: "activate",
        targetUserId: id,
        targetUserName: users.find((u) => u._id === id)?.fullName ?? "User",
      });
      await activateUserApi(id);
    },
    [activateUserApi, logAdminAction, users]
  );

  const suspendFromTable = React.useCallback(
    async (id: string) => {
      logAdminAction({
        action: "suspend",
        targetUserId: id,
        targetUserName: users.find((u) => u._id === id)?.fullName ?? "User",
      });
      await suspendUserApi(id);
    },
    [logAdminAction, suspendUserApi, users]
  );

  return (
    <AdminLayout>
      <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.35 }} className="space-y-6">
        {toast ? (
          <div
            className={`
              fixed top-4 right-4 z-[120] px-4 py-3 rounded-2xl shadow-sm border
              ${toast.type === "success" ? "bg-emerald-50 border-emerald-200 text-emerald-800" : "bg-rose-50 border-rose-200 text-rose-800"}
            `}
          >
            <div className="text-sm font-semibold">{toast.message}</div>
          </div>
        ) : null}

        <UserTable
          users={users}
          pagination={pagination}
          loading={loading}
          onFetchUsers={fetchUsers as any}
          onSelectUser={(u) => {
            setSelectedUser(u);
            setDrawerOpen(true);
          }}
          onApproveUser={approveFromTable}
          onActivateUser={activateFromTable}
          onSuspendUser={suspendFromTable}
          actionLoadingUserId={actionLoadingUserId}
          refreshToken={refreshToken}
        />

        <div className="bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden">
          <div className="px-6 py-4 border-b border-slate-100 flex items-start justify-between gap-4">
            <div className="min-w-0">
              <h3 className="text-base font-semibold text-slate-900 truncate">Admin Audit Logs</h3>
              <p className="text-sm text-slate-500 mt-0.5">Timeline/table view of admin actions</p>
            </div>
            <div className="flex flex-wrap items-center gap-2">
              <select
                value={auditAction}
                onChange={(e) => setAuditAction(e.target.value as any)}
                className="rounded-2xl border border-slate-200 bg-white px-3 py-2 text-sm outline-none focus:ring-2 focus:ring-[#0F766E]/20 focus:border-[#0F766E]"
                aria-label="Filter by action"
              >
                <option value="all">All actions</option>
                <option value="approve">approve</option>
                <option value="activate">activate</option>
                <option value="suspend">suspend</option>
                <option value="delete">delete</option>
                <option value="role_change">role_change</option>
              </select>

              <button
                type="button"
                onClick={() => setAuditView((p) => (p === "timeline" ? "table" : "timeline"))}
                className="rounded-2xl border border-slate-200 bg-white hover:bg-slate-50 px-3 py-2 text-sm font-semibold text-slate-700 transition"
              >
                {auditView === "timeline" ? "Table view" : "Timeline view"}
              </button>
            </div>
          </div>

          <div className="p-6">
            {auditLogs.length === 0 ? (
              <div className="py-8 text-center">
                <p className="text-sm font-medium text-slate-700">No audit logs yet</p>
                <p className="text-xs text-slate-500 mt-1">Perform an admin action to populate this panel.</p>
              </div>
            ) : (
              (() => {
                const visible = auditLogs.filter((l) => (auditAction === "all" ? true : l.action === auditAction));
                if (auditView === "table") {
                  return (
                    <div className="overflow-x-auto">
                      <table className="w-full min-w-[700px] border-separate border-spacing-0">
                        <thead className="bg-slate-50 sticky top-0 z-10">
                          <tr className="text-left text-xs font-semibold text-slate-500 uppercase tracking-wider">
                            <th className="px-4 py-3">Time</th>
                            <th className="px-4 py-3">Admin</th>
                            <th className="px-4 py-3">Action</th>
                            <th className="px-4 py-3">Target</th>
                          </tr>
                        </thead>
                        <tbody className="divide-y divide-slate-100">
                          <AnimatePresence initial={false}>
                            {visible.map((l) => (
                              <motion.tr
                                key={l.id}
                                initial={{ opacity: 0, y: 6 }}
                                animate={{ opacity: 1, y: 0 }}
                                whileHover={{ y: -1 }}
                                className="bg-white"
                              >
                                <td className="px-4 py-3 text-sm text-slate-700">{formatTS(l.timestamp)}</td>
                                <td className="px-4 py-3 text-sm text-slate-700">{l.adminName}</td>
                                <td className="px-4 py-3 text-sm text-slate-700 font-semibold capitalize">{l.action}</td>
                                <td className="px-4 py-3 text-sm text-slate-700">
                                  <span className="font-semibold">{l.targetUserName}</span>
                                </td>
                              </motion.tr>
                            ))}
                          </AnimatePresence>
                        </tbody>
                      </table>
                    </div>
                  );
                }

                return (
                  <div className="space-y-3">
                    {visible.map((l) => (
                      <motion.div
                        key={l.id}
                        initial={{ opacity: 0, y: 6 }}
                        animate={{ opacity: 1, y: 0 }}
                        whileHover={{ y: -1 }}
                        className="bg-white border border-slate-200 rounded-2xl p-4"
                      >
                        <div className="flex items-start justify-between gap-4">
                          <div className="min-w-0">
                            <p className="text-sm font-semibold text-slate-900">
                              {l.action.replace("_", " ")}{" "}
                              <span className="text-slate-500 font-medium">• {l.targetUserName}</span>
                            </p>
                            <p className="text-xs text-slate-500 mt-1">
                              {l.adminName} • {formatTS(l.timestamp)}
                            </p>
                          </div>
                          <span className="inline-flex items-center rounded-full border border-slate-200 bg-slate-50 px-3 py-1 text-xs font-semibold text-slate-700">
                            Admin action
                          </span>
                        </div>
                      </motion.div>
                    ))}
                  </div>
                );
              })()
            )}
          </div>
        </div>

        <UserProfileDrawer
          user={selectedUser}
          isOpen={drawerOpen}
          onClose={() => {
            setDrawerOpen(false);
            setSelectedUser(null);
          }}
          onApprove={async (id) => approveUserApi(id)}
          onSuspend={async (id) => suspendUserApi(id)}
          onActivate={async (id) => activateUserApi(id)}
          onDelete={async (id) => deleteUserApi(id)}
          onRoleChange={async (id, nextRole) => {
            await roleChangeApi(id, nextRole);
          }}
          roleChanging={roleChanging}
          actionLoading={Boolean(actionLoadingUserId)}
          onLogAdminAction={(entry) => logAdminAction({ action: entry.action as any, targetUserId: entry.targetUserId, targetUserName: entry.targetUserName })}
        />
      </motion.div>
    </AdminLayout>
  );
}

"use client";

import * as React from "react";
import { motion } from "framer-motion";
import {
  Area,
  AreaChart,
  Bar,
  BarChart,
  CartesianGrid,
  Line,
  LineChart,
  ResponsiveContainer,
  Tooltip,
  XAxis,
  YAxis,
} from "recharts";

export type ChartPoint = { label: string; value: number };

type FeatureUsagePoint = { label: string; value: number; color?: string };

function ChartCard({ title, subtitle, children }: { title: string; subtitle?: string; children: React.ReactNode }) {
  return (
    <motion.section
      initial={{ opacity: 0, y: 10 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.4 }}
      className="bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden"
    >
      <div className="px-6 py-5 border-b border-slate-100">
        <div className="flex items-start justify-between gap-4">
          <div className="min-w-0">
            <h3 className="text-base font-semibold text-slate-900 truncate">{title}</h3>
            {subtitle ? <p className="text-sm text-slate-500 mt-0.5">{subtitle}</p> : null}
          </div>
        </div>
      </div>
      <div className="p-6">{children}</div>
    </motion.section>
  );
}

function TooltipCard({ active, payload, label }: { active?: boolean; payload?: Array<any>; label?: any }) {
  if (!active || !payload?.length) return null;
  const first = payload[0];
  const value = typeof first?.value === "number" ? first.value : Number(first?.value ?? 0);
  return (
    <div className="bg-white border border-slate-200 rounded-xl shadow-sm px-3 py-2">
      <p className="text-xs font-medium text-slate-500">{label}</p>
      <p className="text-sm font-semibold text-slate-900 tabular-nums">{value.toLocaleString()}</p>
    </div>
  );
}

export default function AnalyticsCharts({
  dailyActiveUsers,
  featureUsage,
  growth,
}: {
  dailyActiveUsers: ChartPoint[];
  featureUsage: FeatureUsagePoint[];
  growth: ChartPoint[];
}) {
  const teal = "#0F766E";
  const teal2 = "#0EA5A4";
  const grid = "#E2E8F0";

  return (
    <div className="grid grid-cols-1 xl:grid-cols-3 gap-6">
      <ChartCard title="Daily Active Users" subtitle="Last 7 days (trend)" >
        <div className="h-[240px]">
          <ResponsiveContainer width="100%" height="100%">
            <LineChart data={dailyActiveUsers}>
              <defs>
                <linearGradient id="daU" x1="0" y1="0" x2="0" y2="1">
                  <stop offset="5%" stopColor={teal} stopOpacity={0.25} />
                  <stop offset="95%" stopColor={teal} stopOpacity={0} />
                </linearGradient>
              </defs>
              <CartesianGrid stroke={grid} strokeDasharray="3 3" vertical={false} />
              <XAxis dataKey="label" stroke="#94A3B8" tick={{ fontSize: 12 }} axisLine={false} tickLine={false} />
              <YAxis stroke="#94A3B8" tick={{ fontSize: 12 }} axisLine={false} tickLine={false} />
              <Tooltip content={<TooltipCard />} />
              <Line
                type="monotone"
                dataKey="value"
                stroke={teal}
                strokeWidth={3}
                dot={{ r: 4, fill: teal, stroke: "#fff", strokeWidth: 2 }}
                activeDot={{ r: 6 }}
              />
            </LineChart>
          </ResponsiveContainer>
        </div>
      </ChartCard>

      <ChartCard title="Feature Usage" subtitle="Top admin features" >
        <div className="h-[240px]">
          <ResponsiveContainer width="100%" height="100%">
            <BarChart data={featureUsage.map((p) => ({ label: p.label, value: p.value }))}>
              <CartesianGrid stroke={grid} strokeDasharray="3 3" vertical={false} />
              <XAxis dataKey="label" stroke="#94A3B8" tick={{ fontSize: 12 }} axisLine={false} tickLine={false} />
              <YAxis stroke="#94A3B8" tick={{ fontSize: 12 }} axisLine={false} tickLine={false} />
              <Tooltip content={<TooltipCard />} />
              <Bar dataKey="value" radius={[10, 10, 0, 0]} fill={teal2} />
            </BarChart>
          </ResponsiveContainer>
        </div>
      </ChartCard>

      <ChartCard title="Growth" subtitle="Revenue-ready metrics (simulated)" >
        <div className="h-[240px]">
          <ResponsiveContainer width="100%" height="100%">
            <AreaChart data={growth}>
              <defs>
                <linearGradient id="growthFill" x1="0" y1="0" x2="0" y2="1">
                  <stop offset="5%" stopColor={teal2} stopOpacity={0.28} />
                  <stop offset="95%" stopColor={teal2} stopOpacity={0} />
                </linearGradient>
              </defs>
              <CartesianGrid stroke={grid} strokeDasharray="3 3" vertical={false} />
              <XAxis dataKey="label" stroke="#94A3B8" tick={{ fontSize: 12 }} axisLine={false} tickLine={false} />
              <YAxis stroke="#94A3B8" tick={{ fontSize: 12 }} axisLine={false} tickLine={false} />
              <Tooltip content={<TooltipCard />} />
              <Area
                type="monotone"
                dataKey="value"
                stroke={teal2}
                strokeWidth={3}
                fill="url(#growthFill)"
              />
            </AreaChart>
          </ResponsiveContainer>
        </div>
      </ChartCard>
    </div>
  );
}

"use client";

import { motion } from "framer-motion";
import { Input } from "@/components/ui/Input";
import { Select } from "@/components/ui/Select";
import { cn } from "@/lib/utils";

export type UserTableFilters = {
  search: string;
  dateRange: "7d" | "30d" | "90d" | "all";
  activityType: "all" | "caregiver" | "careseeker";
  status: "all" | "active" | "pending" | "pending_approval" | "suspended" | "deleted";
};

export default function FiltersBar({
  filters,
  onChange,
  onReset,
}: {
  filters: UserTableFilters;
  onChange: (next: UserTableFilters) => void;
  onReset: () => void;
}) {
  return (
    <motion.div
      initial={{ opacity: 0, y: 8 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.35 }}
      className="bg-white rounded-2xl shadow-sm border border-slate-200 p-4"
    >
      <form
        className="grid grid-cols-1 md:grid-cols-5 gap-3 items-end"
        onSubmit={(e) => {
          e.preventDefault();
        }}
      >
        <div className="md:col-span-2">
          <label className="text-xs font-semibold text-slate-500 mb-1 block">Search</label>
          <div className="relative">
            <svg className="w-4 h-4 text-slate-400 absolute left-3 top-1/2 -translate-y-1/2" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
              <path strokeLinecap="round" strokeLinejoin="round" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
            </svg>
            <Input
              placeholder="Name or email…"
              value={filters.search}
              onChange={(e: any) => onChange({ ...filters, search: e.target.value })}
              className="pl-9 rounded-2xl border-slate-200 focus:border-[#0F766E] focus:ring-[#0F766E]/20"
            />
          </div>
        </div>

        <div>
          <label className="text-xs font-semibold text-slate-500 mb-1 block">Date range</label>
          <Select
            value={filters.dateRange}
            onChange={(e) => onChange({ ...filters, dateRange: e.target.value as FiltersBarProps["filters"]["dateRange"] })}
            className={cn("rounded-2xl border-slate-200 focus:ring-[#0F766E]/20 focus:border-[#0F766E]")}
          >
            <option value="all">All time</option>
            <option value="7d">Last 7 days</option>
            <option value="30d">Last 30 days</option>
            <option value="90d">Last 90 days</option>
          </Select>
        </div>

        <div>
          <label className="text-xs font-semibold text-slate-500 mb-1 block">Activity type</label>
          <Select
            value={filters.activityType}
            onChange={(e) =>
              onChange({
                ...filters,
                activityType: e.target.value as FiltersBarProps["filters"]["activityType"],
              })
            }
            className={cn("rounded-2xl border-slate-200 focus:ring-[#0F766E]/20 focus:border-[#0F766E]")}
          >
            <option value="all">All</option>
            <option value="caregiver">Caregivers</option>
            <option value="careseeker">Care Seekers</option>
          </Select>
        </div>

        <div>
          <label className="text-xs font-semibold text-slate-500 mb-1 block">Status</label>
          <Select
            value={filters.status}
            onChange={(e) =>
              onChange({
                ...filters,
                status: e.target.value as FiltersBarProps["filters"]["status"],
              })
            }
            className={cn("rounded-2xl border-slate-200 focus:ring-[#0F766E]/20 focus:border-[#0F766E]")}
          >
            <option value="all">All</option>
            <option value="active">Active</option>
            <option value="pending">Pending Email</option>
            <option value="pending_approval">Pending Approval</option>
            <option value="suspended">Suspended</option>
            <option value="deleted">Deleted</option>
          </Select>
        </div>

        <div className="flex justify-end md:col-span-1">
          <button
            type="button"
            onClick={onReset}
            className="inline-flex items-center justify-center rounded-2xl border border-slate-200 bg-white px-4 py-2.5 text-sm font-semibold text-slate-700 hover:bg-slate-50 hover:shadow-sm transition"
          >
            Reset
          </button>
        </div>
      </form>
    </motion.div>
  );
}

type FiltersBarProps = Parameters<typeof FiltersBar>[0];

"use client";

import { useState } from "react";
import { motion } from "framer-motion";

// ─── Types ───────────────────────────────────────────────────────────────────

export interface TopPage {
  page: string;
  views: number;
  change: number;
}

export interface LocationEntry {
  code: string;
  country: string;
  visitors: number;
  percent: number;
}

export interface CaregiverVisitor {
  id?: string;
  initials: string;
  name: string;
  avatar?: string | undefined;
  searches: number;
  totalVisits: number;
  unique: number;
  growth: number;
}

export interface ProofOfWork {
  initials: string;
  caregiver: string;
  avatar?: string | undefined;
  service: string;
  client: string;
  hours: string;
  rating: number;
  verified: boolean;
  date?: string | undefined;
}

export interface RealtimeData {
  activeNow: number;
  hourlyVisits: { time: string; visits: number }[];
  topReferrers: { source: string; count: number; percent: number }[];
}

// ─── Skeleton ────────────────────────────────────────────────────────────────

function Skeleton({ className }: { className?: string }) {
  return (
    <div className={`animate-pulse bg-gray-100 rounded ${className ?? ""}`} />
  );
}

// ─── Section Card Wrapper ────────────────────────────────────────────────────

function Section({
  icon,
  title,
  badge,
  actions,
  children,
}: {
  icon: React.ReactNode;
  title: string;
  badge?: string | undefined;
  actions?: React.ReactNode | undefined;
  children: React.ReactNode;
}) {
  return (
    <motion.div
      initial={{ opacity: 0, y: 12 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.4 }}
      className="bg-white rounded-2xl border border-gray-100 overflow-hidden"
    >
      <div className="px-6 py-4 flex items-center justify-between border-b border-gray-50">
        <div className="flex items-center gap-2">
          <span className="text-gray-400">{icon}</span>
          <h3 className="text-sm font-semibold text-gray-900">{title}</h3>
        </div>
        <div className="flex items-center gap-3">
          {badge && (
