export function RealtimeWidget({ data }: { data: RealtimeData }) {
  const maxVisits = Math.max(...data.hourlyVisits.map((v) => v.visits), 1);
  const totalReferrers = data.topReferrers.reduce((s, r) => s + r.count, 0);

  return (
    <div className="space-y-6">
      {/* Realtime Visitors */}
      <Section
        icon={
          <svg className="w-4 h-4 text-amber-500" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
            <path strokeLinecap="round" strokeLinejoin="round" d="M13 10V3L4 14h7v7l9-11h-7z" />
          </svg>
        }
        title="Realtime Visitors"
        badge="LIVE"
      >
        <div className="px-6 py-4">
          <div className="flex items-baseline gap-2 mb-5">
            <span className="text-3xl font-bold text-gray-900 tabular-nums">{data.activeNow}</span>
            <span className="text-sm text-gray-500">active right now</span>
            {data.activeNow > 0 && (
              <span className="ml-auto inline-flex items-center gap-1.5 text-xs font-medium text-emerald-700">
                <span className="w-1.5 h-1.5 bg-emerald-500 rounded-full animate-pulse" />
                Online
              </span>
            )}
          </div>
          {/* Bar chart */}
          <div className="flex items-end gap-1 h-16">
            {data.hourlyVisits.map((h, i) => {
              const pct = (h.visits / maxVisits) * 100;
              return (
                <div
                  key={i}
                  title={`${h.time}: ${h.visits}`}
                  className="flex-1 bg-emerald-500 hover:bg-emerald-600 rounded-sm transition-colors cursor-default"
                  style={{ height: `${Math.max(pct, 4)}%` }}
                />
              );
            })}
          </div>
          <div className="flex justify-between mt-2">
            <span className="text-[10px] text-gray-400">{data.hourlyVisits[0]?.time}</span>
            <span className="text-[10px] text-gray-400">{data.hourlyVisits[data.hourlyVisits.length - 1]?.time}</span>
          </div>
        </div>
      </Section>

      {/* Top Referrers */}
      <Section
        icon={
          <svg className="w-4 h-4" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
            <path strokeLinecap="round" strokeLinejoin="round" d="M10 6H6a2 2 0 00-2 2v10a2 2 0 002 2h10a2 2 0 002-2v-4M14 4h6m0 0v6m0-6L10 14" />
          </svg>
        }
        title="Top Referrers"
        badge={totalReferrers === 0 ? "No data yet" : undefined}
      >
        {totalReferrers === 0 ? (
          <div className="px-6 py-5 text-center">
            <p className="text-xs text-gray-400">Referrer tracking not yet enabled.</p>
            <p className="text-xs text-gray-400 mt-0.5">All counts will appear here automatically.</p>
          </div>
        ) : (
          <div className="divide-y divide-gray-50">
            {data.topReferrers.map((r) => (
              <div
                key={r.source}
                className="px-6 py-3.5 flex items-center justify-between hover:bg-gray-50/50 transition-colors"
              >
                <span className="text-sm font-medium text-gray-900">{r.source}</span>
                <div className="flex items-center gap-2">
                  <span className="text-sm font-semibold text-gray-900 tabular-nums">
                    {r.count.toLocaleString()}
                  </span>
                  <span className="text-xs text-gray-400">({r.percent}%)</span>
                </div>
              </div>
            ))}
          </div>
        )}
      </Section>
    </div>
  );
}

