// ─────────────────────────────────────────────
// MAIN COMPONENT
// ─────────────────────────────────────────────

export default function AgreementViewer({
  bookingId: _bookingId,
  bookingNumber,
  agreementContent,
  agreementStatus,
  userRole,
  hasCurrentUserAccepted,
  seekerAccepted = false,
  caregiverAccepted = false,
  onAccept,
  onDownloadPDF,
  isLoading = false,
}: AgreementViewerProps) {
  const [accepting, setAccepting] = useState(false);
  const [downloading, setDownloading] = useState(false);
  const contentRef = useRef<HTMLDivElement>(null);

  const bothAccepted = seekerAccepted && caregiverAccepted;
  const partiallyAccepted =
    (seekerAccepted || caregiverAccepted) && !bothAccepted;

  const handleAccept = async () => {
    if (accepting || hasCurrentUserAccepted) return;
    setAccepting(true);
    try {
      await onAccept();
    } finally {
      setAccepting(false);
    }
  };

  const handleDownload = async () => {
    if (downloading) return;
    setDownloading(true);
    try {
      await onDownloadPDF();
    } finally {
      setDownloading(false);
    }
  };

  const handlePrint = () => {
    if (typeof window !== "undefined") {
      window.print();
    }
  };

  // ── Render guards ──────────────────────────

  if (isLoading) {
    return (
      <div className="w-full max-w-3xl mx-auto px-4 py-6">
        <AgreementSkeleton />
      </div>
    );
  }

  if (agreementStatus === "pending" || !agreementContent) {
    return (
      <div className="w-full max-w-3xl mx-auto px-4 py-6">
        <AgreementPending bookingNumber={bookingNumber} />
      </div>
    );
  }

  const c = agreementContent;

  // ── Full render ────────────────────────────

  return (
    <div className="w-full max-w-3xl mx-auto px-4 py-6 print:px-0 print:py-0">
      {/* ── HEADER ─────────────────────────────── */}
      <motion.div
        variants={headerVariants}
        initial="hidden"
        animate="visible"
        className="mb-6"
      >
        {/* Top bar */}
        <div className="flex flex-col sm:flex-row sm:items-start sm:justify-between gap-4 mb-5">
          <div className="flex items-center gap-3">
            <div className="flex h-11 w-11 shrink-0 items-center justify-center rounded-2xl bg-[#39B54A]/10">
