// powered open / close transitions.
// ============================================

import { useState, useRef, useCallback, useEffect } from "react";
import { motion, AnimatePresence } from "framer-motion";
import {
  X,
  AlertTriangle,
  CreditCard,
  Star,
  UserX,
  ShieldAlert,
  HelpCircle,
  Upload,
  ImageIcon,
  Trash2,
  CheckSquare,
  Square,
  ChevronDown,
  Loader2,
  FileWarning,
  Info,
} from "lucide-react";

// ─────────────────────────────────────────────
// TYPES
// ─────────────────────────────────────────────

export interface DisputeSubmitData {
  bookingId: string;
  category: string;
  subject: string;
  description: string;
  evidence: File[];
}

export interface DisputeFormProps {
  bookingId: string;
  bookingNumber: string;
  isOpen: boolean;
  onClose: () => void;
  onSubmit: (data: DisputeSubmitData) => Promise<void>;
}

// ─────────────────────────────────────────────
// CATEGORY CONFIG
// ─────────────────────────────────────────────

interface CategoryConfig {
  value: string;
  label: string;
  icon: React.ReactNode;
  description: string;
  badgeBg: string;
