  {
    value: "no_show",
    label: "No Show",
    icon: <UserX size={15} />,
    description: "Caregiver did not appear for the scheduled session",
    badgeBg: "bg-rose-100",
    badgeText: "text-rose-700",
    iconBg: "bg-rose-100 text-rose-600",
