                      </span>
                    </div>
                    <input
                      id="dispute-subject"
                      type="text"
                      value={subject}
                      maxLength={100}
                      onChange={(e) => {
                        setSubject(e.target.value);
                        if (errors.subject)
                          setErrors(
                            (prev) =>
                              ({ ...prev, subject: undefined }) as FormErrors,
