"use client";

import React from "react";

// ============================================
// CIRCULAR PROGRESS STAT CARD
// Modern stat card with circular progress indicator
// ============================================

interface CircularProgressStatProps {
  title: string;
  value: string | number;
  subtitle?: string;
  percentage: number;
  color: string;
  trend?: {
    value: number;
    isPositive: boolean;
  };
  icon?: React.ReactNode;
}

export function CircularProgressStat({
  title,
  value,
  subtitle,
  percentage,
  color,
  trend,
}: CircularProgressStatProps) {
  const radius = 36;
  const circumference = 2 * Math.PI * radius;
  const strokeDashoffset = circumference - (percentage / 100) * circumference;

  return (
    <div className="bg-white rounded-2xl p-6 shadow-sm border border-gray-100 hover:shadow-lg transition-all duration-300">
      <div className="flex items-center gap-4">
        {/* Circular Progress */}
        <div className="relative">
          <svg width="88" height="88" className="-rotate-90">
            {/* Background Circle */}
            <circle
              cx="44"
              cy="44"
              r={radius}
              fill="none"
              stroke="#F3F4F6"
              strokeWidth="8"
            />
            {/* Progress Circle */}
            <circle
              cx="44"
              cy="44"
              r={radius}
              fill="none"
              stroke={color}
              strokeWidth="8"
              strokeLinecap="round"
              strokeDasharray={circumference}
              strokeDashoffset={strokeDashoffset}
              className="transition-all duration-700 ease-out"
            />
          </svg>
          {/* Center Content */}
          <div className="absolute inset-0 flex items-center justify-center">
            <span className="text-lg font-bold text-gray-800">{percentage}%</span>
          </div>
        </div>

        {/* Content */}
        <div className="flex-1">
          <p className="text-sm text-gray-500 mb-1">{title}</p>
          <p className="text-2xl font-bold text-gray-900">{value}</p>
          {subtitle && (
            <p className="text-xs text-gray-400 mt-0.5">{subtitle}</p>
          )}
          {trend && (
            <div className={`flex items-center gap-1 mt-2 text-xs font-medium ${
              trend.isPositive ? "text-green-600" : "text-red-500"
            }`}>
              <svg 
                className={`w-3 h-3 ${!trend.isPositive && "rotate-180"}`} 
                fill="none" 
                stroke="currentColor" 
                viewBox="0 0 24 24"
              >
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 10l7-7m0 0l7 7m-7-7v18" />
              </svg>
              <span>{trend.isPositive ? "+" : ""}{trend.value}%</span>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

