// ============================================
// CAREGIVER DISTRIBUTION (Donut Chart)
// ============================================

interface CaregiverDistributionProps {
  data: {
    type: string;
    count: number;
    color: string;
  }[];
}

export function CaregiverDistribution({ data }: CaregiverDistributionProps) {
  const total = data.reduce((sum, item) => sum + item.count, 0);
  const radius = 70;
  const circumference = 2 * Math.PI * radius;

  let currentOffset = 0;
  const segments = data.map(item => {
    const percentage = total > 0 ? item.count / total : 0;
    const dashArray = percentage * circumference;
    const dashOffset = -currentOffset;
    currentOffset += dashArray;
    return {
      ...item,
      percentage: Math.round(percentage * 100),
      dashArray: `${dashArray} ${circumference}`,
      dashOffset,
    };
  });

  return (
    <div className="flex items-center gap-8">
      {/* Donut Chart */}
      <div className="relative w-44 h-44">
        <svg width="176" height="176" className="-rotate-90">
          <circle
            cx="88"
            cy="88"
            r={radius}
            fill="none"
            stroke="#F3F4F6"
            strokeWidth="20"
          />
          {segments.map((segment, index) => (
            <circle
              key={index}
              cx="88"
              cy="88"
              r={radius}
              fill="none"
              stroke={segment.color}
              strokeWidth="20"
              strokeDasharray={segment.dashArray}
              strokeDashoffset={segment.dashOffset}
              strokeLinecap="round"
              className="transition-all duration-700 ease-out"
            />
          ))}
        </svg>
      </div>

      {/* Legend */}
      <div className="space-y-3">
        {segments.map((segment, index) => (
          <div key={index} className="flex items-center gap-3">
            <div 
              className="w-3 h-3 rounded-full"
              style={{ backgroundColor: segment.color }}
            />
            <div className="flex items-center gap-3">
              <span className="text-sm text-gray-600 min-w-[80px]">{segment.type}</span>
              <span className="text-sm font-semibold text-gray-900">{segment.percentage}%</span>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

