// ============================================
// MESSAGE SENT ANIMATION
// Premium feedback animation when message is sent
// ============================================

"use client";

import { useEffect, useState } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { Check, CheckCheck, Send, Sparkles } from "lucide-react";

interface MessageSentAnimationProps {
  show: boolean;
  status: "sending" | "sent" | "delivered" | "read" | "error";
  onComplete?: () => void;
}

export function MessageSentAnimation({
  show,
  status,
  onComplete,
}: MessageSentAnimationProps) {
  const [phase, setPhase] = useState<"initial" | "flying" | "landing" | "complete">("initial");

  useEffect(() => {
    if (!show) {
      setPhase("initial");
      return;
    }

    // Animate through phases
    setPhase("flying");

    const flyTimer = setTimeout(() => {
      setPhase("landing");
    }, 300);

    const landTimer = setTimeout(() => {
      setPhase("complete");
      onComplete?.();
    }, 600);

    return () => {
      clearTimeout(flyTimer);
      clearTimeout(landTimer);
    };
  }, [show, onComplete]);

  const getStatusIcon = () => {
    switch (status) {
      case "sending":
        return <Send className="w-4 h-4" />;
      case "sent":
        return <Check className="w-4 h-4" />;
      case "delivered":
        return <CheckCheck className="w-4 h-4" />;
      case "read":
        return <CheckCheck className="w-4 h-4 text-blue-500" />;
      default:
        return <Check className="w-4 h-4" />;
    }
  };

  return (
    <AnimatePresence>
      {show && phase !== "complete" && (
        <motion.div
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          exit={{ opacity: 0 }}
          className="fixed inset-0 pointer-events-none z-50 flex items-center justify-center"
        >
          {/* Flying message icon */}
          <motion.div
            initial={{ scale: 0.5, x: 0, y: 100, opacity: 0 }}
            animate={{
              scale: phase === "flying" ? 1 : 0.8,
              x: phase === "landing" ? 50 : 0,
              y: phase === "flying" ? -50 : phase === "landing" ? -100 : 100,
              opacity: 1,
            }}
            transition={{
              type: "spring",
              stiffness: 300,
              damping: 20,
            }}
            className="relative"
          >
            {/* Main icon */}
            <motion.div
              animate={{
                rotate: phase === "flying" ? [0, -10, 10, 0] : 0,
              }}
              transition={{ duration: 0.3, repeat: phase === "flying" ? 1 : 0 }}
              className="w-12 h-12 bg-linear-to-br from-[#39B54A] to-[#2d913c] rounded-full flex items-center justify-center text-white shadow-lg shadow-[#39B54A]/30"
            >
              {getStatusIcon()}
            </motion.div>

            {/* Sparkle effects */}
            {phase === "landing" && (
              <>
                <motion.div
                  initial={{ scale: 0, opacity: 0 }}
                  animate={{ scale: 1.5, opacity: [0, 1, 0] }}
                  transition={{ duration: 0.4 }}
                  className="absolute -top-2 -right-2"
                >
                  <Sparkles className="w-4 h-4 text-yellow-400" />
                </motion.div>
                <motion.div
                  initial={{ scale: 0, opacity: 0 }}
                  animate={{ scale: 1.5, opacity: [0, 1, 0] }}
                  transition={{ duration: 0.4, delay: 0.1 }}
                  className="absolute -bottom-1 -left-2"
                >
                  <Sparkles className="w-3 h-3 text-yellow-400" />
                </motion.div>
              </>
            )}
          </motion.div>
        </motion.div>
      )}
    </AnimatePresence>
  );
}

// ============================================
// MESSAGE STATUS INDICATOR
// Animated status changes for messages
// ============================================

interface MessageStatusIndicatorProps {
  status: "sending" | "sent" | "delivered" | "read" | "error";
  animate?: boolean;
}

export function MessageStatusIndicator({
  status,
  animate = true,
}: MessageStatusIndicatorProps) {
  const variants = {
    initial: { scale: 0.5, opacity: 0 },
    animate: { scale: 1, opacity: 1 },
    exit: { scale: 0.5, opacity: 0 },
  };

  const transition = {
    type: "spring" as const,
    stiffness: 500,
    damping: 25,
  };

  return (
    <AnimatePresence mode="wait">
      <motion.span
        key={status}
        {...(animate ? { variants } : {})}
        initial={animate ? "initial" : false}
        animate="animate"
        {...(animate ? { exit: "exit" as const } : {})}
        transition={transition}
        className="inline-flex items-center"
      >
        {status === "sending" && (
          <motion.div
            animate={{ rotate: 360 }}
            transition={{ duration: 1, repeat: Infinity, ease: "linear" }}
            className="w-3.5 h-3.5 border-2 border-gray-300 border-t-[#39B54A] rounded-full"
          />
        )}
        {status === "sent" && (
          <Check className="w-3.5 h-3.5 text-gray-400" />
        )}
        {status === "delivered" && (
          <CheckCheck className="w-3.5 h-3.5 text-gray-400" />
        )}
        {status === "read" && (
          <CheckCheck className="w-3.5 h-3.5 text-blue-500" />
        )}
        {status === "error" && (
          <motion.span
            animate={{ scale: [1, 1.2, 1] }}
            transition={{ duration: 0.5, repeat: 2 }}
            className="w-3.5 h-3.5 bg-red-500 rounded-full flex items-center justify-center text-white text-[8px] font-bold"
          >
            !
          </motion.span>
        )}
      </motion.span>
    </AnimatePresence>
  );
}

// ============================================
// SENDING INDICATOR
// Shows while message is being sent
// ============================================

export function SendingIndicator() {
  return (
    <motion.div
      initial={{ opacity: 0, y: 10 }}
      animate={{ opacity: 1, y: 0 }}
      exit={{ opacity: 0, y: -10 }}
      className="flex items-center gap-2 text-sm text-gray-500"
    >
      <motion.div
        animate={{ rotate: 360 }}
        transition={{ duration: 1, repeat: Infinity, ease: "linear" }}
        className="w-4 h-4 border-2 border-gray-200 border-t-[#39B54A] rounded-full"
      />
      <span>Sending...</span>
    </motion.div>
  );
}

export default MessageSentAnimation;

// ============================================
// PREMIUM CALL OVERLAY
// FaceTime/WhatsApp-style call UI
// ============================================

"use client";

import React, { useState, memo } from "react";
import { motion, AnimatePresence } from "framer-motion";
import {
  Phone,
  PhoneOff,
  Video,
  VideoOff,
  Mic,
  MicOff,
  Volume2,
  VolumeX,
  RotateCcw,
  Maximize2,
  Minimize2,
} from "lucide-react";

// ============================================
// TYPES
// ============================================

interface PremiumCallOverlayProps {
  isOpen: boolean;
  callType: "audio" | "video";
  callState: "ringing" | "connecting" | "connected" | "ended";
  remoteName: string;
  remoteAvatar?: string;
  duration?: number;
  isRemoteMuted?: boolean;
  isRemoteVideoOff?: boolean;
  onAnswer?: () => void;
  onDecline?: () => void;
  onEnd?: () => void;
  onToggleMute?: () => void;
  onToggleVideo?: () => void;
  onToggleSpeaker?: () => void;
  onFlipCamera?: () => void;
  onMinimize?: () => void;
  onMaximize?: () => void;
  children?: React.ReactNode;
}

// ============================================
// ANIMATION VARIANTS
// ============================================

const overlayVariants = {
  hidden: { opacity: 0 },
  visible: {
    opacity: 1,
    transition: { duration: 0.3 },
  },
  exit: {
    opacity: 0,
    transition: { duration: 0.2 },
  },
};

const contentVariants = {
  hidden: { opacity: 0, scale: 0.9, y: 20 },
  visible: {
    opacity: 1,
    scale: 1,
    y: 0,
    transition: {
      type: "spring",
      stiffness: 400,
      damping: 30,
    },
  },
  exit: {
    opacity: 0,
    scale: 0.9,
    y: 20,
    transition: { duration: 0.2 },
  },
};

const pulseVariants = {
  pulse: {
    scale: [1, 1.1, 1],
    opacity: [0.7, 0.4, 0.7],
    transition: {
      duration: 2,
      repeat: Infinity,
      ease: "easeInOut",
    },
  },
};

const buttonVariants = {
  idle: { scale: 1 },
  hover: { scale: 1.1 },
  tap: { scale: 0.95 },
};

// ============================================
// HELPER FUNCTIONS
// ============================================

const formatDuration = (seconds: number): string => {
  const mins = Math.floor(seconds / 60);
  const secs = seconds % 60;
  return `${mins.toString().padStart(2, "0")}:${secs.toString().padStart(2, "0")}`;
};

// ============================================
// MAIN COMPONENT
// ============================================

export const PremiumCallOverlay = memo<PremiumCallOverlayProps>(({
  isOpen,
  callType,
  callState,
  remoteName,
  remoteAvatar,
  duration = 0,
  isRemoteMuted = false,
  isRemoteVideoOff = false,
  onAnswer,
  onDecline,
  onEnd,
  onToggleMute,
  onToggleVideo,
  onToggleSpeaker,
  onFlipCamera,
  onMinimize,
  onMaximize,
  children,
}) => {
  const [isMuted, setIsMuted] = useState(false);
  const [isVideoOff, setIsVideoOff] = useState(callType === "audio");
  const [isSpeakerOn, setIsSpeakerOn] = useState(false);
  const [isMinimized, setIsMinimized] = useState(false);

  const handleToggleMute = () => {
    setIsMuted(!isMuted);
    onToggleMute?.();
  };

  const handleToggleVideo = () => {
    setIsVideoOff(!isVideoOff);
    onToggleVideo?.();
  };

  const handleToggleSpeaker = () => {
    setIsSpeakerOn(!isSpeakerOn);
    onToggleSpeaker?.();
  };

  const handleMinimize = () => {
    setIsMinimized(true);
    onMinimize?.();
  };

  const handleMaximize = () => {
    setIsMinimized(false);
    onMaximize?.();
  };

  const getStateText = () => {
    switch (callState) {
      case "ringing":
        return callType === "video" ? "Incoming Video Call..." : "Incoming Call...";
      case "connecting":
        return "Connecting...";
      case "connected":
        return formatDuration(duration);
      case "ended":
        return "Call Ended";
      default:
        return "";
    }
  };

  // Minimized view
  if (isMinimized) {
    return (
      <AnimatePresence>
        {isOpen && (
          <motion.div
            initial={{ opacity: 0, scale: 0.8, x: 100 }}
            animate={{ opacity: 1, scale: 1, x: 0 }}
            exit={{ opacity: 0, scale: 0.8, x: 100 }}
            drag
            dragConstraints={{ left: 0, right: 0, top: 0, bottom: 0 }}
            className="fixed bottom-24 right-4 z-50 w-36 h-48 bg-gray-900 rounded-2xl shadow-2xl overflow-hidden cursor-move"
            onClick={handleMaximize}
          >
            {/* Video/Avatar */}
            {children || (
              <div className="absolute inset-0 flex items-center justify-center bg-linear-to-br from-[#39B54A] to-[#2d913c]">
                {remoteAvatar ? (
                  <img src={remoteAvatar} alt={remoteName} className="w-16 h-16 rounded-full" />
                ) : (
                  <div className="w-16 h-16 rounded-full bg-white/20 flex items-center justify-center text-white text-2xl font-bold">
                    {remoteName[0]}
                  </div>
                )}
              </div>
            )}

            {/* Duration */}
            <div className="absolute bottom-2 left-0 right-0 text-center">
              <span className="text-xs text-white bg-black/50 px-2 py-1 rounded-full">
                {formatDuration(duration)}
              </span>
            </div>

            {/* Expand button */}
            <motion.button
              whileHover={{ scale: 1.1 }}
              whileTap={{ scale: 0.95 }}
              className="absolute top-2 right-2 p-1.5 bg-black/30 rounded-full text-white hover:bg-black/50 transition-colors"
              onClick={(e) => {
                e.stopPropagation();
                handleMaximize();
              }}
              aria-label="Maximize call"
            >
              <Maximize2 className="w-4 h-4" />
            </motion.button>
          </motion.div>
        )}
      </AnimatePresence>
    );
  }

  return (
    <AnimatePresence>
      {isOpen && (
        <motion.div
          variants={overlayVariants}
          initial="hidden"
          animate="visible"
          exit="exit"
          className="fixed inset-0 z-50 bg-black/95 flex flex-col"
        >
          {/* Header */}
          <div className="flex items-center justify-between px-6 py-4">
            <motion.button
              variants={buttonVariants}
              initial="idle"
              whileHover="hover"
              whileTap="tap"
              onClick={handleMinimize}
              className="p-2 text-white/80 hover:text-white hover:bg-white/10 rounded-xl transition-colors"
              aria-label="Minimize call"
            >
              <Minimize2 className="w-5 h-5" />
            </motion.button>

            <div className="text-center">
              <p className="text-white/60 text-sm">
                {callType === "video" ? "Video Call" : "Voice Call"}
              </p>
            </div>

            <motion.button
              variants={buttonVariants}
              initial="idle"
              whileHover="hover"
              whileTap="tap"
              onClick={onFlipCamera}
              className="p-2 text-white/80 hover:text-white hover:bg-white/10 rounded-xl transition-colors"
              aria-label="Flip camera"
            >
              <RotateCcw className="w-5 h-5" />
            </motion.button>
          </div>

          {/* Main Content */}
          <motion.div
            variants={contentVariants}
            className="flex-1 flex flex-col items-center justify-center"
          >
            {/* Video placeholder or Avatar */}
            <div className="relative mb-8">
              {/* Pulsing ring for ringing state */}
              {callState === "ringing" && (
                <>
                  <motion.div
                    variants={pulseVariants}
                    animate="pulse"
                    className="absolute inset-0 w-40 h-40 rounded-full bg-[#39B54A]/30"
                    style={{ transform: "translate(-20%, -20%)" }}
                  />
                  <motion.div
                    variants={pulseVariants}
                    animate="pulse"
                    className="absolute inset-0 w-44 h-44 rounded-full bg-[#39B54A]/20"
                    style={{ transform: "translate(-27%, -27%)", animationDelay: "0.5s" }}
                  />
                </>
              )}

              {/* Avatar */}
              {(callState !== "connected" || isRemoteVideoOff || callType === "audio") && (
                <div className="relative z-10">
                  {remoteAvatar ? (
                    <img
                      src={remoteAvatar}
                      alt={remoteName}
                      className="w-32 h-32 rounded-full ring-4 ring-white/20 shadow-2xl"
                    />
                  ) : (
                    <div className="w-32 h-32 rounded-full bg-linear-to-br from-[#39B54A] to-[#2d913c] flex items-center justify-center ring-4 ring-white/20 shadow-2xl">
                      <span className="text-5xl font-bold text-white">
                        {remoteName[0]}
                      </span>
                    </div>
                  )}
                </div>
              )}

              {/* Remote muted indicator */}
              {isRemoteMuted && callState === "connected" && (
                <motion.div
                  initial={{ scale: 0 }}
                  animate={{ scale: 1 }}
                  className="absolute -bottom-2 left-1/2 -translate-x-1/2 px-3 py-1 bg-red-500/80 rounded-full flex items-center gap-1.5"
                >
                  <MicOff className="w-3.5 h-3.5 text-white" />
                  <span className="text-xs text-white font-medium">Muted</span>
                </motion.div>
              )}
            </div>

            {/* Name and Status */}
            <h2 className="text-3xl font-bold text-white mb-2">{remoteName}</h2>
            <motion.p
              key={callState}
              initial={{ opacity: 0, y: 5 }}
              animate={{ opacity: 1, y: 0 }}
              className="text-white/60 text-lg"
            >
              {getStateText()}
            </motion.p>
          </motion.div>

          {/* Video Content Slot */}
          {callType === "video" && callState === "connected" && children && (
            <div className="absolute inset-0 z-0">{children}</div>
          )}

          {/* Controls */}
          <div className="px-6 pb-12">
            {callState === "ringing" ? (
              // Incoming call controls
              <div className="flex items-center justify-center gap-16">
                <motion.button
                  variants={buttonVariants}
                  initial="idle"
                  whileHover="hover"
                  whileTap="tap"
                  onClick={onDecline}
                  className="w-16 h-16 bg-red-500 rounded-full flex items-center justify-center shadow-lg shadow-red-500/30"
                  aria-label="Decline call"
                >
                  <PhoneOff className="w-7 h-7 text-white" />
                </motion.button>
                <motion.button
                  variants={buttonVariants}
                  initial="idle"
                  whileHover="hover"
                  whileTap="tap"
                  onClick={onAnswer}
                  className="w-16 h-16 bg-green-500 rounded-full flex items-center justify-center shadow-lg shadow-green-500/30"
                  aria-label="Answer call"
                >
                  {callType === "video" ? (
                    <Video className="w-7 h-7 text-white" />
                  ) : (
                    <Phone className="w-7 h-7 text-white" />
                  )}
                </motion.button>
              </div>
            ) : (
              // Active call controls
              <div className="flex items-center justify-center gap-4">
                {/* Mute */}
                <motion.button
                  variants={buttonVariants}
                  initial="idle"
                  whileHover="hover"
                  whileTap="tap"
                  onClick={handleToggleMute}
                  className={`w-14 h-14 rounded-full flex items-center justify-center transition-colors ${
                    isMuted
                      ? "bg-white text-gray-900"
                      : "bg-white/10 text-white hover:bg-white/20"
                  }`}
                  aria-label={isMuted ? "Unmute" : "Mute"}
                  aria-pressed={isMuted}
                >
                  {isMuted ? (
                    <MicOff className="w-6 h-6" />
                  ) : (
                    <Mic className="w-6 h-6" />
                  )}
                </motion.button>

                {/* Video toggle (video calls only) */}
                {callType === "video" && (
                  <motion.button
                    variants={buttonVariants}
                    initial="idle"
                    whileHover="hover"
                    whileTap="tap"
                    onClick={handleToggleVideo}
                    className={`w-14 h-14 rounded-full flex items-center justify-center transition-colors ${
                      isVideoOff
                        ? "bg-white text-gray-900"
                        : "bg-white/10 text-white hover:bg-white/20"
                    }`}
                    aria-label={isVideoOff ? "Turn on camera" : "Turn off camera"}
                    aria-pressed={isVideoOff}
                  >
                    {isVideoOff ? (
                      <VideoOff className="w-6 h-6" />
                    ) : (
                      <Video className="w-6 h-6" />
                    )}
                  </motion.button>
                )}

                {/* End call */}
                <motion.button
                  variants={buttonVariants}
                  initial="idle"
                  whileHover="hover"
                  whileTap="tap"
                  onClick={onEnd}
                  className="w-16 h-16 bg-red-500 rounded-full flex items-center justify-center shadow-lg shadow-red-500/30 mx-4"
                  aria-label="End call"
                >
                  <PhoneOff className="w-7 h-7 text-white" />
                </motion.button>

                {/* Speaker */}
                <motion.button
                  variants={buttonVariants}
                  initial="idle"
                  whileHover="hover"
                  whileTap="tap"
                  onClick={handleToggleSpeaker}
                  className={`w-14 h-14 rounded-full flex items-center justify-center transition-colors ${
                    isSpeakerOn
                      ? "bg-white text-gray-900"
                      : "bg-white/10 text-white hover:bg-white/20"
                  }`}
                  aria-label={isSpeakerOn ? "Turn off speaker" : "Turn on speaker"}
                  aria-pressed={isSpeakerOn}
                >
                  {isSpeakerOn ? (
                    <Volume2 className="w-6 h-6" />
                  ) : (
                    <VolumeX className="w-6 h-6" />
                  )}
                </motion.button>

                {/* Flip camera (video calls only) */}
                {callType === "video" && (
                  <motion.button
                    variants={buttonVariants}
                    initial="idle"
                    whileHover="hover"
                    whileTap="tap"
                    onClick={onFlipCamera}
                    className="w-14 h-14 bg-white/10 text-white hover:bg-white/20 rounded-full flex items-center justify-center transition-colors"
                    aria-label="Flip camera"
                  >
                    <RotateCcw className="w-6 h-6" />
                  </motion.button>
                )}
              </div>
            )}
          </div>
        </motion.div>
      )}
    </AnimatePresence>
  );
});

PremiumCallOverlay.displayName = "PremiumCallOverlay";

export default PremiumCallOverlay;

// ============================================
// PREMIUM CHAT HEADER
// Instagram/WhatsApp-style header with call buttons
// ============================================

"use client";

import { useState, memo } from "react";
import Image from "next/image";
import { motion, AnimatePresence } from "framer-motion";
import {
  ArrowLeft,
  Phone,
  Video,
  MoreVertical,
  Search,
  Bell,
  BellOff,
  Archive,
  Download,
  Flag,
  Info,
  X,
  UserX,
  UserCheck,
} from "lucide-react";
import { PremiumOnlineStatus } from "./PremiumOnlineStatus";
import type { Conversation, Participant } from "@/features/chat/services";

// ============================================
// TYPES
// ============================================

interface PremiumChatHeaderProps {
  conversation: Conversation;
  otherParticipant: Participant | null;
  isOnline?: boolean;
  isMuted?: boolean;
  isBlocked?: boolean;
  isTyping?: boolean;
  onBack?: () => void;
  onVoiceCall?: () => void;
  onVideoCall?: () => void;
  onSearch?: () => void;
  onToggleMute?: () => void;
  onBlock?: () => void;
  onUnblock?: () => void;
  onArchive?: () => void;
  onExport?: () => void;
  onReport?: () => void;
  onViewProfile?: () => void;
  showBackButton?: boolean;
  callingEnabled?: boolean;
}

// ============================================
// ANIMATION VARIANTS
// ============================================

const menuVariants = {
  hidden: { opacity: 0, scale: 0.95, y: -5 },
  visible: {
    opacity: 1,
    scale: 1,
    y: 0,
    transition: { type: "spring", stiffness: 500, damping: 30 },
  },
};

const callButtonVariants = {
  idle: { scale: 1 },
  hover: {
    scale: 1.1,
    transition: { type: "spring", stiffness: 400, damping: 10 },
  },
  tap: { scale: 0.95 },
};

// ============================================
// MAIN COMPONENT
// ============================================

export const PremiumChatHeader = memo<PremiumChatHeaderProps>(({
  conversation: _conversation,
  otherParticipant,
  isOnline = false,
  isMuted = false,
  isBlocked = false,
  isTyping = false,
  onBack,
  onVoiceCall,
  onVideoCall,
  onSearch,
  onToggleMute,
  onBlock,
  onUnblock,
  onArchive,
  onExport,
  onReport,
  onViewProfile,
  showBackButton = true,
  callingEnabled = true,
}) => {
  const [showMenu, setShowMenu] = useState(false);
  const [showSearchBar, setShowSearchBar] = useState(false);

  const handleMenuAction = (action: () => void) => {
    action();
    setShowMenu(false);
  };

  return (
    <motion.header
      initial={{ y: -20, opacity: 0 }}
      animate={{ y: 0, opacity: 1 }}
      className="relative flex items-center justify-between px-4 py-3 bg-white/95 dark:bg-gray-900/95 backdrop-blur-xl border-b border-gray-200/60 dark:border-gray-800/60 z-20"
    >
      {/* Left Section - Back button + User info */}
      <div className="flex items-center gap-3 flex-1 min-w-0">
        {/* Back Button */}
        {showBackButton && (
          <motion.button
            whileHover={{ scale: 1.05 }}
            whileTap={{ scale: 0.95 }}
            onClick={onBack}
            className="p-2 -ml-2 text-gray-600 dark:text-gray-400 hover:text-[#39B54A] hover:bg-[#39B54A]/5 rounded-xl transition-colors"
            aria-label="Go back"
          >
            <ArrowLeft className="w-5 h-5" />
          </motion.button>
        )}

        {/* User Avatar + Info */}
        <button
          onClick={onViewProfile}
          className="flex items-center gap-3 flex-1 min-w-0 hover:bg-gray-50 dark:hover:bg-gray-800 rounded-xl p-1.5 -m-1.5 transition-colors"
          aria-label={`View ${otherParticipant?.fullName || "user"}'s profile`}
        >
          {/* Avatar with online indicator */}
          <div className="relative shrink-0">
            {otherParticipant?.avatar ? (
              <Image
                src={otherParticipant.avatar}
                alt={otherParticipant.fullName}
                width={44}
                height={44}
                className="rounded-full ring-2 ring-white dark:ring-gray-800 shadow-sm"
              />
            ) : (
              <div className="w-11 h-11 rounded-full bg-linear-to-br from-[#39B54A] to-[#2d913c] flex items-center justify-center text-white font-semibold shadow-sm">
                {otherParticipant?.fullName?.[0] || "?"}
              </div>
            )}
            <PremiumOnlineStatus isOnline={isOnline} size="md" />
          </div>

          {/* User Info */}
          <div className="flex-1 min-w-0 text-left">
            <div className="flex items-center gap-2">
              <h2 className="font-semibold text-gray-900 dark:text-white truncate">
                {otherParticipant?.fullName || "Unknown User"}
              </h2>
              {isMuted && (
                <motion.span
                  initial={{ scale: 0 }}
                  animate={{ scale: 1 }}
                  className="p-1 bg-gray-100 dark:bg-gray-800 rounded-full"
                >
                  <BellOff className="w-3 h-3 text-gray-400" />
                </motion.span>
              )}
              {isBlocked && (
                <motion.span
                  initial={{ scale: 0 }}
                  animate={{ scale: 1 }}
                  className="px-2 py-0.5 bg-red-100 dark:bg-red-900/30 text-red-600 dark:text-red-400 text-xs font-medium rounded-full"
                >
                  Blocked
                </motion.span>
              )}
            </div>
            <AnimatePresence mode="wait">
              {isTyping ? (
                <motion.p
                  key="typing"
                  initial={{ opacity: 0, y: -5 }}
                  animate={{ opacity: 1, y: 0 }}
                  exit={{ opacity: 0, y: 5 }}
                  className="text-xs text-[#39B54A] font-medium"
                >
                  typing...
                </motion.p>
              ) : (
                <motion.p
                  key="status"
                  initial={{ opacity: 0, y: 5 }}
                  animate={{ opacity: 1, y: 0 }}
                  exit={{ opacity: 0, y: -5 }}
                  className={`text-xs capitalize ${
                    isOnline
                      ? "text-[#39B54A] font-medium"
                      : "text-gray-500 dark:text-gray-400"
                  }`}
                >
                  {isOnline ? "Online" : otherParticipant?.role || "Offline"}
                </motion.p>
              )}
            </AnimatePresence>
          </div>
        </button>
      </div>

      {/* Right Section - Action buttons */}
      <div className="flex items-center gap-1">
        {/* Call Buttons (only if not blocked and calling enabled) */}
        {!isBlocked && callingEnabled && (
          <>
            <motion.button
              variants={callButtonVariants}
              initial="idle"
              whileHover="hover"
              whileTap="tap"
              onClick={onVoiceCall}
              className="p-2.5 text-gray-600 dark:text-gray-400 hover:text-[#39B54A] hover:bg-[#39B54A]/10 rounded-xl transition-colors"
              aria-label="Start voice call"
            >
              <Phone className="w-5 h-5" />
            </motion.button>
            <motion.button
              variants={callButtonVariants}
              initial="idle"
              whileHover="hover"
              whileTap="tap"
              onClick={onVideoCall}
              className="p-2.5 text-gray-600 dark:text-gray-400 hover:text-[#39B54A] hover:bg-[#39B54A]/10 rounded-xl transition-colors"
              aria-label="Start video call"
            >
              <Video className="w-5 h-5" />
            </motion.button>
          </>
        )}

        {/* Search Button */}
        <motion.button
          whileHover={{ scale: 1.05 }}
          whileTap={{ scale: 0.95 }}
          onClick={() => setShowSearchBar(!showSearchBar)}
          className={`p-2.5 rounded-xl transition-colors ${
            showSearchBar
              ? "text-[#39B54A] bg-[#39B54A]/10"
              : "text-gray-600 dark:text-gray-400 hover:text-[#39B54A] hover:bg-[#39B54A]/5"
          }`}
          aria-label="Search messages"
          aria-expanded={showSearchBar}
        >
          {showSearchBar ? (
            <X className="w-5 h-5" />
          ) : (
            <Search className="w-5 h-5" />
          )}
        </motion.button>

        {/* More Options */}
        <div className="relative">
          <motion.button
            whileHover={{ scale: 1.05 }}
            whileTap={{ scale: 0.95 }}
            onClick={() => setShowMenu(!showMenu)}
            className={`p-2.5 rounded-xl transition-colors ${
              showMenu
                ? "text-[#39B54A] bg-[#39B54A]/10"
                : "text-gray-600 dark:text-gray-400 hover:text-[#39B54A] hover:bg-[#39B54A]/5"
            }`}
            aria-label="More options"
            aria-expanded={showMenu}
            aria-haspopup="menu"
          >
            <MoreVertical className="w-5 h-5" />
          </motion.button>

          {/* Dropdown Menu */}
          <AnimatePresence>
            {showMenu && (
              <>
                <motion.div
                  initial={{ opacity: 0 }}
                  animate={{ opacity: 1 }}
                  exit={{ opacity: 0 }}
                  className="fixed inset-0 z-30"
                  onClick={() => setShowMenu(false)}
                />
                <motion.div
                  variants={menuVariants}
                  initial="hidden"
                  animate="visible"
                  exit="hidden"
                  className="absolute right-0 top-full mt-2 w-56 bg-white dark:bg-gray-800 rounded-xl shadow-xl border border-gray-200 dark:border-gray-700 overflow-hidden z-40"
                  role="menu"
                >
                  {/* View Profile */}
                  <button
                    onClick={() => handleMenuAction(onViewProfile || (() => {}))}
                    className="flex items-center gap-3 w-full px-4 py-3 text-sm text-gray-700 dark:text-gray-300 hover:bg-gray-50 dark:hover:bg-gray-700/50 transition-colors"
                    role="menuitem"
                  >
                    <Info className="w-4 h-4" />
                    View Profile
                  </button>

                  {/* Search Messages */}
                  <button
                    onClick={() => {
                      setShowSearchBar(true);
                      setShowMenu(false);
                      onSearch?.();
                    }}
