﻿// ============================================
// VIDEO CALL MODAL
// Full-screen modal for active video/audio calls
// ============================================

"use client";

import { useEffect, useState, useCallback } from "react";
import { motion, AnimatePresence } from "framer-motion";
import {
  PhoneOff,
  Video,
  VideoOff,
  Mic,
  MicOff,
  X,
  Maximize2,
  Minimize2,
  Users,
} from "lucide-react";
import {
  useCall,
  useCallStateHooks,
  CallingState,
  StreamCall,
  SpeakerLayout,
  CallParticipantsList,
  useStreamVideoClient,
} from "@stream-io/video-react-sdk";
import "@stream-io/video-react-sdk/dist/css/styles.css";

interface VideoCallModalProps {
  isOpen: boolean;
  onClose: () => void;
  callId: string;
  callType?: "audio" | "video";
  participantName?: string;
  participantAvatar?: string;
}

// Inner component that uses the call hooks
function CallContent({
  onClose,
  callType,
  participantName,
}: {
  onClose: () => void;
  callType?: "audio" | "video";
  participantName?: string;
}) {
  const call = useCall();
  const { useCallCallingState, useParticipantCount } =
    useCallStateHooks();
  const callingState = useCallCallingState();
  const participantCount = useParticipantCount();

  const [isMicOn, setIsMicOn] = useState(true);
  const [isCameraOn, setIsCameraOn] = useState(callType === "video");
  const [isFullscreen, setIsFullscreen] = useState(false);
  const [showParticipants, setShowParticipants] = useState(false);

  // Join call on mount
  useEffect(() => {
    if (call && callingState === CallingState.IDLE) {
      call.join({ create: true }).catch(console.error);
    }
  }, [call, callingState]);

  // Toggle mic
  const handleToggleMic = useCallback(async () => {
    if (!call) return;
    try {
      await call.microphone.toggle();
      setIsMicOn(!isMicOn);
    } catch (error) {
      console.error("Failed to toggle mic:", error);
    }
  }, [call, isMicOn]);

  // Toggle camera
  const handleToggleCamera = useCallback(async () => {
    if (!call) return;
    try {
      await call.camera.toggle();
      setIsCameraOn(!isCameraOn);
    } catch (error) {
      console.error("Failed to toggle camera:", error);
    }
  }, [call, isCameraOn]);

  // End call
  const handleEndCall = useCallback(async () => {
    if (!call) return;
    try {
      await call.leave();
      onClose();
    } catch (error) {
      console.error("Failed to leave call:", error);
      onClose();
    }
  }, [call, onClose]);

  // Toggle fullscreen
  const handleToggleFullscreen = useCallback(() => {
    if (!document.fullscreenElement) {
      document.documentElement.requestFullscreen();
      setIsFullscreen(true);
    } else {
      document.exitFullscreen();
      setIsFullscreen(false);
    }
  }, []);

  // Render based on calling state
  if (callingState === CallingState.JOINING) {
    return (
      <div className="flex flex-col items-center justify-center h-full bg-gray-900">
        <div className="w-16 h-16 border-4 border-[#39B54A] border-t-transparent rounded-full animate-spin mb-4" />
        <p className="text-white text-lg">Connecting...</p>
        <p className="text-gray-400 text-sm mt-2">
          Calling {participantName || "participant"}
        </p>
      </div>
    );
  }

  if (callingState === CallingState.LEFT) {
    return (
      <div className="flex flex-col items-center justify-center h-full bg-gray-900">
        <PhoneOff className="w-16 h-16 text-red-500 mb-4" />
        <p className="text-white text-lg">Call ended</p>
        <button
          onClick={onClose}
          className="mt-6 px-6 py-3 bg-[#39B54A] text-white rounded-xl hover:bg-[#2d913c] transition-colors"
        >
          Close
        </button>
      </div>
    );
  }

  return (
    <div className="relative h-full bg-gray-900 flex flex-col">
      {/* Header */}
      <div className="absolute top-0 left-0 right-0 z-20 flex items-center justify-between p-4 bg-linear-to-b from-black/60 to-transparent">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 bg-[#39B54A] rounded-full flex items-center justify-center text-white font-bold">
            {participantName?.charAt(0) || "?"}
          </div>
          <div>
            <h3 className="text-white font-semibold">
              {participantName || "Participant"}
            </h3>
            <p className="text-gray-300 text-sm flex items-center gap-1">
              <Users className="w-3.5 h-3.5" />
              {participantCount} participant{participantCount !== 1 ? "s" : ""}
            </p>
          </div>
        </div>
        <div className="flex items-center gap-2">
          <button
            onClick={() => setShowParticipants(!showParticipants)}
            className={`p-2 rounded-lg transition-colors ${
              showParticipants
                ? "bg-[#39B54A] text-white"
                : "bg-white/10 text-white hover:bg-white/20"
            }`}
          >
            <Users className="w-5 h-5" />
          </button>
          <button
            onClick={handleToggleFullscreen}
            className="p-2 bg-white/10 text-white rounded-lg hover:bg-white/20 transition-colors"
          >
            {isFullscreen ? (
              <Minimize2 className="w-5 h-5" />
            ) : (
              <Maximize2 className="w-5 h-5" />
            )}
          </button>
          <button
            onClick={onClose}
            className="p-2 bg-white/10 text-white rounded-lg hover:bg-red-500 transition-colors"
          >
            <X className="w-5 h-5" />
          </button>
        </div>
      </div>

      {/* Main video area */}
      <div className="flex-1 relative">
        <SpeakerLayout />

        {/* Participants sidebar */}
        <AnimatePresence>
          {showParticipants && (
            <motion.div
              initial={{ x: "100%" }}
              animate={{ x: 0 }}
              exit={{ x: "100%" }}
              className="absolute top-16 right-0 bottom-24 w-72 bg-gray-800/90 backdrop-blur-sm border-l border-gray-700"
            >
              <div className="p-4">
                <h4 className="text-white font-semibold mb-4">Participants</h4>
                <CallParticipantsList onClose={() => setShowParticipants(false)} />
              </div>
            </motion.div>
          )}
        </AnimatePresence>
      </div>

      {/* Controls */}
      <div className="absolute bottom-0 left-0 right-0 z-20 p-6 bg-linear-to-t from-black/80 to-transparent">
        <div className="flex items-center justify-center gap-4">
          {/* Mic toggle */}
          <button
            onClick={handleToggleMic}
            className={`p-4 rounded-full transition-colors ${
              isMicOn
                ? "bg-white/10 text-white hover:bg-white/20"
                : "bg-red-500 text-white"
            }`}
            title={isMicOn ? "Mute" : "Unmute"}
          >
            {isMicOn ? (
              <Mic className="w-6 h-6" />
            ) : (
              <MicOff className="w-6 h-6" />
            )}
          </button>

          {/* Camera toggle (video calls only) */}
          {callType === "video" && (
            <button
              onClick={handleToggleCamera}
              className={`p-4 rounded-full transition-colors ${
                isCameraOn
                  ? "bg-white/10 text-white hover:bg-white/20"
                  : "bg-red-500 text-white"
              }`}
              title={isCameraOn ? "Turn off camera" : "Turn on camera"}
            >
              {isCameraOn ? (
                <Video className="w-6 h-6" />
              ) : (
                <VideoOff className="w-6 h-6" />
              )}
            </button>
          )}

          {/* End call */}
          <button
            onClick={handleEndCall}
            className="p-4 bg-red-500 text-white rounded-full hover:bg-red-600 transition-colors"
            title="End call"
          >
            <PhoneOff className="w-6 h-6" />
          </button>
        </div>
      </div>
    </div>
  );
}

export function VideoCallModal({
  isOpen,
  onClose,
  callId,
  callType = "video",
  participantName,
}: VideoCallModalProps) {
  const client = useStreamVideoClient();
  const [call, setCall] = useState<any>(null);

  // Create/get call when modal opens
  useEffect(() => {
    if (isOpen && client && callId) {
      const newCall = client.call("default", callId);
      setCall(newCall);
    }

    return () => {
      // Cleanup on close
      if (call) {
        call.leave().catch(console.error);
      }
    };
  }, [isOpen, client, callId]);

  if (!isOpen || !call) return null;

  return (
    <AnimatePresence>
      <motion.div
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        exit={{ opacity: 0 }}
        className="fixed inset-0 z-50 bg-black"
      >
        <StreamCall call={call}>
          <CallContent
            onClose={onClose}
            callType={callType}
            {...(participantName !== undefined ? { participantName } : {})}
          />
        </StreamCall>
      </motion.div>
    </AnimatePresence>
  );
}

export default VideoCallModal;

// ============================================
// VIDEO CALL PROVIDER
// Context provider for Stream.io video calls
// ============================================

"use client";

import {
  createContext,
  useContext,
  useState,
  useCallback,
  useEffect,
  ReactNode,
} from "react";
import { StreamVideo, StreamVideoClient, User as StreamUser } from "@stream-io/video-react-sdk";
import { videoService, STREAM_CONFIG } from "@/services/api/video.service";
import { useAuthContext } from "@/context/AuthContext";

interface VideoCallState {
  isInitialized: boolean;
  isInCall: boolean;
  callId: string | null;
  callType: "audio" | "video" | null;
  conversationId: string | null;
  error: string | null;
}

interface VideoCallContextType {
  client: StreamVideoClient | null;
  state: VideoCallState;
  initializeClient: () => Promise<void>;
  startCall: (conversationId: string, callType?: "audio" | "video") => Promise<string | null>;
  joinCall: (callId: string) => Promise<void>;
  endCall: () => void;
  isReady: boolean;
}

const VideoCallContext = createContext<VideoCallContextType | undefined>(undefined);

export function VideoCallProvider({ children }: { children: ReactNode }) {
  const { user, isAuthenticated } = useAuthContext();
  const [client, setClient] = useState<StreamVideoClient | null>(null);
  const [state, setState] = useState<VideoCallState>({
    isInitialized: false,
    isInCall: false,
    callId: null,
    callType: null,
    conversationId: null,
    error: null,
  });

  // Check if Stream.io is configured
  const isStreamConfigured = Boolean(STREAM_CONFIG.apiKey);

  // Initialize Stream Video client
  const initializeClient = useCallback(async () => {
    if (!isAuthenticated || !user || client) return;

    if (!isStreamConfigured) {
      console.warn("Stream.io is not configured. Video/audio calls will not work.");
      setState(prev => ({
        ...prev,
        error: "Video calls not configured. Please set NEXT_PUBLIC_STREAM_API_KEY in environment variables.",
      }));
      return;
    }

    try {
      // Get token from backend
      const response = await videoService.getUserToken();

      if (!response.success || !response.data) {
        throw new Error("Failed to get video token");
      }

      const { token, apiKey, userId, clientSideAuth } = response.data;
      const resolvedApiKey = apiKey ?? STREAM_CONFIG.apiKey;

      if (!resolvedApiKey) {
        throw new Error("Missing Stream API key");
      }

      // Create Stream user
      const streamUser: StreamUser = {
        id: userId,
        name: user.fullName || "User",
        ...(user.avatar ? { image: user.avatar } : {}),
      };

      // Create client
      let videoClient: StreamVideoClient;

      if (clientSideAuth || !token) {
        // Client-side token generation (development mode)
        videoClient = new StreamVideoClient({
          apiKey: resolvedApiKey,
          user: streamUser,
          tokenProvider: async () => {
            // In production, this should call backend to refresh token
            const refreshResponse = await videoService.getUserToken();
            return refreshResponse.data?.token || "";
          },
        });
      } else {
        // Server-provided token
        videoClient = new StreamVideoClient({
          apiKey: resolvedApiKey,
          user: streamUser,
          token,
        });
      }

      setClient(videoClient);
      setState(prev => ({ ...prev, isInitialized: true, error: null }));
    } catch (error) {
      console.error("Failed to initialize video client:", error);
      setState(prev => ({
        ...prev,
        error: error instanceof Error ? error.message : "Failed to initialize video",
      }));
    }
  }, [isAuthenticated, user, client]);

  // Start a new call
  const startCall = useCallback(async (
    conversationId: string,
    callType: "audio" | "video" = "video"
  ): Promise<string | null> => {
    if (!client) {
      await initializeClient();
    }

    try {
      const response = await videoService.initializeCall(conversationId, callType);

      if (!response.success || !response.data) {
        throw new Error("Failed to initialize call");
      }

      const { callId } = response.data;

      setState(prev => ({
        ...prev,
        isInCall: true,
        callId,
        callType,
        conversationId,
        error: null,
      }));

      return callId;
    } catch (error) {
      console.error("Failed to start call:", error);
      setState(prev => ({
        ...prev,
        error: error instanceof Error ? error.message : "Failed to start call",
      }));
      return null;
    }
  }, [client, initializeClient]);

  // Join an existing call
  const joinCall = useCallback(async (callId: string) => {
    if (!client) {
      await initializeClient();
    }

    try {
      const response = await videoService.getCallDetails(callId);

      if (!response.success || !response.data) {
        throw new Error("Failed to get call details");
      }

      const { conversationId, callType } = response.data;

      setState(prev => ({
        ...prev,
        isInCall: true,
        callId,
        callType: callType as "audio" | "video",
        conversationId,
        error: null,
      }));
    } catch (error) {
      console.error("Failed to join call:", error);
      setState(prev => ({
        ...prev,
        error: error instanceof Error ? error.message : "Failed to join call",
      }));
    }
  }, [client, initializeClient]);

  // End the current call
  const endCall = useCallback(() => {
    setState(prev => ({
      ...prev,
      isInCall: false,
      callId: null,
      callType: null,
      conversationId: null,
    }));
  }, []);

  // Initialize client lazily - only when needed, not on page load
  // Removed auto-initialization to prevent 404 errors when video service is not fully configured
  // useEffect(() => {
  //   if (isAuthenticated && user && !client) {
  //     initializeClient();
  //   }
  // }, [isAuthenticated, user, client, initializeClient]);

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      if (client) {
        client.disconnectUser();
      }
    };
  }, [client]);

  const contextValue: VideoCallContextType = {
    client,
    state,
    initializeClient,
    startCall,
    joinCall,
    endCall,
    isReady: state.isInitialized && !!client,
  };

  // Wrap with StreamVideo provider if client exists
  if (client) {
    return (
      <VideoCallContext.Provider value={contextValue}>
        <StreamVideo client={client}>
          {children}
        </StreamVideo>
      </VideoCallContext.Provider>
    );
  }

  return (
    <VideoCallContext.Provider value={contextValue}>
      {children}
    </VideoCallContext.Provider>
  );
}

export function useVideoCall() {
  const context = useContext(VideoCallContext);
  if (context === undefined) {
    throw new Error("useVideoCall must be used within a VideoCallProvider");
  }
  return context;
}

"use client";

import { useState, useEffect, useCallback, useRef } from "react";
import { motion } from "framer-motion";
import {
  MapPin,
  Crosshair,
  Loader2,
  CheckCircle,
  AlertCircle,
  RefreshCw,
  Navigation,
  ShieldCheck,
} from "lucide-react";
import LocationAutocomplete from "@/components/features/location/LocationAutocomplete";
import locationApiService, {
  type LocationSuggestion,
} from "@/features/map/services";

const DEFAULT_CENTER = { lat: 27.7172, lng: 85.3240 }; // Kathmandu, Nepal
const DEFAULT_ZOOM = 13;
const VERIFIED_DISTANCE_KM = 3;

export interface LocationData {
  locationName?: string;
  placeId?: string;
  coordinates: {
    lat: number;
    lng: number;
  };
  selectedCoordinates?: {
    lat: number;
    lng: number;
  };
  gpsCoordinates?: {
    lat: number;
    lng: number;
  };
  distanceKm?: number;
  gpsVerified?: boolean;
  trustScore?: number;
  accuracy: number;
  address: string;
  city: string;
  state: string;
  country: string;
  postalCode: string;
  capturedAt: string;
}

interface LocationPickerProps {
  onLocationSelect: (location: LocationData | null) => void;
  initialLocation?: LocationData | null;
  className?: string;
}

interface MapComponentProps {
  center: { lat: number; lng: number };
  markerPosition: { lat: number; lng: number };
  onMarkerDrag: (lat: number, lng: number) => void;
  onMapClick: (lat: number, lng: number) => void;
}

type LeafletContainerElement = HTMLDivElement & { _leaflet_id?: number };

const haversineDistanceKm = (
  lat1: number,
  lng1: number,
  lat2: number,
  lng2: number
): number => {
  const toRad = (deg: number) => (deg * Math.PI) / 180;
  const earthRadiusKm = 6371;
  const dLat = toRad(lat2 - lat1);
  const dLng = toRad(lng2 - lng1);

  const a =
    Math.sin(dLat / 2) * Math.sin(dLat / 2) +
    Math.cos(toRad(lat1)) * Math.cos(toRad(lat2)) *
      Math.sin(dLng / 2) * Math.sin(dLng / 2);

  const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
  return earthRadiusKm * c;
};

function MapComponent({
  center,
  markerPosition,
  onMarkerDrag,
  onMapClick,
}: MapComponentProps) {
  const mapRef = useRef<HTMLDivElement>(null);
  const mapInstanceRef = useRef<unknown>(null);
  const markerRef = useRef<unknown>(null);
  const [isMapReady, setIsMapReady] = useState(false);
  const onMarkerDragRef = useRef(onMarkerDrag);
  const onMapClickRef = useRef(onMapClick);

  useEffect(() => {
    onMarkerDragRef.current = onMarkerDrag;
  }, [onMarkerDrag]);

  useEffect(() => {
    onMapClickRef.current = onMapClick;
  }, [onMapClick]);

  useEffect(() => {
    if (!mapRef.current || mapInstanceRef.current) return;

    let disposed = false;
    const container = mapRef.current as LeafletContainerElement;

    const initMap = async () => {
      const L = (await import("leaflet")).default;
      await import("leaflet/dist/leaflet.css");

      if (disposed) return;

      delete (L.Icon.Default.prototype as { _getIconUrl?: unknown })._getIconUrl;
      L.Icon.Default.mergeOptions({
        iconRetinaUrl:
          "https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.9.4/images/marker-icon-2x.png",
        iconUrl:
          "https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.9.4/images/marker-icon.png",
        shadowUrl:
          "https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.9.4/images/marker-shadow.png",
      });

      const customIcon = L.divIcon({
        className: "custom-marker",
        html: `
          <div style="
            width: 40px;
            height: 40px;
            position: relative;
            transform: translate(-50%, -100%);
          ">
            <svg viewBox="0 0 40 52" fill="none" xmlns="http://www.w3.org/2000/svg">
              <path d="M20 0C8.954 0 0 8.954 0 20c0 14 20 32 20 32s20-18 20-32C40 8.954 31.046 0 20 0z" fill="#1D4ED8"/>
              <circle cx="20" cy="18" r="8" fill="white"/>
            </svg>
          </div>
        `,
        iconSize: [40, 52],
        iconAnchor: [20, 52],
      });

      // Leaflet stores instance metadata on the container element. Reset it for
      // StrictMode/HMR remounts to avoid "Map container is already initialized".
      if (container._leaflet_id) {
        delete container._leaflet_id;
      }
      container.innerHTML = "";

      const map = L.map(container, {
        center: [center.lat, center.lng],
        zoom: DEFAULT_ZOOM,
        zoomControl: false,
      });

      L.tileLayer("https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png", {
        attribution:
          '&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors',
        maxZoom: 19,
      }).addTo(map);

      L.control.zoom({ position: "topright" }).addTo(map);

      const marker = L.marker([markerPosition.lat, markerPosition.lng], {
        draggable: true,
        icon: customIcon,
      }).addTo(map);

      marker.on("dragend", () => {
        const pos = marker.getLatLng();
        onMarkerDragRef.current(pos.lat, pos.lng);
      });

      map.on("click", (e: { latlng: { lat: number; lng: number } }) => {
        const { lat, lng } = e.latlng;
        marker.setLatLng([lat, lng]);
        onMapClickRef.current(lat, lng);
      });

      if (disposed) {
        map.off();
        map.remove();
        return;
      }

      mapInstanceRef.current = map;
      markerRef.current = marker;
      setIsMapReady(true);
    };

    void initMap();

    return () => {
      disposed = true;
      const map = mapInstanceRef.current as { remove: () => void } | null;
      if (map) {
        const mapWithOff = map as { off?: () => void; remove: () => void };
        mapWithOff.off?.();
        map.remove();
        mapInstanceRef.current = null;
        markerRef.current = null;
      }

      container.innerHTML = "";
      if (container._leaflet_id) {
        delete container._leaflet_id;
      }
      setIsMapReady(false);
    };
  }, []);

  useEffect(() => {
    const marker = markerRef.current as { setLatLng: (latLng: [number, number]) => void } | null;
    if (marker && isMapReady) {
      marker.setLatLng([markerPosition.lat, markerPosition.lng]);
    }
  }, [markerPosition.lat, markerPosition.lng, isMapReady]);

  useEffect(() => {
    const map = mapInstanceRef.current as {
      setView: (centerValue: [number, number], zoom: number) => void;
    } | null;

    if (map && isMapReady) {
      map.setView([center.lat, center.lng], DEFAULT_ZOOM);
    }
  }, [center.lat, center.lng, isMapReady]);

  return (
    <div
      ref={mapRef}
      className="h-full w-full overflow-hidden rounded-xl"
      style={{ minHeight: "300px" }}
    />
  );
}

export default function LocationPicker({
  onLocationSelect,
  initialLocation,
  className = "",
}: LocationPickerProps) {
  const [status, setStatus] = useState<
    "idle" | "locating" | "geocoding" | "success" | "error"
  >("idle");
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const [center, setCenter] = useState(
    initialLocation?.coordinates || DEFAULT_CENTER
  );
  const [markerPosition, setMarkerPosition] = useState(
    initialLocation?.coordinates || DEFAULT_CENTER
  );
  const [locationData, setLocationData] = useState<LocationData | null>(
    initialLocation || null
  );
  const [accuracy, setAccuracy] = useState<number>(initialLocation?.accuracy || 0);
  const [selectedCoordinates, setSelectedCoordinates] = useState<
    { lat: number; lng: number } | undefined
  >(initialLocation?.selectedCoordinates || initialLocation?.coordinates);
  const [gpsCoordinates, setGpsCoordinates] = useState<
    { lat: number; lng: number } | undefined
  >(initialLocation?.gpsCoordinates);

  const buildAndEmitLocation = useCallback(
    async (
      selected: { lat: number; lng: number },
      meta?: { locationName?: string; placeId?: string }
    ) => {
      setStatus("geocoding");

      const geocoded = await locationApiService.reverseGeocode(selected.lat, selected.lng);
      const distanceKm =
        gpsCoordinates && selected
          ? haversineDistanceKm(
              selected.lat,
              selected.lng,
              gpsCoordinates.lat,
              gpsCoordinates.lng
            )
          : undefined;
      const gpsVerified =
        typeof distanceKm === "number" ? distanceKm <= VERIFIED_DISTANCE_KM : false;

      const trustScore =
        20 +
        (gpsVerified ? 40 : 0) +
        (accuracy > 0 && accuracy <= 100 ? 10 : 0);

      const newLocationData: LocationData = {
        ...(meta?.locationName ? { locationName: meta.locationName } : {}),
        ...(meta?.placeId ? { placeId: meta.placeId } : {}),
        coordinates: selected,
        selectedCoordinates: selected,
        ...(gpsCoordinates ? { gpsCoordinates } : {}),
        ...(typeof distanceKm === "number" ? { distanceKm } : {}),
        gpsVerified,
        trustScore,
        accuracy,
        address: geocoded.address,
        city: geocoded.city,
        state: geocoded.state,
        country: geocoded.country,
        postalCode: geocoded.postalCode,
        capturedAt: new Date().toISOString(),
      };

      setLocationData(newLocationData);
      onLocationSelect(newLocationData);
      setStatus("success");
    },
    [accuracy, gpsCoordinates, onLocationSelect]
  );

  const getCurrentLocation = useCallback(() => {
    if (!navigator.geolocation) {
      setErrorMessage("Geolocation is not supported by your browser");
      setStatus("error");
      return;
    }

    setStatus("locating");
    setErrorMessage(null);

    navigator.geolocation.getCurrentPosition(
      async (position) => {
        const { latitude, longitude, accuracy: rawAccuracy } = position.coords;
        const gpsPoint = { lat: latitude, lng: longitude };

        setAccuracy(rawAccuracy);
        setGpsCoordinates(gpsPoint);

        const finalSelected = selectedCoordinates || gpsPoint;
        setCenter(finalSelected);
        setMarkerPosition(finalSelected);

        await buildAndEmitLocation(finalSelected);
      },
      (error) => {
        let message = "Unable to get your location";
        switch (error.code) {
          case error.PERMISSION_DENIED:
            message =
              "Location permission denied. Please enable location access in your browser settings.";
            break;
          case error.POSITION_UNAVAILABLE:
            message = "Location information is unavailable. Please try again.";
            break;
          case error.TIMEOUT:
            message = "Location request timed out. Please try again.";
            break;
        }
        setErrorMessage(message);
        setStatus("error");
      },
      {
        enableHighAccuracy: true,
        timeout: 15000,
        maximumAge: 0,
      }
    );
  }, [buildAndEmitLocation, selectedCoordinates]);

  const handlePositionChange = useCallback(
    async (lat: number, lng: number) => {
      const selected = { lat, lng };
      setSelectedCoordinates(selected);
      setMarkerPosition(selected);
      setCenter(selected);
      await buildAndEmitLocation(selected);
    },
    [buildAndEmitLocation]
  );

  const handleAutocompleteSelect = useCallback(
    async (suggestion: LocationSuggestion) => {
      const selected = { lat: suggestion.lat, lng: suggestion.lng };
      setSelectedCoordinates(selected);
      setCenter(selected);
      setMarkerPosition(selected);

      await buildAndEmitLocation(selected, {
        locationName: suggestion.displayName,
        placeId: suggestion.placeId,
      });
    },
    [buildAndEmitLocation]
  );

  const clearLocation = useCallback(() => {
    setLocationData(null);
    setMarkerPosition(DEFAULT_CENTER);
    setCenter(DEFAULT_CENTER);
    setStatus("idle");
    setAccuracy(0);
    setSelectedCoordinates(undefined);
    setGpsCoordinates(undefined);
    onLocationSelect(null);
  }, [onLocationSelect]);

  return (
    <div className={`space-y-4 ${className}`}>
      <div className="rounded-2xl border border-slate-200 bg-linear-to-br from-slate-50 via-white to-blue-50 p-4 shadow-sm">
        <div className="flex items-center justify-between gap-3">
          <div className="flex items-center gap-3">
            <div className="flex h-10 w-10 items-center justify-center rounded-xl bg-blue-100">
              <MapPin className="h-5 w-5 text-blue-700" />
            </div>
            <div>
              <h3 className="text-sm font-semibold text-slate-900">Location Authenticity Check</h3>
              <p className="text-xs text-slate-500">
                Search your address, then confirm with live GPS for higher trust
              </p>
            </div>
          </div>

          <motion.button
            type="button"
            onClick={getCurrentLocation}
            disabled={status === "locating" || status === "geocoding"}
            whileTap={{ scale: 0.96 }}
            className={`inline-flex items-center gap-2 rounded-lg px-4 py-2 text-sm font-medium transition-all ${
              status === "locating" || status === "geocoding"
                ? "cursor-not-allowed bg-slate-100 text-slate-400"
                : "bg-blue-600 text-white shadow-md shadow-blue-600/30 hover:bg-blue-700"
            }`}
          >
            {status === "locating" || status === "geocoding" ? (
              <>
                <Loader2 className="h-4 w-4 animate-spin" />
                {status === "locating" ? "Locating..." : "Resolving..."}
              </>
            ) : (
              <>
                <Crosshair className="h-4 w-4" />
                Use Current GPS
              </>
            )}
          </motion.button>
        </div>

        <div className="mt-4 space-y-1">
          <p className="text-xs font-medium text-slate-600">Search and pick your address</p>
          <LocationAutocomplete onSelect={handleAutocompleteSelect} />
        </div>
      </div>

      {status === "error" && errorMessage && (
        <motion.div
          initial={{ opacity: 0, y: -8 }}
          animate={{ opacity: 1, y: 0 }}
          className="flex items-start gap-2 rounded-xl border border-red-200 bg-red-50 p-3"
        >
          <AlertCircle className="mt-0.5 h-4 w-4 shrink-0 text-red-500" />
          <div className="flex-1">
            <p className="text-sm text-red-600">{errorMessage}</p>
            <button
              type="button"
              onClick={getCurrentLocation}
              className="mt-1 text-xs text-red-600 underline"
            >
              Try again
            </button>
          </div>
        </motion.div>
      )}

      <div className="relative overflow-hidden rounded-xl border-2 border-slate-200 bg-slate-100">
        <div className="h-75">
          <MapComponent
            center={center}
            markerPosition={markerPosition}
            onMarkerDrag={handlePositionChange}
            onMapClick={handlePositionChange}
          />
        </div>

        {status === "idle" && !locationData && (
          <div className="absolute inset-0 flex items-center justify-center bg-black/45">
            <div className="px-6 text-center text-white">
              <Navigation className="mx-auto mb-3 h-12 w-12 opacity-80" />
              <p className="text-sm font-medium">Search address or select directly on map</p>
              <p className="mt-1 text-xs opacity-80">Then tap Use Current GPS for strong verification</p>
            </div>
          </div>
        )}

        {(status === "locating" || status === "geocoding") && (
          <div className="absolute inset-0 flex items-center justify-center bg-white/80">
            <div className="text-center">
              <Loader2 className="mx-auto mb-2 h-8 w-8 animate-spin text-blue-600" />
              <p className="text-sm text-slate-600">
                {status === "locating" ? "Getting GPS location..." : "Fetching formatted address..."}
              </p>
            </div>
          </div>
        )}
      </div>

      {locationData && status === "success" && (
        <motion.div
          initial={{ opacity: 0, y: 8 }}
          animate={{ opacity: 1, y: 0 }}
          className="space-y-3 rounded-xl border border-emerald-200 bg-emerald-50 p-4"
        >
          <div className="flex items-start justify-between">
            <div className="flex items-center gap-2 text-emerald-700">
              <CheckCircle className="h-5 w-5" />
              <span className="text-sm font-semibold">Location Captured</span>
            </div>
            <button
              type="button"
              onClick={clearLocation}
              className="text-xs text-slate-600 underline"
            >
              Clear
            </button>
          </div>

          <div className="rounded-lg border border-emerald-100 bg-white p-3">
            <p className="text-sm font-medium leading-relaxed text-slate-800">
              {locationData.address}
            </p>
            <div className="mt-2 flex flex-wrap gap-3 text-xs text-slate-500">
              <span>Lat: {locationData.coordinates.lat.toFixed(6)}</span>
              <span>Lng: {locationData.coordinates.lng.toFixed(6)}</span>
              {locationData.accuracy > 0 && <span>GPS Accuracy: ±{Math.round(locationData.accuracy)}m</span>}
              {typeof locationData.distanceKm === "number" && (
                <span>GPS Distance: {locationData.distanceKm.toFixed(2)} km</span>
              )}
            </div>
          </div>

          {typeof locationData.distanceKm === "number" && (
            <div
              className={`flex items-center gap-2 rounded-lg border p-2 text-xs ${
                locationData.gpsVerified
                  ? "border-emerald-300 bg-emerald-100 text-emerald-800"
                  : "border-amber-300 bg-amber-100 text-amber-800"
              }`}
            >
              <ShieldCheck className="h-4 w-4" />
              {locationData.gpsVerified
                ? "GPS and selected location match. Auto-verification confidence is high."
                : `GPS and selected location differ by over ${VERIFIED_DISTANCE_KM} km. Admin review will validate.`}
            </div>
          )}

          <div className="flex items-center gap-2 text-xs text-emerald-700">
            <RefreshCw className="h-3.5 w-3.5" />
            <span>Drag marker or click map to fine-tune location anytime</span>
          </div>
        </motion.div>
      )}

      <div className="flex items-start gap-2 rounded-xl border border-blue-100 bg-blue-50 p-3">
        <MapPin className="mt-0.5 h-4 w-4 shrink-0 text-blue-500" />
        <p className="text-xs text-blue-700">
          Your location evidence is encrypted and used only for account trust and safety checks.
        </p>
      </div>
    </div>
  );
}

'use client';

import { useEffect, useRef } from 'react';
import type { Coordinates } from '../types';
import { MAP_CONFIG } from '../types';

interface MapViewProps {
  center: Coordinates;
  zoom?: number;
  marker?: Coordinates;
  className?: string;
}

export function MapView({ center, zoom = MAP_CONFIG.DEFAULT_ZOOM, marker, className }: MapViewProps) {
  const mapRef = useRef<HTMLDivElement>(null);
  const mapInstanceRef = useRef<unknown>(null);
  const markerRef = useRef<unknown>(null);

  useEffect(() => {
    if (!mapRef.current || mapInstanceRef.current) {
      return;
    }

    const initMap = async () => {
      const L = (await import('leaflet')).default;
      await import('leaflet/dist/leaflet.css');

      delete (L.Icon.Default.prototype as { _getIconUrl?: unknown })._getIconUrl;
      L.Icon.Default.mergeOptions({
        iconRetinaUrl: 'https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.9.4/images/marker-icon-2x.png',
        iconUrl: 'https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.9.4/images/marker-icon.png',
        shadowUrl: 'https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.9.4/images/marker-shadow.png',
      });

      const map = L.map(mapRef.current!, {
        center: [center.lat, center.lng],
        zoom,
        zoomControl: true,
      });

      L.tileLayer(MAP_CONFIG.TILE_URL, {
        attribution: MAP_CONFIG.TILE_ATTRIBUTION,
        maxZoom: MAP_CONFIG.MAX_ZOOM,
      }).addTo(map);

      if (marker) {
        markerRef.current = L.marker([marker.lat, marker.lng]).addTo(map);
      }

      mapInstanceRef.current = map;
    };

    initMap();

    return () => {
      if (mapInstanceRef.current) {
        try {
          const map = mapInstanceRef.current as any;
          if (map && typeof map.remove === 'function') {
            map.remove();
          }
        } catch (error) {
          console.error('Error removing map instance:', error);
        }
      }
      mapInstanceRef.current = null;
      markerRef.current = null;
    };
  }, [center.lat, center.lng, marker, zoom]);

  useEffect(() => {
    const map = mapInstanceRef.current as {
      setView: (centerValue: [number, number], zoomValue?: number) => void;
    } | null;
    const mapMarker = markerRef.current as {
      setLatLng: (position: [number, number]) => void;
    } | null;

    if (map) {
      map.setView([center.lat, center.lng], zoom);
    }

    if (marker && mapMarker) {
      mapMarker.setLatLng([marker.lat, marker.lng]);
    }
  }, [center.lat, center.lng, marker, zoom]);

  return (
    <div
      ref={mapRef}
      className={className || 'h-full w-full min-h-65 overflow-hidden rounded-lg'}
    />
  );
}

/**
 * Admin Dashboard Map
 * Displays all caregivers with clustering, filtering, and statistics
 * Optimized for large datasets with performance in mind
 */

'use client';

import { useState, useEffect, useCallback, useRef } from 'react';
import { motion } from 'framer-motion';
import { BaseMap } from './BaseMap';
import { roleColors } from './mapConstants';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/Card';
import { Select } from '@/components/ui/Select';
import type { CaregiverLocation, CaregiverRole } from '@/types/map.types';
import { Users, UserCheck, UserX, MapPin, TrendingUp } from 'lucide-react';
import { cn } from '@/lib/utils';
import type L from 'leaflet';

export interface AdminDashboardMapProps {
  /** Array of all caregivers */
  caregivers: CaregiverLocation[];
  /** Default center for map */
  defaultCenter: { latitude: number; longitude: number };
  /** Callback when caregiver marker is clicked */
  onCaregiverClick?: (caregiver: CaregiverLocation) => void;
  /** Additional className */
  className?: string;
}

type FilterStatus = 'all' | 'active' | 'inactive';
type FilterRole = 'all' | CaregiverRole;

export function AdminDashboardMap({
  caregivers,
  defaultCenter,
  onCaregiverClick,
  className,
}: AdminDashboardMapProps) {
  const [mapInstance, setMapInstance] = useState<L.Map | null>(null);
  const markerClusterGroupRef = useRef<L.MarkerClusterGroup | null>(null);
  const [filterStatus, setFilterStatus] = useState<FilterStatus>('all');
  const [filterRole, setFilterRole] = useState<FilterRole>('all');
  const [filteredCaregivers, setFilteredCaregivers] = useState(caregivers);
  const leafletRef = useRef<typeof L | null>(null);

  // Filter caregivers based on status and role
  useEffect(() => {
    let filtered = caregivers;

    if (filterStatus !== 'all') {
      filtered = filtered.filter((c) =>
        filterStatus === 'active' ? c.isActive : !c.isActive
      );
    }

    if (filterRole !== 'all') {
      filtered = filtered.filter((c) => c.role === filterRole);
    }

    setFilteredCaregivers(filtered);
  }, [caregivers, filterStatus, filterRole]);

  // Setup markers and clustering
  useEffect(() => {
    if (!mapInstance) return;

    const setupMarkers = async () => {
      // Dynamically import Leaflet and marker cluster
      if (!leafletRef.current) {
        leafletRef.current = (await import('leaflet')).default;
        await import('leaflet.markercluster/dist/MarkerCluster.css');
        await import('leaflet.markercluster/dist/MarkerCluster.Default.css');
        await import('leaflet.markercluster');
      }
      const L = leafletRef.current;

      // Remove existing cluster group
      if (markerClusterGroupRef.current) {
        mapInstance.removeLayer(markerClusterGroupRef.current);
      }

      // Create new marker cluster group with custom options
      const clusterGroup = L.markerClusterGroup({
        chunkedLoading: true,
        spiderfyOnMaxZoom: true,
        showCoverageOnHover: true,
        zoomToBoundsOnClick: true,
        maxClusterRadius: 60,
        iconCreateFunction: (cluster) => {
          const markers = cluster.getAllChildMarkers();
          const activeCount = markers.filter((m: any) => m.options.isActive).length;
          const size = 50;

          return L.divIcon({
            html: `
              <div style="
                width: ${size}px;
                height: ${size}px;
                background: linear-gradient(135deg, #4461F2 0%, #8B54F7 100%);
                border-radius: 50%;
                border: 3px solid white;
                box-shadow: 0 4px 6px -1px rgb(0 0 0 / 0.1), 0 2px 4px -2px rgb(0 0 0 / 0.1);
                display: flex;
                flex-direction: column;
                align-items: center;
                justify-content: center;
                color: white;
                font-weight: bold;
              ">
                <div style="font-size: 18px;">${markers.length}</div>
                <div style="font-size: 9px; margin-top: -2px;">${activeCount} active</div>
              </div>
            `,
            className: 'custom-cluster-icon',
            iconSize: [size, size],
          });
        },
      });

      // Add markers to cluster group
      for (const caregiver of filteredCaregivers) {
        const color = roleColors[caregiver.role] || '#4461F2';
        const isActive = caregiver.isActive !== undefined ? caregiver.isActive : true;
        const size = 36;

        const iconHtml = `
          <div style="
            width: ${size}px;
            height: ${size}px;
            background: ${isActive ? color : '#9CA3AF'};
            border-radius: 50% 50% 50% 0;
            transform: rotate(-45deg);
            border: 3px solid white;
            box-shadow: 0 4px 6px -1px rgb(0 0 0 / 0.1), 0 2px 4px -2px rgb(0 0 0 / 0.1);
            display: flex;
            align-items: center;
            justify-content: center;
          ">
            <div style="
              transform: rotate(45deg);
              color: white;
              font-size: ${size * 0.5}px;
              font-weight: bold;
            ">📍</div>
          </div>
        `;

        const icon = L.divIcon({
          html: iconHtml,
          className: 'custom-marker-icon',
          iconSize: [size, size],
          iconAnchor: [size / 2, size],
          popupAnchor: [0, -size],
        });

        const marker = L.marker([caregiver.latitude, caregiver.longitude], {
          icon,
          isActive: caregiver.isActive,
        } as any);

        // Create detailed popup
        const popupContent = createAdminPopupContent(caregiver);
        marker.bindPopup(popupContent, {
          maxWidth: 320,
          className: 'admin-custom-popup',
        });

        marker.on('click', () => {
          onCaregiverClick?.(caregiver);
        });

        clusterGroup.addLayer(marker);
      }

      mapInstance.addLayer(clusterGroup);
      markerClusterGroupRef.current = clusterGroup;

      // Fit bounds if we have caregivers
      if (filteredCaregivers.length > 0) {
        const bounds = L.latLngBounds(
          filteredCaregivers.map((c) => [c.latitude, c.longitude] as L.LatLngExpression)
        );
        mapInstance.fitBounds(bounds, { padding: [50, 50], maxZoom: 15 });
      }
    };

    setupMarkers();

    return () => {
      if (markerClusterGroupRef.current && mapInstance) {
        mapInstance.removeLayer(markerClusterGroupRef.current);
      }
    };
  }, [mapInstance, filteredCaregivers, onCaregiverClick]);

  const handleMapReady = useCallback((map: L.Map) => {
    setMapInstance(map);
  }, []);

  // Calculate statistics
  const stats = calculateStatistics(filteredCaregivers);

  return (
    <div className={cn('space-y-4', className)}>
      {/* Statistics Cards */}
      <div className="grid gap-4 md:grid-cols-4">
        <StatCard
          icon={Users}
          label="Total Caregivers"
          value={stats.total}
          bgColor="bg-blue-50"
          iconColor="text-blue-600"
        />
        <StatCard
          icon={UserCheck}
          label="Active"
          value={stats.active}
          bgColor="bg-green-50"
          iconColor="text-green-600"
        />
        <StatCard
          icon={UserX}
          label="Inactive"
          value={stats.inactive}
          bgColor="bg-orange-50"
          iconColor="text-orange-600"
        />
        <StatCard
          icon={TrendingUp}
          label="Avg Rating"
          value={stats.avgRating.toFixed(1)}
          bgColor="bg-purple-50"
          iconColor="text-purple-600"
        />
      </div>

      {/* Filters */}
      <Card>
        <CardContent className="p-4">
          <div className="flex flex-wrap items-center gap-4">
            <div className="flex items-center gap-2 text-sm text-neutral-600">
              <MapPin className="w-4 h-4" />
              <span className="font-medium">
                Showing {filteredCaregivers.length} of {caregivers.length} caregivers
              </span>
            </div>

            <div className="flex-1" />

            <div className="flex items-center gap-2">
              <label className="text-sm font-medium text-neutral-700">Status:</label>
              <Select
                value={filterStatus}
                onChange={(e) => setFilterStatus(e.target.value as FilterStatus)}
                className="w-[120px]"
              >
                <option value="all">All</option>
                <option value="active">Active</option>
                <option value="inactive">Inactive</option>
              </Select>
            </div>

            <div className="flex items-center gap-2">
              <label className="text-sm font-medium text-neutral-700">Role:</label>
              <Select
                value={filterRole}
                onChange={(e) => setFilterRole(e.target.value as FilterRole)}
                className="w-[180px]"
              >
                <option value="all">All Roles</option>
                <option value="Nurse">Nurse</option>
                <option value="Child Care">Child Care</option>
                <option value="Elder Care">Elder Care</option>
                <option value="Physiotherapy">Physiotherapy</option>
                <option value="Personal Care">Personal Care</option>
                <option value="Disability Support">Disability Support</option>
                <option value="Mental Health Support">Mental Health Support</option>
              </Select>
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Map */}
      <motion.div
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.3 }}
      >
        <Card>
          <CardHeader>
            <CardTitle className="text-xl">Geographic Distribution</CardTitle>
          </CardHeader>
          <CardContent>
            <BaseMap
              center={defaultCenter}
              zoom={12}
              height="h-[600px]"
              onMapReady={handleMapReady}
            />
          </CardContent>
        </Card>
      </motion.div>

      {/* Role Distribution */}
      <Card>
        <CardHeader>
          <CardTitle className="text-lg">Distribution by Role</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="grid gap-2 sm:grid-cols-2 lg:grid-cols-4">
            {Object.entries(stats.byRole).map(([role, count]) => (
              <div
                key={role}
                className="flex items-center justify-between p-3 rounded-lg bg-neutral-50"
              >
                <div className="flex items-center gap-2">
                  <div
                    className="w-3 h-3 rounded-full"
                    style={{ background: roleColors[role as CaregiverRole] || '#4461F2' }}
                  />
