            font-size: ${size * 0.5}px;
            font-weight: bold;
          ">📍</div>
        </div>
      `;

      const icon = L.divIcon({
        html: iconHtml,
        className: 'custom-marker-icon',
        iconSize: [size, size],
        iconAnchor: [size / 2, size],
        popupAnchor: [0, -size],
      });

      const newMarker = L.marker([baseLocation.latitude, baseLocation.longitude], {
        icon,
      })
        .addTo(map)
        .bindPopup('<strong>Your Base Location</strong>', { closeButton: false })
        .openPopup();

      void newMarker;

      // Add initial service circle
      const circle = L.circle([baseLocation.latitude, baseLocation.longitude], {
        radius: radius * 1000, // Convert km to meters
        color: '#4461F2',
        fillColor: '#4461F2',
        fillOpacity: 0.15,
        weight: 2,
      }).addTo(map);

      setServiceCircle(circle);

      // Fit bounds to circle
      map.fitBounds(circle.getBounds(), { padding: [50, 50] });
    },
    [baseLocation, radius]
  );

  // Update circle when radius changes
  useEffect(() => {
    if (!mapInstance || !serviceCircle) return;

    try {
      serviceCircle.setRadius(radius * 1000);
      const bounds = serviceCircle.getBounds();
      if (bounds) {
        mapInstance.fitBounds(bounds, { padding: [50, 50] });
      }
    } catch {
      // Circle may not be attached to map yet during re-renders
    }
  }, [radius, mapInstance, serviceCircle]);

  const handleRadiusChange = (newRadius: number) => {
    setRadius(newRadius);
    onRadiusChange?.(newRadius);
  };

  return (
    <motion.div
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.3 }}
      className={cn('space-y-4', className)}
    >
      <Card>
        <CardHeader>
          <CardTitle className="text-xl">Set Your Service Area</CardTitle>
          <p className="text-sm text-neutral-500 mt-1">
            Define how far you're willing to travel for care services
          </p>
        </CardHeader>
        <CardContent className="space-y-6">
          {/* Radius Slider */}
          <div className="space-y-3">
            <div className="flex items-center justify-between">
              <label className="text-sm font-medium text-neutral-700">Service Radius</label>
              <span className="text-2xl font-bold text-blue-600">{radius} km</span>
            </div>
            <Slider
              min={1}
              max={50}
              step={1}
              value={radius}
              onValueChange={handleRadiusChange}
              className="w-full"
            />
            <div className="flex justify-between text-xs text-neutral-500">
              <span>1 km</span>
              <span>50 km</span>
            </div>
          </div>

          {/* Map */}
          <BaseMap
            center={baseLocation}
            zoom={12}
            height="h-[400px]"
            onMapReady={handleMapReady}
            className="rounded-lg"
          />

          {/* Info Card */}
          <div className="p-4 bg-blue-50 rounded-lg border border-blue-100">
            <div className="flex items-start gap-3">
              <MapPin className="w-5 h-5 text-blue-600 shrink-0 mt-0.5" />
              <div className="flex-1 text-sm">
                <p className="font-medium text-blue-900">Coverage Area</p>
                <p className="text-blue-700 mt-1">
                  You'll be visible to care seekers within {radius} km of your base location.
                  Larger radius means more opportunities but longer travel times.
                </p>
              </div>
            </div>
          </div>
        </CardContent>
      </Card>
    </motion.div>
  );
}

// ============================================
// USE GEOLOCATION HOOK
// Browser geolocation with status tracking
// ============================================

'use client';

import { useState, useCallback } from 'react';
import type { Coordinates } from '../types';

type GeolocationStatus = 'idle' | 'loading' | 'success' | 'error';

interface GeolocationState {
  coordinates: Coordinates | null;
  accuracy: number | null;
  status: GeolocationStatus;
  error: string | null;
}

interface UseGeolocationOptions {
  enableHighAccuracy?: boolean;
  timeout?: number;
  maximumAge?: number;
}

interface UseGeolocationReturn extends GeolocationState {
  getCurrentPosition: () => void;
  clearPosition: () => void;
}

const defaultOptions: UseGeolocationOptions = {
  enableHighAccuracy: true,
  timeout: 15000,
  maximumAge: 0,
};

export function useGeolocation(options: UseGeolocationOptions = {}): UseGeolocationReturn {
  const [state, setState] = useState<GeolocationState>({
    coordinates: null,
    accuracy: null,
    status: 'idle',
    error: null,
  });

  const mergedOptions = { ...defaultOptions, ...options };

  const getCurrentPosition = useCallback(() => {
    if (!navigator.geolocation) {
      setState((prev) => ({
        ...prev,
        status: 'error',
        error: 'Geolocation is not supported by your browser',
      }));
      return;
    }

    setState((prev) => ({ ...prev, status: 'loading', error: null }));

    navigator.geolocation.getCurrentPosition(
      (position) => {
        setState({
          coordinates: {
            lat: position.coords.latitude,
            lng: position.coords.longitude,
          },
          accuracy: position.coords.accuracy,
          status: 'success',
          error: null,
        });
      },
      (error) => {
        let errorMessage = 'Unable to get your location';

        switch (error.code) {
          case error.PERMISSION_DENIED:
            errorMessage = 'Location permission denied. Please enable location access.';
            break;
          case error.POSITION_UNAVAILABLE:
            errorMessage = 'Location information is unavailable.';
            break;
          case error.TIMEOUT:
            errorMessage = 'Location request timed out.';
            break;
        }

        setState((prev) => ({
          ...prev,
          status: 'error',
          error: errorMessage,
        }));
      },
      mergedOptions
    );
  }, [mergedOptions]);

  const clearPosition = useCallback(() => {
    setState({
      coordinates: null,
      accuracy: null,
      status: 'idle',
      error: null,
    });
  }, []);

  return {
    ...state,
    getCurrentPosition,
    clearPosition,
  };
}

