// ============================================
// USE SOCKET — Real-time Hook for CareConnect
// Standalone singleton hook for booking/system
// event subscriptions via socket.io-client v4.
//
// NOTE: This hook is separate from the
// SocketContext used by the chat subsystem.
// Import from "@/hooks" (not "@/context") when
// subscribing to SYSTEM_EVENTS.
// ============================================

"use client";

import { useEffect, useRef, useState, useCallback } from "react";
import { io, Socket } from "socket.io-client";

// ─────────────────────────────────────────────
// SYSTEM EVENTS — mirrors backend event names
// ─────────────────────────────────────────────
export const SYSTEM_EVENTS = {
  BOOKING_CREATED: "BOOKING_CREATED",
  BOOKING_ACCEPTED: "BOOKING_ACCEPTED",
  BOOKING_AGREEMENT_GENERATED: "BOOKING_AGREEMENT_GENERATED",
  BOOKING_AGREEMENT_ACCEPTED: "BOOKING_AGREEMENT_ACCEPTED",
  BOOKING_PAYMENT_COMPLETED: "BOOKING_PAYMENT_COMPLETED",
  BOOKING_PAYMENT_FAILED: "BOOKING_PAYMENT_FAILED",
  BOOKING_CONFIRMED: "BOOKING_CONFIRMED",
  BOOKING_ACTIVE: "BOOKING_ACTIVE",
  BOOKING_COMPLETED: "BOOKING_COMPLETED",
  BOOKING_CANCELLED: "BOOKING_CANCELLED",
  TRACKING_SUBMITTED: "TRACKING_SUBMITTED",
  TRACKING_FLAGGED: "TRACKING_FLAGGED",
  TRACKING_MISSED: "TRACKING_MISSED",
  DISPUTE_CREATED: "DISPUTE_CREATED",
  DISPUTE_RESOLVED: "DISPUTE_RESOLVED",
  DISPUTE_UPDATED: "DISPUTE_UPDATED",
  SYSTEM_STATS_UPDATED: "SYSTEM_STATS_UPDATED",
  NOTIFICATION_CREATED: "NOTIFICATION_CREATED",
} as const;

export type SystemEvent = (typeof SYSTEM_EVENTS)[keyof typeof SYSTEM_EVENTS];

// ─────────────────────────────────────────────
// TYPE HELPERS
// ─────────────────────────────────────────────
type EventHandler = (...args: unknown[]) => void;

interface TrackedSubscription {
  event: string;
  handler: EventHandler;
}

// ─────────────────────────────────────────────
// MODULE-LEVEL SINGLETON STATE
// Reference counting ensures the socket lives
// exactly as long as there are active consumers.
// ─────────────────────────────────────────────

/** Derive socket server URL from the API URL. Strips trailing /api path. */
function resolveSocketUrl(): string {
  const apiUrl = process.env.NEXT_PUBLIC_API_URL || "http://localhost:5000";
  // If the API URL ends with /api or /api/, strip it so we connect to the root.
  return apiUrl.replace(/\/api\/?$/, "");
}

/** Read the access token from localStorage, trying the primary key then fallback. */
function readToken(): string | null {
  if (typeof window === "undefined") return null;
  // Primary key as specified in task; fallback to the project's canonical key.
  return (
    localStorage.getItem("accessToken") ||
    localStorage.getItem("careconnect_token") ||
    null
  );
}

let _globalSocket: Socket | null = null;
let _consumerCount = 0;

/**
 * Increments the consumer reference count and returns the shared socket instance.
 * Creates a new socket if one does not yet exist.
 * Returns null when there is no auth token (unauthenticated user).
 */
function acquireSocket(): Socket | null {
  if (typeof window === "undefined") return null;

  const token = readToken();
  if (!token) return null; // unauthenticated — do not create socket

  _consumerCount++;

  if (!_globalSocket || _globalSocket.disconnected) {
    const url = resolveSocketUrl();

    _globalSocket = io(url, {
      auth: { token },
      transports: ["websocket", "polling"],
      reconnection: true,
      reconnectionAttempts: 5,
      reconnectionDelay: 1_000,
      reconnectionDelayMax: 10_000,
      timeout: 20_000,
      // Don't auto-connect; we'll call connect() after wiring listeners.
      autoConnect: false,
    });

    _globalSocket.connect();
  }

  return _globalSocket;
}

/**
 * Decrements the consumer count and disconnects + destroys the singleton
 * when the last consumer unmounts.
 */
function releaseSocket(): void {
  _consumerCount = Math.max(0, _consumerCount - 1);

  if (_consumerCount === 0 && _globalSocket) {
    _globalSocket.disconnect();
    _globalSocket.removeAllListeners();
    _globalSocket = null;
  }
}

// ─────────────────────────────────────────────
// PRIMARY HOOK: useSocket
// ─────────────────────────────────────────────

export interface UseSocketReturn {
  /** The underlying socket.io Socket instance, or null before connected. */
  socket: Socket | null;
  /** True when the socket is currently connected to the server. */
  connected: boolean;
  /**
   * Subscribe to a socket event.
   * All subscriptions added via this function are automatically removed
   * when the calling component unmounts.
   */
  on: (event: string, handler: EventHandler) => void;
  /**
   * Emit an event to the server.
   * Silently drops the call if the socket is not connected.
   */
  emit: (event: string, data?: unknown) => void;
}

export function useSocket(): UseSocketReturn {
  const socketRef = useRef<Socket | null>(null);
  const subscriptionsRef = useRef<TrackedSubscription[]>([]);
  const [connected, setConnected] = useState(false);
  // A lightweight counter state so consumers re-render once the socket mounts.
  const [, setTick] = useState(0);

  useEffect(() => {
    const socket = acquireSocket();
    socketRef.current = socket;

    // Trigger one re-render so socketRef.current is available to callers.
    setTick((n) => n + 1);

    if (!socket) {
      // No token / SSR — nothing to clean up.
      return;
    }

    // Sync initial connection state.
    setConnected(socket.connected);

    const handleConnect = () => setConnected(true);
    const handleDisconnect = () => setConnected(false);
    const handleConnectError = (err: Error) => {
      console.warn("[useSocket] Connection error:", err.message);
    };

    socket.on("connect", handleConnect);
    socket.on("disconnect", handleDisconnect);
    socket.on("connect_error", handleConnectError);

    return () => {
      // Remove core lifecycle listeners.
      socket.off("connect", handleConnect);
      socket.off("disconnect", handleDisconnect);
      socket.off("connect_error", handleConnectError);

      // Remove ALL event subscriptions that were registered via on().
      for (const { event, handler } of subscriptionsRef.current) {
        socket.off(event, handler);
      }
      subscriptionsRef.current = [];

      // Release the singleton reference.
      releaseSocket();
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const on = useCallback((event: string, handler: EventHandler): void => {
    const socket = socketRef.current;
    if (!socket) {
      if (process.env.NODE_ENV === "development") {
        console.warn(`[useSocket] on("${event}"): socket not yet available`);
      }
      return;
    }
    socket.on(event, handler);
    // Track so we can auto-remove on unmount.
    subscriptionsRef.current.push({ event, handler });
  }, []);

  const emit = useCallback((event: string, data?: unknown): void => {
    const socket = socketRef.current;
    if (!socket?.connected) {
      if (process.env.NODE_ENV === "development") {
        console.warn(`[useSocket] emit("${event}"): socket not connected`);
      }
      return;
    }
    socket.emit(event, data);
  }, []);

  return {
    socket: socketRef.current,
    connected,
    on,
    emit,
  };
}

// ─────────────────────────────────────────────
// CONVENIENCE HOOK: useSocketEvent
// Subscribes to a single event with stable
// handler semantics (handler ref never stales).
// ─────────────────────────────────────────────

/**
 * Subscribe to a single socket event.
 *
 * @example
 * useSocketEvent(SYSTEM_EVENTS.BOOKING_CONFIRMED, (payload) => {
 *   toast.success(`Booking ${payload.bookingNumber} confirmed!`);
 * });
 *
 * The handler is always up-to-date (stored in a ref), so you don't need
 * to list it in dependency arrays. The subscription is removed automatically
 * when the component unmounts.
 */
export function useSocketEvent(event: string, handler: EventHandler): void {
  const { socket } = useSocket();
  // Keep the latest handler in a ref so the subscription never goes stale.
  const handlerRef = useRef<EventHandler>(handler);
  handlerRef.current = handler;

  useEffect(() => {
    if (!socket) return;

    const stableHandler: EventHandler = (...args) => {
      handlerRef.current(...args);
    };

    socket.on(event, stableHandler);

    return () => {
      socket.off(event, stableHandler);
    };
  }, [socket, event]);
}

// ─────────────────────────────────────────────
// RE-EXPORTS for convenience
// ─────────────────────────────────────────────
export type { Socket };

// ============================================
// OFFLINE MESSAGE QUEUE
// Handles message queueing when socket is disconnected
// ============================================

interface QueuedMessage {
  id: string;
  conversationId: string;
  content: string;
  type?: string;
  metadata?: any;
  timestamp: number;
  retryCount: number;
  maxRetries: number;
}

const STORAGE_KEY = 'careconnect_message_queue';
const MAX_RETRIES = 3;
const RETRY_DELAY_MS = 2000;

class OfflineMessageQueue {
  private queue: QueuedMessage[] = [];
  private processing = false;

  constructor() {
    this.loadFromStorage();
  }

  add(conversationId: string, content: string, type = 'text', metadata = {}) {
    const message: QueuedMessage = {
      id: `msg_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
      conversationId,
      content,
      type,
      metadata,
      timestamp: Date.now(),
      retryCount: 0,
      maxRetries: MAX_RETRIES,
    };

    this.queue.push(message);
    this.saveToStorage();
    return message.id;
  }

  getAll(): QueuedMessage[] {
    return [...this.queue];
  }

  getByConversation(conversationId: string): QueuedMessage[] {
    return this.queue.filter(msg => msg.conversationId === conversationId);
  }

  remove(messageId: string) {
    this.queue = this.queue.filter(msg => msg.id !== messageId);
    this.saveToStorage();
  }

  clear() {
    this.queue = [];
    this.saveToStorage();
  }

  async process(sendFunction: (msg: QueuedMessage) => Promise<boolean>) {
    if (this.processing || this.queue.length === 0) return;

    this.processing = true;
    const messagesToProcess = [...this.queue];
    
    for (const message of messagesToProcess) {
      try {
        const success = await sendFunction(message);
        
        if (success) {
          this.remove(message.id);
        } else {
          message.retryCount++;
          
          if (message.retryCount >= message.maxRetries) {
            this.remove(message.id);
          } else {
            const delay = RETRY_DELAY_MS * Math.pow(2, message.retryCount);
            await new Promise(resolve => setTimeout(resolve, delay));
          }
        }
      } catch (error) {
        message.retryCount++;
        if (message.retryCount >= message.maxRetries) {
          this.remove(message.id);
        }
      }
    }

    this.saveToStorage();
    this.processing = false;
  }

  private loadFromStorage() {
    try {
      const stored = localStorage.getItem(STORAGE_KEY);
      if (stored) {
        this.queue = JSON.parse(stored);
        const oneDayAgo = Date.now() - 24 * 60 * 60 * 1000;
        this.queue = this.queue.filter(msg => msg.timestamp > oneDayAgo);
      }
    } catch (error) {
      this.queue = [];
    }
  }

  private saveToStorage() {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(this.queue));
    } catch (error) {
      console.error('Failed to save queue:', error);
    }
  }

  size(): number {
    return this.queue.length;
  }
}

export default OfflineMessageQueue;
export type { QueuedMessage };

